DG.put("krisnaavtaar/27",{"n":27,"title":"ਅਥ ਰਾਸ ਮੰਡਲ","title_roman":"Ath raas mandal","page":403,"blocks":[{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":403},{"type":"verse","number":[441],"number_text":"੪੪੧।","page":403,"lines":[{"gurmukhi":"ਜਬ ਆਈ ਹੈ ਕਾਤਿਕ ਕੀ ਰੁਤਿ ਸੀਤਲ ਕਾਨ੍ਹ ਤਬੈ ਅਤਿ ਹੀ ਰਸੀਆ।","roman":"Jab aaee hai kaatik kee ruti seetal kaanh tabai ati hee raseeaa |","meaning_en":"","page":403},{"gurmukhi":"ਸੰਗਿ ਗੋਪਿਨ ਖੇਲ ਬਿਚਾਰ ਕਰਿਓ ਜੁ ਹੁਤੋ ਭਗਵਾਨ ਮਹਾ ਜਸੀਆ।","roman":"Sangi gopin khel bichaar kario ju huto bhagvaan mahaa jaseeaa |","meaning_en":"","page":403},{"gurmukhi":"ਅਪਵਿਤ੍ਰਨ ਲੋਗਨ ਕੇ ਜਿਹ ਕੇ ਪਗਿ ਲਾਗਤ ਪਾਪ ਸਭੈ ਨਸੀਆ।","roman":"Apvitran logan ke jih ke pagi laagat paap sabhai naseeaa |","meaning_en":"","page":403},{"gurmukhi":"ਤਿਹ ਕੋ ਸੁਨਿ ਤ੍ਰੀਯਨ ਕੇ ਸੰਗਿ ਖੇਲ ਨਿਵਾਰਹੁ ਕਾਮ ਇਹੈ ਬਸੀਆ। ੪੪੧।","roman":"Tih ko suni treeyan ke sangi khel nivaarhu kaam ihai baseeaa | 441 |","meaning_en":"","page":403}]},{"type":"verse","number":[442],"number_text":"੪੪੨।","page":403,"lines":[{"gurmukhi":"ਆਨਨ ਜਾਹਿ ਨਿਸਾਪਤਿ ਸੋ ਦ੍ਰਿਗ ਕੋਮਲ ਹੈ ਕਮਲਾ ਦਲ ਕੈਸੇ।","roman":"Aanan jaahi nisaapti so drig komal hai kamlaa dal kaise |","meaning_en":"","page":403},{"gurmukhi":"ਹੈ ਭਰੁਟੇ ਧਨੁ ਸੇ ਬਰਨੀ ਸਰ ਦੂਰ ਕਰੈ ਤਨ ਕੇ ਦੁਖਰੈ ਸੇ।","roman":"Hai bharute dhanu se barnee sar door karai tan ke dukhrai se |","meaning_en":"","page":403},{"gurmukhi":"ਕਾਮ ਕੀ ਸਾਨ ਕੇ ਸਾਥ ਘਸੇ ਦੁਖ ਸਾਧਨ ਕਟਬੇ ਕਹੁ ਤੈਸੇ।","roman":"Kaam kee saan ke saath ghase dukh saadhan katbe kahu taise |","meaning_en":"","page":403},{"gurmukhi":"ਕਉਲ ਕੇ ਪਤ੍ਰ ਕਿਧੋ ਸੀਸ ਸਾਥ ਲਗੇ ਕਬਿ ਸੁੰਦਰ ਸ੍ਯਾਮ ਅਰੈ ਸੇ। ੪੪੨।","roman":"Kaul ke patr kidho sees saath lage kabi sundar syaam arai se | 442 |","meaning_en":"","page":403}]},{"type":"verse","number":[443],"number_text":"੪੪੩।","page":403,"lines":[{"gurmukhi":"ਬਧਿਕ ਹੈ ਟਟੀਆ ਬਰੁਨੀ ਧਰ ਕੋਰਨ ਕੀ ਦੁਤਿ ਸਾਇਕ ਸਾਧੇ।","roman":"Badhik hai tateeaa barunee dhar koran kee duti saaik saadhe |","meaning_en":"","page":403},{"gurmukhi":"ਠਾਢੇ ਹੈ ਕਾਨ੍ਹ ਕਿਧੋ ਬਨ ਮੈ ਤਨ ਪੈ ਸਿਰ ਪੈ ਅੰਬੁਵਾ ਰੰਗ ਬਾਧੇ।","roman":"Thaadhe hai kaanh kidho ban mai tan pai sir pai anbuvaa rang baadhe |","meaning_en":"","page":403},{"gurmukhi":"ਚਾਲ ਚਲੈ ਹਰੂਏ ਹਰੂਏ ਮਨੋ ਸੀਖ ਦਈ ਇਹ ਬਾਧਕ ਪਾਧੇ।","roman":"Chaal chalai harooe harooe mano seekh daee ih baadhak paadhe |","meaning_en":"","page":403},{"gurmukhi":"ਅਉ ਸਭ ਹੀ ਠਟ ਬਧਕ ਸੇ ਮਨ ਮੋਹਨ ਜਾਲ ਪੀਤੰਬਰ ਕਾਧੇ। ੪੪੩।","roman":"Au sabh hee that badhak se man mohan jaal peetanbar kaadhe | 443 |","meaning_en":"","page":403}]},{"type":"verse","number":[444],"number_text":"੪੪੪।","page":403,"lines":[{"gurmukhi":"ਸੋ ਉਠਿ ਠਾਢਿ ਕਿਧੋ ਬਨ ਮੈ ਜੁਗ ਤੀਸਰ ਮੈ ਪਤਿ ਜੋਊ ਸੀਯਾ।","roman":"So uthi thaadhi kidho ban mai jug teesar mai pati jo'oo seeyaa |","meaning_en":"","page":403},{"gurmukhi":"ਜਮੁਨਾ ਮਹਿ ਖੇਲ ਕੇ ਕਾਰਨ ਕੌ ਘਸਿ ਚੰਦਨ ਭਾਲ ਮੈ ਟੀਕੋ ਦੀਯਾ।","roman":"Jamunaa mahi khel ke kaaran kau ghasi chandan bhaal mai teeko deeyaa |","meaning_en":"","page":403},{"gurmukhi":"ਭਿਲਰਾ ਡਰਿ ਨੈਨ ਕੇ ਸੈਨਨ ਕੋ ਸਭ ਗੋਪਿਨ ਕੋ ਮਨ ਚੋਰਿ ਲੀਯਾ।","roman":"Bhilraa dari nain ke sainan ko sabh gopin ko man chori leeyaa |","meaning_en":"","page":403},{"gurmukhi":"ਕਬਿ ਸ੍ਯਾਮ ਕਹੈ ਭਗਵਾਨ ਕਿਧੋ ਰਸ ਕਾਰਨ ਕੋ ਠਗ ਬੇਸ ਕੀਆ। ੪੪੪।","roman":"Kabi syaam kahai bhagvaan kidho ras kaaran ko thag bes keeaa | 444 |","meaning_en":"","page":403}]},{"type":"verse","number":[445],"number_text":"੪੪੫।","page":403,"lines":[{"gurmukhi":"ਦ੍ਰਿਗ ਜਾਹਿ ਮ੍ਰਿਗੀ ਪਤਿ ਕੀ ਸਮ ਹੈ ਮੁਖ ਜਾਹਿ ਨਿਸਾਪਤਿ ਸੀ ਛਬਿ ਪਾਈ।","roman":"Drig jaahi mrigee pati kee sam hai mukh jaahi nisaapti see chhabi paaee |","meaning_en":"","page":403},{"gurmukhi":"ਜਾਹਿ ਕੁਰੰਗਨ ਕੇ ਰਿਪੁ ਸੀ ਕਟਿ ਕੰਚਨ ਸੀ ਤਨ ਨੈ ਛਬਿ ਛਾਈ।","roman":"Jaahi kurangan ke ripu see kati kanchan see tan nai chhabi chhaaee |","meaning_en":"","page":403},{"gurmukhi":"ਪਾਟ ਬਨੇ ਕਦਲੀ ਦਲ ਦ੍ਵੈ ਜੰਘਾ ਪਰ ਤੀਰਨ ਸੀ ਦੁਤਿ ਗਾਈ।","roman":"Paat bane kadlee dal dvai janghaa par teeran see duti gaaee |","meaning_en":"","page":403},{"gurmukhi":"ਅੰਗ ਪ੍ਰਤੰਗ ਸੁ ਸੁੰਦਰ ਸ੍ਯਾਮ ਕਛੂ ਉਪਮਾ ਕਹੀਐ ਨਹੀ ਜਾਈ। ੪੪੫।","roman":"Ang pratang su sundar syaam kachhoo upmaa kaheeai nahee jaaee | 445 |","meaning_en":"","page":403}]},{"type":"verse","number":[446],"number_text":"੪੪੬।","page":404,"lines":[{"gurmukhi":"ਮੁਖ ਜਾਹਿ ਨਿਸਾਪਤਿ ਕੀ ਸਮ ਹੈ ਬਨ ਮੈ ਤਿਨ ਗੀਤ ਰਿਝਿਯੋ ਅਰੁ ਗਾਯੋ।","roman":"Mukh jaahi nisaapti kee sam hai ban mai tin geet rijhiyo aru gaayo |","meaning_en":"","page":404},{"gurmukhi":"ਤਾ ਸੁਰ ਕੋ ਧੁਨਿ ਸ੍ਰਉਨਨ ਮੈ ਬ੍ਰਿਜ ਹੂੰ ਕੀ ਤ੍ਰਿਯਾ ਸਭ ਹੀ ਸੁਨਿ ਪਾਯੋ।","roman":"Taa sur ko dhuni sraunan mai brij hoon kee triyaa sabh hee suni paayo |","meaning_en":"","page":404},{"gurmukhi":"ਧਾਇ ਚਲੀ ਹਰਿ ਕੇ ਮਿਲਬੇ ਕਹੁ ਤਉ ਸਭ ਕੇ ਮਨ ਮੈ ਜਬ ਭਾਯੋ।","roman":"Dhaai chalee hari ke milbe kahu tau sabh ke man mai jab bhaayo |","meaning_en":"","page":404},{"gurmukhi":"ਕਾਨ੍ਹ ਮਨੋ ਮ੍ਰਿਗਨੀ ਜੁਵਤੀ ਛਲਬੇ ਕਹੁ ਘੰਟਕ ਹੇਰਿ ਬਨਾਯੋ। ੪੪੬।","roman":"Kaanh mano mrignee juvtee chhalbe kahu ghantak heri banaayo | 446 |","meaning_en":"","page":404}]},{"type":"verse","number":[447],"number_text":"੪੪੭।","page":404,"lines":[{"gurmukhi":"ਮੁਰਲੀ ਮੁਖ ਕਾਨਰ ਕੇ ਤਰੂਏ ਤਰੁ ਸ੍ਯਾਮ ਕਹੈ ਬਿਧਿ ਖੂਬ ਛਕੀ।","roman":"Murlee mukh kaanar ke tarooe taru syaam kahai bidhi khoob chhakee |","meaning_en":"","page":404},{"gurmukhi":"ਬ੍ਰਿਜ ਭਾਮਿਨ ਆ ਪਹੁਚੀ ਦਵਰੀ ਸੁਧਿ ਹਿਯਾ ਜੁ ਰਹੀ ਨ ਕਛੂ ਮੁਖ ਕੀ।","roman":"Brij bhaamin aa pahuchee davree sudhi hiyaa ju rahee na kachhoo mukh kee |","meaning_en":"","page":404},{"gurmukhi":"ਮੁਖ ਕੋ ਪਿਖਿ ਰੂਪ ਕੇ ਬਸ੍ਯ ਭਈ ਮਤ ਹ੍ਵੈ ਅਤਿ ਹੀ ਕਹਿ ਕਾਨ੍ਹ ਬਕੀ।","roman":"Mukh ko pikhi roop ke basy bhaee mat hvai ati hee kahi kaanh bakee |","meaning_en":"","page":404},{"gurmukhi":"ਇਕ ਝੂਮਿ ਪਰੀ ਇਕ ਗਾਇ ਉਠੀ ਤਨ ਮੈ ਇਕ ਹ੍ਵੈ ਰਹਿਗੀ ਸੁ ਜਕੀ।੪੪੭।","roman":"Ik jhoomi paree ik gaai uthee tan mai ik hvai rahigee su jakee | 447 |","meaning_en":"","page":404}]},{"type":"verse","number":[448],"number_text":"੪੪੮।","page":404,"lines":[{"gurmukhi":"ਹਰਿ ਕੀ ਸੁਨਿ ਕੈ ਸੁਰ ਸ੍ਰਉਨਨ ਮੈ ਸਭ ਧਾਇ ਚਲੀ ਬ੍ਰਿਜਭੂਮਿ ਸਖੀ।","roman":"Hari kee suni kai sur sraunan mai sabh dhaai chalee brijbhoomi sakhee |","meaning_en":"","page":404},{"gurmukhi":"ਸਭ ਮੈਨ ਕੇ ਹਾਥਿ ਗਈ ਬਧ ਕੈ ਸਭ ਸੁੰਦਰ ਸ੍ਯਾਮ ਕੀ ਪੇਖਿ ਅਖੀ।","roman":"Sabh main ke haathi gaee badh kai sabh sundar syaam kee pekhi akhee |","meaning_en":"","page":404},{"gurmukhi":"ਨਿਕਰੀ ਗ੍ਰਿਹ ਤੇ ਮ੍ਰਿਗਨੀ ਸਮ ਮਾਨਹੁ ਗੋਪਿਨ ਤੇ ਨਹਿ ਜਾਹਿ ਰਖੀ।","roman":"Nikree grih te mrignee sam maanhu gopin te nahi jaahi rakhee |","meaning_en":"","page":404},{"gurmukhi":"ਇਹ ਭਾਤਿ ਹਰੀ ਪਹਿ ਆਇ ਗਈ ਜਨੁ ਆਇ ਗਈ ਸੁਧਿ ਜਾਨਿ ਸਖੀ। ੪੪੮।","roman":"Ih bhaati haree pahi aai gaee janu aai gaee sudhi jaani sakhee | 448 |","meaning_en":"","page":404}]},{"type":"verse","number":[449],"number_text":"੪੪੯।","page":404,"lines":[{"gurmukhi":"ਗਈ ਆਇ ਦਸੋ ਦਿਸ ਤੇ ਗੁਪੀਆ ਸਭ ਹੀ ਰਸ ਕਾਨ੍ਹ ਕੇ ਸਾਥ ਪਗੀ।","roman":"Gaee aai daso dis te gupeeaa sabh hee ras kaanh ke saath pagee |","meaning_en":"","page":404},{"gurmukhi":"ਪਿਖ ਕੈ ਮੁਖਿ ਕਾਨ੍ਹ ਕੋ ਚੰਦ ਕਲਾ ਸੁ ਚਕੋਰਨ ਸੀ ਮਨ ਮੈ ਉਮਗੀ।","roman":"Pikh kai mukhi kaanh ko chand kalaa su chakoran see man mai umgee |","meaning_en":"","page":404},{"gurmukhi":"ਹਰਿ ਕੋ ਪੁਨਿ ਸੁਧਿ ਸੁ ਆਨਨ ਪੇਖਿ ਕਿਧੌ ਤਿਨ ਕੀ ਠਗ ਡੀਠ ਲਗੀ।","roman":"Hari ko puni sudhi su aanan pekhi kidhau tin kee thag deeth lagee |","meaning_en":"","page":404},{"gurmukhi":"ਭਗਵਾਨ ਪ੍ਰਸੰਨਿ ਭਯੋ ਪਿਖ ਕੈ ਕਬਿ ਸ੍ਯਾਮ ਮਨੋ ਮ੍ਰਿਗ ਦੇਖ ਮ੍ਰਿਗੀ। ੪੪੯।","roman":"Bhagvaan prasanni bhayo pikh kai kabi syaam mano mrig dekh mrigee | 449 |","meaning_en":"","page":404}]},{"type":"verse","number":[450],"number_text":"੪੫੦।","page":404,"lines":[{"gurmukhi":"ਗੋਪਿਨ ਕੀ ਬਰਜੀ ਨ ਰਹੀ ਸੁਰ ਕਾਨਰ ਕੀ ਸੁਨਬੇ ਕਹੁ ਤ੍ਰਾਘੀ।","roman":"Gopin kee barjee na rahee sur kaanar kee sunbe kahu traaghee |","meaning_en":"","page":404},{"gurmukhi":"ਨਾਖਿ ਚਲੀ ਅਪਨੇ ਗ੍ਰਿਹ ਇਉ ਜਿਮੁ ਮਤਿ ਜੁਗੀਸ੍ਵਰ ਇੰਦ੍ਰਹਿ ਲਾਘੀ।","roman":"Naakhi chalee apne grih iu jimu mati jugeesvar indrahi laaghee |","meaning_en":"","page":404},{"gurmukhi":"ਦੇਖਨ ਕੋ ਮੁਖਿ ਤਾਹਿ ਚਲੀ ਜੋਊ ਕਾਮ ਕਲਾ ਹੂੰ ਕੋ ਹੈ ਫੁਨਿ ਬਾਘੀ।","roman":"Dekhan ko mukhi taahi chalee jo'oo kaam kalaa hoon ko hai phuni baaghee |","meaning_en":"","page":404},{"gurmukhi":"ਡਾਰਿ ਚਲੀ ਸਿਰ ਕੇ ਪਟ ਇਉ ਜਨੁ ਡਾਰਿ ਚਲੀ ਸਭ ਲਾਜ ਬਹਾਘੀ।੪੫੦।","roman":"Daari chalee sir ke pat iu janu daari chalee sabh laaj bahaaghee | 450 |","meaning_en":"","page":404}]},{"type":"verse","number":[451],"number_text":"੪੫੧।","page":404,"lines":[{"gurmukhi":"ਕਾਨ੍ਹ ਕੇ ਪਾਸਿ ਗਈ ਜਬ ਹੀ ਤਬ ਹੀ ਸਭ ਗੋਪਿਨ ਲੀਨ ਸੁ ਸੰਙਾ।","roman":"Kaanh ke paasi gaee jab hee tab hee sabh gopin leen su sanngaa |","meaning_en":"","page":404},{"gurmukhi":"ਚੀਰ ਪਰੇ ਗਿਰ ਕੈ ਤਨ ਭੂਖਨ ਟੂਟ ਗਈ ਤਿਨ ਹਾਥਨ ਬੰਙਾ।","roman":"Cheer pare gir kai tan bhookhan toot gaee tin haathan banngaa |","meaning_en":"","page":404},{"gurmukhi":"ਕਾਨ੍ਹ ਕੋ ਰੂਪ ਨਿਹਾਰਿ ਸਭੈ ਗੁਪੀਆ ਕਬਿ ਸ੍ਯਾਮ ਭਈ ਇਕ ਰੰਙਾ।","roman":"Kaanh ko roop nihaari sabhai gupeeaa kabi syaam bhaee ik ranngaa |","meaning_en":"","page":404},{"gurmukhi":"ਹੋਇ ਗਈ ਤਨਮੈ ਸਭ ਹੀ ਇਕ ਰੰਗ ਮਨੋ ਸਭ ਛੋਡ ਕੈ ਸੰਙਾ। ੪੫੧।","roman":"Hoi gaee tanmai sabh hee ik rang mano sabh chhod kai sanngaa | 451 |","meaning_en":"","page":404}]},{"type":"verse","number":[452],"number_text":"੪੫੨।","page":405,"lines":[{"gurmukhi":"ਗੋਪਿਨ ਭੂਲਿ ਗਈ ਗ੍ਰਿਹ ਕੀ ਸੁਧਿ ਕਾਨ੍ਹ ਹੀ ਕੇ ਰਸ ਭੀਤਰ ਰਾਚੀ।","roman":"Gopin bhooli gaee grih kee sudhi kaanh hee ke ras bheetar raachee |","meaning_en":"","page":405},{"gurmukhi":"ਭਉਹ ਭਰੀ ਮਧੁਰੀ ਬਰਨੀ ਸਭ ਹੀ ਸੁ ਢਰੀ ਜਨੁ ਮੈਨ ਕੇ ਸਾਚੀ।","roman":"Bhauh bharee madhuree barnee sabh hee su dharee janu main ke saachee |","meaning_en":"","page":405},{"gurmukhi":"ਛੋਰ ਦਏ ਰਸ ਅਉਰਨ ਸ੍ਵਾਦ ਭਲੇ ਭਗਵਾਨ ਹੀ ਸੋ ਸਭ ਮਾਚੀ।","roman":"Chhor dae ras auran svaad bhale bhagvaan hee so sabh maachee |","meaning_en":"","page":405},{"gurmukhi":"ਸੋਭਤ ਤਾ ਤਨ ਮੈ ਹਰਿ ਕੋ ਮਨੋ ਕੰਚਨ ਮੈ ਚੁਨੀਆ ਚੁਨਿ ਖਾਚੀ। ੪੫੨।","roman":"Sobhat taa tan mai hari ko mano kanchan mai chuneeaa chuni khaachee | 452 |","meaning_en":"","page":405}]},{"type":"verse","number":[453],"number_text":"੪੫੩।","page":405,"lines":[{"gurmukhi":"ਕਾਨ੍ਹ ਕੋ ਰੂਪ ਨਿਹਾਰਿ ਰਹੀ ਬ੍ਰਿਜ ਮੈ ਜੁ ਹੁਤੀ ਗੁਪੀਆ ਅਤਿ ਹਾਛੀ।","roman":"Kaanh ko roop nihaari rahee brij mai ju hutee gupeeaa ati haachhee |","meaning_en":"","page":405},{"gurmukhi":"ਰਾਜਤ ਜਾਹਿ ਮ੍ਰਿਗੀ ਪਤਿ ਨੈਨ ਬਿਰਾਜਤ ਸੁੰਦਰ ਹੈ ਸਮ ਮਾਛੀ।","roman":"Raajat jaahi mrigee pati nain biraajat sundar hai sam maachhee |","meaning_en":"","page":405},{"gurmukhi":"ਸੋਭਿਤ ਹੈ ਬ੍ਰਿਜ ਮੰਡਲ ਮੈ ਜਨੁ ਖੇਲਬੇ ਕਾਜਿ ਨਟੀ ਇਹ ਕਾਛੀ।","roman":"Sobhit hai brij mandal mai janu khelbe kaaji natee ih kaachhee |","meaning_en":"","page":405},{"gurmukhi":"ਦੇਖਨਿ ਹਾਰ ਕਿਧੌ ਭਗਵਾਨ ਦਿਖਾਵਤ ਭਾਵ ਹਮੈ ਹਿਯਾ ਆਛੀ। ੪੫੩।","roman":"Dekhni haar kidhau bhagvaan dikhaavat bhaav hamai hiyaa aachhee | 453 |","meaning_en":"","page":405}]},{"type":"verse","number":[454],"number_text":"੪੫੪।","page":405,"lines":[{"gurmukhi":"ਸੋਹਤ ਸਹੈ ਸਭ ਗੋਪਿਨ ਕੇ ਕਬਿ ਸ੍ਯਾਮ ਕਹੈ ਦ੍ਰਿਗ ਅੰਜਨ ਆਜੇ।","roman":"Sohat sahai sabh gopin ke kabi syaam kahai drig anjan aaje |","meaning_en":"","page":405},{"gurmukhi":"ਕਉਲਨ ਕੀ ਜਨੁ ਸੁਧਿ ਪ੍ਰਭਾ ਸਰ ਸੁੰਦਰ ਸਾਨ ਕੇ ਊਪਰਿ ਮਾਜੇ।","roman":"Kaulan kee janu sudhi prabhaa sar sundar saan ke oopri maaje |","meaning_en":"","page":405},{"gurmukhi":"ਬੈਠਿ ਘਰੀ ਇਕ ਮੈ ਚਤੁਰਾਨਨ ਮੈਨ ਕੇ ਤਾਤ ਬਨੇ ਕਸਿ ਸਾਜੇ।","roman":"Baithi gharee ik mai chaturaanan main ke taat bane kasi saaje |","meaning_en":"","page":405},{"gurmukhi":"ਮੋਹਤਿ ਹੈ ਮਨ ਜੋਗਨ ਕੇ ਫੁਨਿ ਜੋਗਨ ਕੇ ਗਨ ਬੀਚ ਕਲਾ ਜੇ। ੪੫੪।","roman":"Mohti hai man jogan ke phuni jogan ke gan beech kalaa je | 454 |","meaning_en":"","page":405}]},{"type":"verse","number":[455],"number_text":"੪੫੫।","page":405,"lines":[{"gurmukhi":"ਠਾਢਿ ਹੈ ਕਾਨ੍ਹ ਸੋਊ ਮਹਿ ਗੋਪਿਨ ਜਾਹਿ ਕੋ ਅੰਤ ਮੁਨੀ ਨਹਿ ਬੂਝੇ।","roman":"Thaadhi hai kaanh so'oo mahi gopin jaahi ko ant munee nahi boojhe |","meaning_en":"","page":405},{"gurmukhi":"ਕੋਟਿ ਕਰੈ ਉਪਮਾ ਬਹੁ ਬਰਖਨ ਨੈਨਨ ਸੋ ਤਉ ਨੈਕੁ ਨ ਸੂਝੇ।","roman":"Koti karai upmaa bahu barkhan nainan so tau naiku na soojhe |","meaning_en":"","page":405},{"gurmukhi":"ਤਾਹੀ ਕੇ ਅੰਤਿ ਲਖੈਬੇ ਕੇ ਕਾਰਨ ਸੂਰ ਘਨੈ ਰਨ ਭੀਤਰ ਜੂਝੇ।","roman":"Taahee ke anti lakhaibe ke kaaran soor ghanai ran bheetar joojhe |","meaning_en":"","page":405},{"gurmukhi":"ਸੋ ਬ੍ਰਿਜ ਭੂਮਿ ਬਿਖੈ ਭਗਵਾਨ ਤ੍ਰੀਆ ਗਨ ਮੈ ਰਸ ਬੈਨ ਅਰੂਝੇ। ੪੫੫।","roman":"So brij bhoomi bikhai bhagvaan treeaa gan mai ras bain aroojhe | 455 |","meaning_en":"","page":405}]},{"type":"verse","number":[456],"number_text":"੪੫੬।","page":405,"lines":[{"gurmukhi":"ਕਾਨਰ ਕੇ ਨਿਕਟੈ ਜਬ ਹੀ ਸਭ ਹੀ ਗੁਪੀਆ ਮਿਲਿ ਸੁੰਦਰ ਗਈਯਾ।","roman":"Kaanar ke niktai jab hee sabh hee gupeeaa mili sundar gaeeyaa |","meaning_en":"","page":405},{"gurmukhi":"ਸੋ ਹਰਿ ਮਧਿ ਸਸਾਨਨ ਪੇਖਿ ਸਭੈ ਫੁਨਿ ਕੰਦ੍ਰਪ ਬੇਖ ਬਨਈਆ।","roman":"So hari madhi sasaanan pekhi sabhai phuni kandrap bekh banaeeaa |","meaning_en":"","page":405},{"gurmukhi":"ਲੈ ਮੁਰਲੀ ਅਪਨੇ ਕਰਿ ਕਾਨ੍ਹ ਕਿਧੌ ਅਤਿ ਹੀ ਹਿਤ ਸਾਥ ਬਜਈਯਾ।","roman":"Lai murlee apne kari kaanh kidhau ati hee hit saath bajaeeyaa |","meaning_en":"","page":405},{"gurmukhi":"ਘੰਟਕ ਹੇਰਕ ਜਿਉ ਪਿਖ ਕੈ ਮ੍ਰਿਗਨੀ ਮੁਹਿ ਜਾਤ ਸੁ ਹੈ ਠਹਰਈਯਾ। ੪੫੬।","roman":"Ghantak herak jiu pikh kai mrignee muhi jaat su hai thahraeeyaa | 456 |","meaning_en":"","page":405}]},{"type":"verse","number":[457],"number_text":"੪੫੭।","page":405,"lines":[{"gurmukhi":"ਮਾਲਸਿਰੀ ਅਰੁ ਰਾਮਕਲੀ ਸੁਭ ਸਾਰੰਗ ਭਾਵਨ ਸਾਥ ਬਸਾਵੈ।","roman":"Maalsiree aru raamaklee subh saarang bhaavan saath basaavai |","meaning_en":"","page":405},{"gurmukhi":"ਜੈਤਸਿਰੀ ਅਰੁ ਸੁਧ ਮਲਾਰ ਬਿਲਾਵਲ ਕੀ ਧੁਨਿ ਕੂਕ ਸੁਨਾਵੈ।","roman":"Jaitsiree aru sudh malaar bilaaval kee dhuni kook sunaavai |","meaning_en":"","page":405},{"gurmukhi":"ਲੈ ਮੁਰਲੀ ਅਪੁਨੇ ਕਰਿ ਕਾਨ੍ਹ ਕਿਧੌ ਅਤਿ ਹੀ ਹਿਤ ਸਾਥ ਬਜਾਵੈ।","roman":"Lai murlee apune kari kaanh kidhau ati hee hit saath bajaavai |","meaning_en":"","page":405},{"gurmukhi":"ਪਉਨ ਚਲੈ ਨ ਰਹੈ ਜਮੁਨਾ ਥਿਰ ਮੋਹਿ ਰਹੈ ਧੁਨਿ ਜੋ ਸੁਨਿ ਪਾਵੈ। ੪੫੭।","roman":"Paun chalai na rahai jamunaa thir mohi rahai dhuni jo suni paavai | 457 |","meaning_en":"","page":405}]},{"type":"verse","number":[458],"number_text":"੪੫੮।","page":406,"lines":[{"gurmukhi":"ਸੁਨ ਕੇ ਮੁਰਲੀ ਧੁਨਿ ਕਾਨਰ ਕੀ ਸਭ ਗੋਪਿਨ ਕੀ ਸਭ ਸੁਧਿ ਛੁਟੀ।","roman":"Sun ke murlee dhuni kaanar kee sabh gopin kee sabh sudhi chhutee |","meaning_en":"","page":406},{"gurmukhi":"ਸਭ ਛਾਡਿ ਚਲੀ ਅਪਨੇ ਗ੍ਰਿਹ ਕਾਰਜ ਕਾਨ੍ਹ ਹੀ ਕੀ ਧੁਨਿ ਸਾਥ ਜੁਟੀ।","roman":"Sabh chhaadi chalee apne grih kaaraj kaanh hee kee dhuni saath jutee |","meaning_en":"","page":406},{"gurmukhi":"ਠਗਨੀ ਸੁਰ ਹੈ ਕਬਿ ਸ੍ਯਾਮ ਕਹੈ ਇਨ ਅੰਤਰ ਕੀ ਸਭ ਮਤਿ ਲੁਟੀ।","roman":"Thagnee sur hai kabi syaam kahai in antar kee sabh mati lutee |","meaning_en":"","page":406},{"gurmukhi":"ਮ੍ਰਿਗਨੀ ਸਮ ਹੈ ਚਲਤ ਯੌ ਇਨ ਕੇ ਮਗ ਲਾਜ ਕੀ ਬੇਲ ਤਰਾਕ ਤੁਟੀ।੪੫੮।","roman":"Mrignee sam hai chalat yau in ke mag laaj kee bel taraak tutee | 458 |","meaning_en":"","page":406}]},{"type":"verse","number":[459],"number_text":"੪੫੯।","page":406,"lines":[{"gurmukhi":"ਕਾਨ੍ਹ ਕੋ ਰੂਪ ਨਿਹਾਰ ਰਹੀ ਤ੍ਰਿਯਾ ਸ੍ਯਾਮ ਕਹੈ ਕਬਿ ਹੋਇ ਇਕਾਠੀ।","roman":"Kaanh ko roop nihaar rahee triyaa syaam kahai kabi hoi ikaathee |","meaning_en":"","page":406},{"gurmukhi":"ਜਿਉ ਸੁਰਕੀ ਧੁਨਿ ਕੌ ਸੁਨ ਕੈ ਮ੍ਰਿਗਨੀ ਚਲਿ ਆਵਤ ਜਾਤ ਨ ਨਾਠੀ।","roman":"Jiu surkee dhuni kau sun kai mrignee chali aavat jaat na naathee |","meaning_en":"","page":406},{"gurmukhi":"ਮੈਨ ਸੋ ਮਤ ਹ੍ਵੈ ਕੂਦਤ ਕਾਨ੍ਹ ਸੁ ਛੋਰਿ ਮਨੋ ਸਭ ਲਾਜ ਕੀ ਗਾਠੀ।","roman":"Main so mat hvai koodat kaanh su chhori mano sabh laaj kee gaathee |","meaning_en":"","page":406},{"gurmukhi":"ਗੋਪਿਨ ਕੋ ਮਨੁ ਯੌ ਚੁਰਿ ਗਯੋ ਜਿਮ ਖੋਰਰ ਪਾਥਰ ਪੈ ਚਰਨਾਠੀ। ੪੫੯।","roman":"Gopin ko manu yau churi gayo jim khorar paathar pai charnaathee | 459 |","meaning_en":"","page":406}]},{"type":"verse","number":[460],"number_text":"੪੬੦।","page":406,"lines":[{"gurmukhi":"ਹਸਿ ਬਾਤ ਕਰੈ ਹਰਿ ਸੋ ਗੁਪੀਆ ਕਬਿ ਸ੍ਯਾਮ ਕਹੈ ਜਿਨ ਭਾਗ ਬਡੇ।","roman":"Hasi baat karai hari so gupeeaa kabi syaam kahai jin bhaag bade |","meaning_en":"","page":406},{"gurmukhi":"ਮੋਹਿ ਸਭੈ ਪ੍ਰਗਟਿਯੋ ਇਨ ਕੋ ਪਿਖ ਕੈ ਹਰਿ ਪਾਪਨ ਜਾਲ ਲਡੇ।","roman":"Mohi sabhai pragtiyo in ko pikh kai hari paapan jaal lade |","meaning_en":"","page":406},{"gurmukhi":"ਕ੍ਰਿਸਨੰ ਤਨ ਮਧਿ ਬਧੂ ਬ੍ਰਿਜ ਕੀ ਮਨ ਹ੍ਵੈ ਕਰਿ ਆਤੁਰ ਅਤਿ ਗਡੇ।","roman":"Krisnan tan madhi badhoo brij kee man hvai kari aatur ati gade |","meaning_en":"","page":406},{"gurmukhi":"ਸੋਊ ਸਤਿ ਕਿਧੋ ਮਨ ਜਾਹਿ ਗਡੇ ਸੁ ਅਧਨਿ ਜਿਨੋ ਮਨ ਹੈ ਅਗਡੇ। ੪੬੦।","roman":"So'oo sati kidho man jaahi gade su adhni jino man hai agde | 460 |","meaning_en":"","page":406}]},{"type":"verse","number":[461],"number_text":"੪੬੧।","page":406,"lines":[{"gurmukhi":"ਨੈਨ ਚੁਰਾਇ ਮਹਾ ਸੁਖ ਪਾਇ ਕਛੂ ਮੁਸਕਾਇ ਭਯੋ ਹਰਿ ਠਾਢੋ।","roman":"Nain churaai mahaa sukh paai kachhoo muskaai bhayo hari thaadho |","meaning_en":"","page":406},{"gurmukhi":"ਮੋਹਿ ਰਹੀ ਬ੍ਰਿਜ ਬਾਮ ਸਭੈ ਅਤਿ ਹੀ ਤਿਨ ਕੈ ਮਨਿ ਆਨੰਦ ਬਾਢੋ।","roman":"Mohi rahee brij baam sabhai ati hee tin kai mani aanand baadho |","meaning_en":"","page":406},{"gurmukhi":"ਜਾ ਭਗਵਾਨ ਕਿਧੋ ਸੀਯ ਜੀਤ ਕੈ ਮਾਰਿ ਡਰਿਯੋ ਰਿਪੁ ਰਾਵਨ ਗਾਢੋ।","roman":"Jaa bhagvaan kidho seey jeet kai maari dariyo ripu raavan gaadho |","meaning_en":"","page":406},{"gurmukhi":"ਤਾ ਭਗਵਾਨ ਕਿਧੋ ਮੁਖ ਤੇ ਮੁਕਤਾ ਨੁਕਤਾ ਸਮ ਅੰਮ੍ਰਿਤ ਕਾਢੋ। ੪੬੧।","roman":"Taa bhagvaan kidho mukh te muktaa nuktaa sam anmrit kaadho | 461 |","meaning_en":"","page":406}]},{"type":"heading","kind":"speaker","name":"ਕਾਨ੍ਹ ਜੂ ਬਾਚ ਗੋਪੀ ਪ੍ਰਤਿ","gurmukhi":"ਕਾਨ੍ਹ ਜੂ ਬਾਚ ਗੋਪੀ ਪ੍ਰਤਿ","roman":"Kaanh joo baach gopee prati","meaning_en":"","page":406},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":406},{"type":"verse","number":[462],"number_text":"੪੬੨।","page":406,"lines":[{"gurmukhi":"ਆਜੁ ਭਯੋ ਝੜ ਹੈ ਜਮੁਨਾ ਤਟਿ ਖੇਲਨ ਕੀ ਅਬ ਘਾਤ ਬਣੀ।","roman":"Aaju bhayo jhar hai jamunaa tati khelan kee ab ghaat banee |","meaning_en":"","page":406},{"gurmukhi":"ਤਜ ਕੈ ਡਰ ਖੇਲ ਕਰੋ ਹਮ ਸੋ ਕਬਿ ਸ੍ਯਾਮ ਕਹਿਯੋ ਹਸਿ ਕਾਨ੍ਹ ਅਣੀ।","roman":"Taj kai dar khel karo ham so kabi syaam kahiyo hasi kaanh anee |","meaning_en":"","page":406},{"gurmukhi":"ਜੋ ਸੁੰਦਰ ਹੈ ਤੁਮ ਮੈ ਸੋਊ ਖੇਲਹੁ ਖੇਲਹੁ ਨਾਹਿ ਜਣੀ ਰੁ ਕਣੀ।","roman":"Jo sundar hai tum mai so'oo khelhu khelhu naahi janee ru kanee |","meaning_en":"","page":406},{"gurmukhi":"ਇਹ ਭਾਤਿ ਕਹੈ ਹਸਿ ਕੈ ਰਸ ਬੋਲ ਕਿਧੋ ਹਰਤਾ ਜੋਊ ਮਾਨ ਫਣੀ। ੪੬੨।","roman":"Ih bhaati kahai hasi kai ras bol kidho hartaa jo'oo maan phanee | 462 |","meaning_en":"","page":406}]},{"type":"verse","number":[463],"number_text":"੪੬੩।","page":406,"lines":[{"gurmukhi":"ਹਸਿ ਕੈ ਸੁ ਕਹੀ ਬਤੀਆ ਤਿਨ ਸੋ ਕਬਿ ਸ੍ਯਾਮ ਕਹੈ ਹਰਿ ਜੋ ਰਸ ਰਾਤੋ।","roman":"Hasi kai su kahee bateeaa tin so kabi syaam kahai hari jo ras raato |","meaning_en":"","page":406},{"gurmukhi":"ਨੈਨ ਮ੍ਰਿਗੀਪਤਿ ਸੇ ਤਿਹ ਕੇ ਇਮ ਚਾਲ ਚਲੈ ਜਿਮ ਗਈਯਰ ਮਾਤੋ।","roman":"Nain mrigeepti se tih ke im chaal chalai jim gaeeyar maato |","meaning_en":"","page":406},{"gurmukhi":"ਦੇਖਤ ਮੂਰਤਿ ਕਾਨ੍ਹ ਕੀ ਗੋਪਿਨ ਭੂਲਿ ਗਈ ਗ੍ਰਿਹ ਕੀ ਸੁਧ ਸਾਤੋ।","roman":"Dekhat moorti kaanh kee gopin bhooli gaee grih kee sudh saato |","meaning_en":"","page":406},{"gurmukhi":"ਚੀਰ ਗਏ ਉਡ ਕੈ ਤਨ ਕੈ ਅਰੁ ਟੂਟ ਗਯੋ ਨੈਨ ਤੇ ਲਾਜ ਕੋ ਨਾਤੋ। ੪੬੩।","roman":"Cheer gae ud kai tan kai aru toot gayo nain te laaj ko naato | 463 |","meaning_en":"","page":406}]},{"type":"verse","number":[464],"number_text":"੪੬੪।","page":407,"lines":[{"gurmukhi":"ਕੁਪਿ ਕੈ ਮਧੁ ਕੈਟਭ ਤਾਨਿ ਮਰੇ ਮੁਰਿ ਦੈਤ ਮਰਿਯੋ ਅਪਨੇ ਜਿਨ ਹਾਥਾ।","roman":"Kupi kai madhu kaitabh taani mare muri dait mariyo apne jin haathaa |","meaning_en":"","page":407},{"gurmukhi":"ਜਾਹਿ ਬਿਭੀਛਨ ਰਾਜ ਦਯੋ ਰਿਸਿ ਰਾਵਨ ਕਾਟ ਦਏ ਜਿਹ ਮਾਥਾ।","roman":"Jaahi bibheechhan raaj dayo risi raavan kaat dae jih maathaa |","meaning_en":"","page":407},{"gurmukhi":"ਸੋ ਤਿਹ ਕੀ ਤਿਹੂ ਲੋਗਨ ਮਧਿ ਕਹੈ ਕਬਿ ਸ੍ਯਾਮ ਚਲੇ ਜਸ ਗਾਥਾ।","roman":"So tih kee tihoo logan madhi kahai kabi syaam chale jas gaathaa |","meaning_en":"","page":407},{"gurmukhi":"ਸੋ ਬ੍ਰਿਜ ਭੂਮਿ ਬਿਖੈ ਰਸ ਕੈ ਹਿਤ ਖੇਲਤ ਹੈ ਫੁਨਿ ਗੋਪਿਨ ਸਾਥਾ। ੪੬੪।","roman":"So brij bhoomi bikhai ras kai hit khelat hai phuni gopin saathaa | 464 |","meaning_en":"","page":407}]},{"type":"verse","number":[465],"number_text":"੪੬੫।","page":407,"lines":[{"gurmukhi":"ਹਸਿ ਕੈ ਹਰਿ ਜੂ ਬ੍ਰਿਜ ਮੰਡਲ ਮੈ ਸੰਗ ਗੋਪਿਨ ਕੇ ਇਕ ਹੋਡ ਬਦੀ।","roman":"Hasi kai hari joo brij mandal mai sang gopin ke ik hod badee |","meaning_en":"","page":407},{"gurmukhi":"ਸਭ ਧਾਇ ਪਰੈ ਹਮਹੂੰ ਤੁਮਹੂੰ ਇਹ ਭਾਤਿ ਕਹਿਯੋ ਮਿਲਿ ਬੀਚ ਨਦੀ।","roman":"Sabh dhaai parai hamhoon tumhoon ih bhaati kahiyo mili beech nadee |","meaning_en":"","page":407},{"gurmukhi":"ਜਬ ਜਾਇ ਪਰੇ ਜਮੁਨਾ ਜਲ ਮੈ ਸੰਗ ਗੋਪਿਨ ਕੇ ਭਗਵਾਨ ਜਦੀ।","roman":"Jab jaai pare jamunaa jal mai sang gopin ke bhagvaan jadee |","meaning_en":"","page":407},{"gurmukhi":"ਤਬ ਲੈ ਚੁਭਕੀ ਹਰਿ ਜੀ ਤ੍ਰਿਯ ਕੋ ਸੁ ਲਯੋ ਮੁਖ ਚੂਮ ਕਿਧੋ ਸੋ ਤਦੀ। ੪੬੫।","roman":"Tab lai chubhkee hari jee triy ko su layo mukh choom kidho so tadee | 465 |","meaning_en":"","page":407}]},{"type":"heading","kind":"speaker","name":"ਗੋਪੀ ਬਾਚ ਕਾਨ੍ਹ ਜੂ ਸੋ","gurmukhi":"ਗੋਪੀ ਬਾਚ ਕਾਨ੍ਹ ਜੂ ਸੋ","roman":"Gopee baach kaanh joo so","meaning_en":"","page":407},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":407},{"type":"verse","number":[466],"number_text":"੪੬੬।","page":407,"lines":[{"gurmukhi":"ਮਿਲ ਕੈ ਸਭ ਗ੍ਵਾਰਿਨ ਸੁੰਦਰ ਸ੍ਯਾਮ ਸੋ ਸ੍ਯਾਮ ਕਹੀ ਹਸਿ ਬਾਤ ਪ੍ਰਬੀਨਨ।","roman":"Mil kai sabh gvaarin sundar syaam so syaam kahee hasi baat prabeenan |","meaning_en":"","page":407},{"gurmukhi":"ਰਾਜਤ ਜਾਹਿ ਮ੍ਰਿਗੀਪਤਿ ਸੇ ਦ੍ਰਿਗ ਛਾਜਤ ਚੰਚਲਤਾ ਸਮ ਮੀਨਨ।","roman":"Raajat jaahi mrigeepti se drig chhaajat chanchaltaa sam meenan |","meaning_en":"","page":407},{"gurmukhi":"ਕੰਚਨ ਸੇ ਤਨ ਕਉਲ ਮੁਖੀ ਰਸ ਆਤੁਰ ਹੈ ਕਹਿਯੋ ਰਛਕ ਦੀਨਨ।","roman":"Kanchan se tan kaul mukhee ras aatur hai kahiyo rachhak deenan |","meaning_en":"","page":407},{"gurmukhi":"ਨੇਹੁ ਬਢਾਇ ਮਹਾ ਸੁਖੁ ਪਾਇ ਕਹਿਯੋ ਸਿਰਿ ਨਿਆਇ ਕੈ ਭਾਤਿ ਅਧੀਨਨ। ੪੬੬।","roman":"Nehu badhaai mahaa sukhu paai kahiyo siri niaai kai bhaati adheenan | 466 |","meaning_en":"","page":407}]},{"type":"verse","number":[467],"number_text":"੪੬੭।","page":407,"lines":[{"gurmukhi":"ਅਤਿ ਹ੍ਵੈ ਰਿਝਵੰਤ ਕਹਿਓ ਗੁਪੀਆ ਜੁਗ ਤੀਸਰ ਮੈ ਪਤਿ ਭਯੋ ਜੁ ਕਪੀ।","roman":"Ati hvai rijhvant kahio gupeeaa jug teesar mai pati bhayo ju kapee |","meaning_en":"","page":407},{"gurmukhi":"ਜਿਨਿ ਰਾਵਨ ਖੇਤਿ ਮਰਿਓ ਕੁਪ ਕੈ ਜਿਹ ਰੀਝਿ ਬਿਭੀਛਨ ਲੰਕ ਥਪੀ।","roman":"Jini raavan kheti mario kup kai jih reejhi bibheechhan lank thapee |","meaning_en":"","page":407},{"gurmukhi":"ਜਿਹ ਕੀ ਜਗ ਬੀਚ ਪ੍ਰਸਿਧ ਕਲਾ ਕਬਿ ਸ੍ਯਾਮ ਕਹੈ ਕਛੁ ਨਾਹਿ ਛਪੀ।","roman":"Jih kee jag beech prasidh kalaa kabi syaam kahai kachhu naahi chhapee |","meaning_en":"","page":407},{"gurmukhi":"ਤਿਹ ਸੰਗ ਕਰੈ ਰਸ ਕੀ ਚਰਚਾ ਜਿਨ ਹੂੰ ਤਿਰੀਯਾ ਫੁਨਿ ਚੰਡਿ ਜਪੀ। ੪੬੭।","roman":"Tih sang karai ras kee charchaa jin hoon tireeyaa phuni chandi japee | 467 |","meaning_en":"","page":407}]},{"type":"verse","number":[468],"number_text":"੪੬੮।","page":407,"lines":[{"gurmukhi":"ਜਉ ਰਸ ਬਾਤ ਕਹੀ ਗੁਪੀਆ ਤਬ ਹੀ ਹਰਿ ਜਵਾਬ ਦਯੋ ਤਿਨ ਸਾਫੀ।","roman":"Jau ras baat kahee gupeeaa tab hee hari javaab dayo tin saaphee |","meaning_en":"","page":407},{"gurmukhi":"ਆਈ ਹੋ ਛੋਡਿ ਸਭੈ ਪਤਿ ਕੋ ਤੁਮ ਹੋਇ ਤੁਮੈ ਨ ਮਰੇ ਫੁਨਿ ਮਾਫੀ।","roman":"Aaee ho chhodi sabhai pati ko tum hoi tumai na mare phuni maaphee |","meaning_en":"","page":407},{"gurmukhi":"ਹਉ ਤੁਮ ਸੋ ਨਹਿ ਹੇਤ ਕਰੋ ਤੁਮ ਕਾਹੇ ਕਉ ਬਾਮ ਕਰੋ ਰਸ ਲਾਫੀ।","roman":"Hau tum so nahi het karo tum kaahe kau baam karo ras laaphee |","meaning_en":"","page":407},{"gurmukhi":"ਇਉ ਕਹਿ ਕੈ ਹਰਿ ਮੋਨ ਭਜੀ ਸੁ ਬਜਾਇ ਉਠਿਯੋ ਮੁਰਲੀ ਮਹਿ ਕਾਫੀ।੪੬੮।","roman":"Iu kahi kai hari mon bhajee su bajaai uthiyo murlee mahi kaaphee | 468 |","meaning_en":"","page":407}]},{"type":"heading","kind":"speaker","name":"ਕਾਨ੍ਹ ਬਾਚ ਗੋਪੀ ਸੋਂ","gurmukhi":"ਕਾਨ੍ਹ ਬਾਚ ਗੋਪੀ ਸੋਂ","roman":"Kaanh baach gopee son","meaning_en":"","page":407},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":407},{"type":"verse","number":[469],"number_text":"੪੬੯।","page":407,"lines":[{"gurmukhi":"ਸਭ ਸੁੰਦਰ ਗੋਪਿਨ ਸੋ ਕਬਿ ਸ੍ਯਾਮ ਦਯੋ ਹਰਿ ਕੈ ਹਰਿ ਜਵਾਬ ਜਬੈ।","roman":"Sabh sundar gopin so kabi syaam dayo hari kai hari javaab jabai |","meaning_en":"","page":407},{"gurmukhi":"ਨ ਗਈ ਹਰਿ ਮਾਨ ਕਹਿਯੋ ਗ੍ਰਿਹ ਕੋ ਪ੍ਰਭ ਮੋਹਿ ਰਹੀ ਮੁਖਿ ਦੇਖ ਸਬੈ।","roman":"Na gaee hari maan kahiyo grih ko prabh mohi rahee mukhi dekh sabai |","meaning_en":"","page":407},{"gurmukhi":"ਕ੍ਰਿਸਨੰ ਕਰਿ ਲੈ ਅਪਨੇ ਮੁਰਲੀ ਸੁ ਬਜਾਇ ਉਠਿਓ ਜੁਤ ਰਾਗ ਤਬੈ।","roman":"Krisnan kari lai apne murlee su bajaai uthio jut raag tabai |","meaning_en":"","page":407},{"gurmukhi":"ਮਨੋ ਘਾਇਲ ਗੋਪਿਨ ਕੇ ਬ੍ਰਣ ਮੈ ਭਗਵਾਨ ਡਰਿਯੋ ਜਨੁ ਲੋਨ ਅਬੈ। ੪੬੯।","roman":"Mano ghaail gopin ke bran mai bhagvaan dariyo janu lon abai | 469 |","meaning_en":"","page":407}]},{"type":"verse","number":[470],"number_text":"੪੭੦।","page":408,"lines":[{"gurmukhi":"ਜਿਉ ਮ੍ਰਿਗ ਬੀਚ ਮ੍ਰਿਗੀ ਪਿਖੀਐ ਹਰਿ ਤਿਉ ਗਨ ਗ੍ਵਾਰਿਨ ਕੇ ਮਧਿ ਸੋਭੈ।","roman":"Jiu mrig beech mrigee pikheeai hari tiu gan gvaarin ke madhi sobhai |","meaning_en":"","page":408},{"gurmukhi":"ਦੇਖਿ ਜਿਸੈ ਰਿਪੁ ਰੀਝ ਰਹੈ ਕਬਿ ਸ੍ਯਾਮ ਨਹੀ ਮਨ ਭੀਤਰ ਛੋਭੈ।","roman":"Dekhi jisai ripu reejh rahai kabi syaam nahee man bheetar chhobhai |","meaning_en":"","page":408},{"gurmukhi":"ਦੇਖਿ ਜਿਸੈ ਮ੍ਰਿਗ ਧਾਵਤ ਆਵਤ ਚਿਤ ਕਰੈ ਨ ਹਮੈ ਫੁਨਿ ਕੋ ਭੈ।","roman":"Dekhi jisai mrig dhaavat aavat chit karai na hamai phuni ko bhai |","meaning_en":"","page":408},{"gurmukhi":"ਸੋ ਬਨ ਬੀਚ ਬਿਰਾਜਤ ਕਾਨ੍ਹ ਜੋਊ ਪਿਖਵੈ ਤਿਹ ਕੋ ਮਨੁ ਲੋਭੈ। ੪੭੦।","roman":"So ban beech biraajat kaanh jo'oo pikhvai tih ko manu lobhai | 470 |","meaning_en":"","page":408}]},{"type":"heading","kind":"speaker","name":"ਗੋਪੀ ਬਾਚ ਕਾਨ੍ਹ ਜੂ ਸੋ","gurmukhi":"ਗੋਪੀ ਬਾਚ ਕਾਨ੍ਹ ਜੂ ਸੋ","roman":"Gopee baach kaanh joo so","meaning_en":"","page":408},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":408},{"type":"verse","number":[471],"number_text":"੪੭੧।","page":408,"lines":[{"gurmukhi":"ਸੋਊ ਗ੍ਵਾਰਿਨ ਬੋਲਿ ਉਠੀ ਹਰਿ ਸੋ ਬਚਨਾ ਜਿਨ ਕੇ ਸਮ ਸੁਧ ਅਮੀ।","roman":"So'oo gvaarin boli uthee hari so bachnaa jin ke sam sudh amee |","meaning_en":"","page":408},{"gurmukhi":"ਤਿਹ ਸਾਥ ਲਗੀ ਚਰਚਾ ਕਰਨੇ ਹਰਤਾ ਮਨ ਸਾਧਨ ਸੁਧਿ ਗਮੀ।","roman":"Tih saath lagee charchaa karne hartaa man saadhan sudhi gamee |","meaning_en":"","page":408},{"gurmukhi":"ਤਜ ਕੈ ਅਪੁਨੇ ਭਰਤਾ ਹਮਰੀ ਮਤਿ ਕਾਨ੍ਹ ਜੂ ਊਪਰਿ ਤੋਹਿ ਰਮੀ।","roman":"Taj kai apune bhartaa hamree mati kaanh joo oopri tohi ramee |","meaning_en":"","page":408},{"gurmukhi":"ਅਤਿ ਹੀ ਤਨ ਕਾਮ ਕਰਾ ਉਪਜੀ ਤੁਮ ਕੋ ਪਿਖਏ ਨਹਿ ਜਾਤ ਛਮੀ। ੪੭੧।","roman":"Ati hee tan kaam karaa upjee tum ko pikhae nahi jaat chhamee | 471 |","meaning_en":"","page":408}]},{"type":"heading","kind":"speaker","name":"ਕਬਿਯੋ ਬਾਚ","gurmukhi":"ਕਬਿਯੋ ਬਾਚ","roman":"Kabiyo baach","meaning_en":"","page":408},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":408},{"type":"verse","number":[472],"number_text":"੪੭੨।","page":408,"lines":[{"gurmukhi":"ਭਗਵਾਨਿ ਲਖੀ ਅਪੁਨੇ ਮਨ ਮੈ ਇਹ ਗ੍ਵਾਰਨਿ ਮੋ ਪਿਖਿ ਮੈਨ ਭਰੀ।","roman":"Bhagvaani lakhee apune man mai ih gvaarni mo pikhi main bharee |","meaning_en":"","page":408},{"gurmukhi":"ਤਬ ਹੀ ਤਜਿ ਸੰਕ ਸਭੈ ਮਨ ਕੀ ਤਿਨ ਕੇ ਸੰਗਿ ਮਾਨੁਖ ਕੇਲ ਕਰੀ।","roman":"Tab hee taji sank sabhai man kee tin ke sangi maanukh kel karee |","meaning_en":"","page":408},{"gurmukhi":"ਹਰਿ ਜੀ ਕਰਿ ਖੇਲ ਕਿਧੌ ਇਨ ਸੋ ਜਨੁ ਕਾਮ ਜਰੀ ਇਹ ਕੀਨ ਜਰੀ।","roman":"Hari jee kari khel kidhau in so janu kaam jaree ih keen jaree |","meaning_en":"","page":408},{"gurmukhi":"ਕਬਿ ਸ੍ਯਾਮ ਕਹੈ ਪਿਖਵੋ ਤੁਮ ਕੌਤੁਕ ਕਾਨ੍ਹ ਹਰਿਯੋ ਕਿ ਹਰੀ ਸੁ ਹਰੀ।੪੭੨।","roman":"Kabi syaam kahai pikhvo tum kautuk kaanh hariyo ki haree su haree | 472 |","meaning_en":"","page":408}]},{"type":"verse","number":[473],"number_text":"੪੭੩।","page":408,"lines":[{"gurmukhi":"ਜੋ ਜੁਗ ਤੀਸਰ ਮੂਰਤਿ ਰਾਮ ਧਰੀ ਜਿਹ ਅਉਰ ਕਰਿਯੋ ਅਤਿ ਸੀਲਾ।","roman":"Jo jug teesar moorti raam dharee jih aur kariyo ati seelaa |","meaning_en":"","page":408},{"gurmukhi":"ਸਤ੍ਰਨ ਕੋ ਸੁ ਸੰਘਾਰਿ ਕਹੈ ਪ੍ਰਤਿਪਾਰਕ ਸਾਧਨ ਕੋ ਹਰਿ ਹੀਲਾ।","roman":"Satran ko su sanghaari kahai pratipaarak saadhan ko hari heelaa |","meaning_en":"","page":408},{"gurmukhi":"ਦਵਾਪਰ ਮੋ ਸੋਊ ਕਾਨ੍ਹ ਭਯੋ ਮਰੀਯਾ ਅਰਿ ਕੋ ਧਰੀਯਾ ਪਟ ਪੀਲਾ।","roman":"Davaapar mo so'oo kaanh bhayo mareeyaa ari ko dhareeyaa pat peelaa |","meaning_en":"","page":408},{"gurmukhi":"ਸੋ ਹਰਿ ਭੂਮਿ ਬਿਖੈ ਬ੍ਰਿਜ ਕੀ ਹਸਿ ਗੋਪਿਨ ਸਾਥ ਕਰੈ ਰਸ ਲੀਲਾ। ੪੭੩।","roman":"So hari bhoomi bikhai brij kee hasi gopin saath karai ras leelaa | 473 |","meaning_en":"","page":408}]},{"type":"verse","number":[474],"number_text":"੪੭੪।","page":408,"lines":[{"gurmukhi":"ਮਾਲਸਿਰੀ ਅਰੁ ਰਾਮਕਲੀ ਸੁਭ ਸਾਰੰਗ ਭਾਵਨ ਸਾਥ ਬਜਾਵੈ।","roman":"Maalsiree aru raamaklee subh saarang bhaavan saath bajaavai |","meaning_en":"","page":408},{"gurmukhi":"ਜੈਤਸਿਰੀ ਅਰੁ ਸੁਧ ਮਲ੍ਹਾਰ ਬਿਲਾਵਲ ਕੀ ਧੁਨਿ ਕੂਕਿ ਸੁਨਾਵੈ।","roman":"Jaitsiree aru sudh malhaar bilaaval kee dhuni kooki sunaavai |","meaning_en":"","page":408},{"gurmukhi":"ਲੈ ਮੁਰਲੀ ਅਪੁਨੇ ਕਰਿ ਕਾਨ੍ਹ ਕਿਧੋ ਅਤਿ ਭਾਵਨ ਸਾਥ ਬਜਾਵੈ।","roman":"Lai murlee apune kari kaanh kidho ati bhaavan saath bajaavai |","meaning_en":"","page":408},{"gurmukhi":"ਪਉਨ ਚਲੈ ਨ ਰਹੈ ਜਮੁਨਾ ਥਿਰ ਮੋਹਿ ਰਹੈ ਧੁਨਿ ਜੋ ਸੁਨਿ ਪਾਵੈ। ੪੭੪।","roman":"Paun chalai na rahai jamunaa thir mohi rahai dhuni jo suni paavai | 474 |","meaning_en":"","page":408}]},{"type":"verse","number":[475],"number_text":"੪੭੫।","page":409,"lines":[{"gurmukhi":"ਕਾਨ੍ਹ ਬਜਾਵਤ ਹੈ ਸੁਰ ਸੋ ਫੁਨਿ ਗੋਪਿਨ ਕੇ ਮਨ ਮੈ ਜੋਊ ਭਾਵੈ।","roman":"Kaanh bajaavat hai sur so phuni gopin ke man mai jo'oo bhaavai |","meaning_en":"","page":409},{"gurmukhi":"ਰਾਮਕਲੀ ਅਰੁ ਸੁਧ ਮਲ੍ਹਾਰ ਬਿਲਾਵਲ ਕੀ ਅਤਿ ਹੀ ਠਟ ਪਾਵੈ।","roman":"Raamaklee aru sudh malhaar bilaaval kee ati hee that paavai |","meaning_en":"","page":409},{"gurmukhi":"ਰੀਝਿ ਰਹੈ ਸੁ ਸੁਰੀ ਅਸੁਰੀ ਮ੍ਰਿਗ ਛਾਡਿ ਮ੍ਰਿਗੀ ਬਨ ਕੀ ਚਲਿ ਆਵੈ।","roman":"Reejhi rahai su suree asuree mrig chhaadi mrigee ban kee chali aavai |","meaning_en":"","page":409},{"gurmukhi":"ਸੋ ਮੁਰਲੀ ਮਹਿ ਸ੍ਯਾਮ ਪ੍ਰਬੀਨ ਮਨੋ ਕਰਿ ਰਾਗਨ ਰੂਪ ਦਿਖਾਵੈ। ੪੭੫।","roman":"So murlee mahi syaam prabeen mano kari raagan roop dikhaavai | 475 |","meaning_en":"","page":409}]},{"type":"verse","number":[476],"number_text":"੪੭੬।","page":409,"lines":[{"gurmukhi":"ਸੁਨ ਕੈ ਮੁਰਲੀ ਧੁਨਿ ਕਾਨਰ ਕੀ ਮਨ ਮੈ ਸਭ ਗ੍ਵਾਰਿਨ ਰੀਝਿ ਰਹੀ ਹੈ।","roman":"Sun kai murlee dhuni kaanar kee man mai sabh gvaarin reejhi rahee hai |","meaning_en":"","page":409},{"gurmukhi":"ਜੋ ਗ੍ਰਿਹ ਲੋਗਨ ਬਾਤ ਕਹੀ ਤਿਨ ਹੂੰ ਫੁਨਿ ਊਪਰਿ ਸੀਸ ਸਹੀ ਹੈ।","roman":"Jo grih logan baat kahee tin hoon phuni oopri sees sahee hai |","meaning_en":"","page":409},{"gurmukhi":"ਸਾਮੁਹਿ ਧਾਇ ਚਲੀ ਹਰਿ ਕੇ ਉਪਮਾ ਤਿਹ ਕੀ ਕਬਿ ਸ੍ਯਾਮ ਕਹੀ ਹੈ।","roman":"Saamuhi dhaai chalee hari ke upmaa tih kee kabi syaam kahee hai |","meaning_en":"","page":409},{"gurmukhi":"ਮਾਨਹੁ ਪੇਖਿ ਸਮਸਨ ਕੇ ਮੁਖ ਧਾਇ ਚਲੀ ਮਿਲਿ ਜੂਥ ਅਹੀ ਹੈ। ੪੭੬।","roman":"Maanhu pekhi samsan ke mukh dhaai chalee mili jooth ahee hai | 476 |","meaning_en":"","page":409}]},{"type":"verse","number":[477],"number_text":"੪੭੭।","page":409,"lines":[{"gurmukhi":"ਜਿਨਿ ਰੀਝਿ ਬਿਭੀਛਨ ਰਾਜੁ ਦਯੋ ਕੁਪ ਕੈ ਦਸ ਸੀਸ ਦਈ ਜਿਨਿ ਪੀੜਾ।","roman":"Jini reejhi bibheechhan raaju dayo kup kai das sees daee jini peeraa |","meaning_en":"","page":409},{"gurmukhi":"ਮਾਰੁਤ ਹ੍ਵੈ ਦਲ ਦੈਤਨ ਕੋ ਛਿਨ ਮੈ ਘਨ ਸੋ ਕਰ ਦੀਨ ਉਝੀੜਾ।","roman":"Maarut hvai dal daitan ko chhin mai ghan so kar deen ujheeraa |","meaning_en":"","page":409},{"gurmukhi":"ਜਾਹਿ ਮਰਿਯੋ ਮੁਰ ਨਾਮ ਮਹਾ ਸੁਰ ਆਪਨ ਹੀ ਲੰਘਿ ਮਾਰਗੁ ਭੀੜਾ।","roman":"Jaahi mariyo mur naam mahaa sur aapan hee langhi maargu bheeraa |","meaning_en":"","page":409},{"gurmukhi":"ਸੋ ਫੁਨਿ ਭੂਮਿ ਬਿਖੈ ਬ੍ਰਿਜ ਕੀ ਸੰਗਿ ਗੋਪਿਨ ਕੈ ਸੁ ਕਰੈ ਰਸ ਕ੍ਰੀੜਾ। ੪੭੭।","roman":"So phuni bhoomi bikhai brij kee sangi gopin kai su karai ras kreeraa | 477 |","meaning_en":"","page":409}]},{"type":"verse","number":[478],"number_text":"੪੭੮।","page":409,"lines":[{"gurmukhi":"ਖੇਲਤ ਕਾਨ੍ਹ ਸੋਊ ਤਿਨ ਸੋ ਜਿਹ ਕੀ ਸੁ ਕਰੈ ਸਭ ਹੀ ਜਗ ਜਾਤ੍ਰਾ।","roman":"Khelat kaanh so'oo tin so jih kee su karai sabh hee jag jaatraa |","meaning_en":"","page":409},{"gurmukhi":"ਸੋ ਸਭ ਹੀ ਜਗ ਕੋ ਪਤਿ ਹੈ ਤਿਨ ਜੀਵਨ ਕੇ ਬਲ ਕੀ ਪਰ ਮਾਤ੍ਰਾ।","roman":"So sabh hee jag ko pati hai tin jeevan ke bal kee par maatraa |","meaning_en":"","page":409},{"gurmukhi":"ਰਾਮ ਹ੍ਵੈ ਰਾਵਨ ਸੋ ਜਿਨ ਹੂੰ ਕੁਪਿ ਜੁਧ ਕਰਿਯੋ ਕਰਿ ਕੈ ਪ੍ਰਮ ਛਾਤ੍ਰਾ।","roman":"Raam hvai raavan so jin hoon kupi judh kariyo kari kai pram chhaatraa |","meaning_en":"","page":409},{"gurmukhi":"ਸੋ ਹਰਿ ਬੀਚ ਅਹੀਰਿਨ ਕੇ ਕਰਿਬੇ ਕਹੁ ਕਉਤੁਕ ਕੀਨ ਸੁ ਨਾਤ੍ਰਾ। ੪੭੮।","roman":"So hari beech aheerin ke karibe kahu kautuk keen su naatraa | 478 |","meaning_en":"","page":409}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":409},{"type":"verse","number":[479],"number_text":"੪੭੯।","page":409,"lines":[{"gurmukhi":"ਜਬੈ ਕ੍ਰਿਸਨ ਸੰਗ ਗੋਪੀਅਨ ਕਰੀ ਮਾਨੁਖੀ ਬਾਨ।","roman":"Jabai krisan sang gopeean karee maanukhee baan |","meaning_en":"","page":409},{"gurmukhi":"ਸਭ ਗੋਪੀ ਤਬ ਯੌ ਲਖਿਯੋ ਭਯੋ ਬਸ੍ਯ ਭਗਵਾਨ। ੪੭੯।","roman":"Sabh gopee tab yau lakhiyo bhayo basy bhagvaan | 479 |","meaning_en":"","page":409}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":409},{"type":"verse","number":[480],"number_text":"੪੮੦।","page":409,"lines":[{"gurmukhi":"ਕਾਨ੍ਹ ਤਬੈ ਸੰਗ ਗੋਪਿਨ ਕੇ ਤਬ ਹੀ ਫੁਨਿ ਅੰਤ੍ਰ ਧਿਆਨ ਹ੍ਵੈ ਗਈਯਾ।","roman":"Kaanh tabai sang gopin ke tab hee phuni antr dhiaan hvai gaeeyaa |","meaning_en":"","page":409},{"gurmukhi":"ਖੇ ਕਹ ਗਯੋ ਧਰਨੀ ਧਸਿ ਗਯੋ ਕਿਧੋ ਮਧਿ ਰਹਿਯੋ ਸਮਝਿਯੋ ਨਹੀ ਪਈਯਾ।","roman":"Khe kah gayo dharnee dhasi gayo kidho madhi rahiyo samjhiyo nahee paeeyaa |","meaning_en":"","page":409},{"gurmukhi":"ਗੋਪਿਨ ਕੀ ਜਬ ਯੌ ਗਤਿ ਭੀ ਤਬ ਤਾ ਛਬਿ ਕੋ ਕਬਿ ਸ੍ਯਾਮ ਕਹਇਯਾ।","roman":"Gopin kee jab yau gati bhee tab taa chhabi ko kabi syaam kahaiyaa |","meaning_en":"","page":409},{"gurmukhi":"ਜਿਉ ਸੰਗ ਮੀਨਨ ਕੇ ਲਰ ਕੈ ਤਿਨ ਤ੍ਯਾਗ ਸਭੋ ਮਨੋ ਬਾਰਿ ਧਰਇਯਾ।੪੮੦।","roman":"Jiu sang meenan ke lar kai tin tyaag sabho mano baari dharaiyaa | 480 |","meaning_en":"","page":409}]},{"type":"verse","number":[481],"number_text":"੪੮੧।","page":409,"lines":[{"gurmukhi":"ਗੋਪਿਨ ਕੇ ਤਨ ਕੀ ਛੁਟਗੀ ਸੁਧਿ ਡੋਲਤ ਹੈ ਬਨ ਮੈ ਜਨੁ ਬਉਰੀ।","roman":"Gopin ke tan kee chhutgee sudhi dolat hai ban mai janu bauree |","meaning_en":"","page":409},{"gurmukhi":"ਏਕ ਉਠੈ ਇਕ ਝੂਮਿ ਗਿਰੈ ਬ੍ਰਿਜ ਕੀ ਮਹਰੀ ਇਕ ਆਵਤ ਦਉਰੀ।","roman":"Ek uthai ik jhoomi girai brij kee mahree ik aavat dauree |","meaning_en":"","page":409},{"gurmukhi":"ਆਤੁਰ ਹ੍ਵੈ ਅਤਿ ਢੂੰਡਤ ਹੈ ਤਿਨ ਕੇ ਸਿਰ ਕੀ ਗਿਰ ਗੀ ਸੁ ਪਿਛਉਰੀ।","roman":"Aatur hvai ati dhoondat hai tin ke sir kee gir gee su pichhauree |","meaning_en":"","page":410},{"gurmukhi":"ਕਾਨ੍ਹ ਕੋ ਧ੍ਯਾਨ ਬਸਿਯੋ ਮਨ ਮੈ ਸੋਊ ਜਾਨ ਗਹੈ ਫੁਨਿ ਰੂਖਨ ਕਉਰੀ। ੪੮੧।","roman":"Kaanh ko dhyaan basiyo man mai so'oo jaan gahai phuni rookhan kauree | 481 |","meaning_en":"","page":410}]},{"type":"verse","number":[482],"number_text":"੪੮੨।","page":410,"lines":[{"gurmukhi":"ਫੇਰਿ ਤਜੈ ਤਿਨ ਰੂਖਨ ਕੋ ਇਹ ਭਾਤਿ ਕਹੈ ਨੰਦ ਲਾਲ ਕਹਾ ਰੇ।","roman":"Pheri tajai tin rookhan ko ih bhaati kahai nand laal kahaa re |","meaning_en":"","page":410},{"gurmukhi":"ਚੰਪਕ ਮਉਲਸਿਰੀ ਬਟ ਤਾਲ ਲਵੰਗ ਲਤਾ ਕਚਨਾਰ ਜਹਾ ਰੇ।","roman":"Chanpak maulsiree bat taal lavang lataa kachnaar jahaa re |","meaning_en":"","page":410},{"gurmukhi":"ਪੈ ਜਿਹ ਕੇ ਹਮ ਕਾਰਨ ਕੋ ਪਗਿ ਕੰਟਕਕਾ ਸਿਰਿ ਧੂਪ ਸਹਾ ਰੇ।","roman":"Pai jih ke ham kaaran ko pagi kantakkaa siri dhoop sahaa re |","meaning_en":"","page":410},{"gurmukhi":"ਸੋ ਹਮ ਕੌ ਤੁਮ ਦੇਹੁ ਬਤਾਇ ਪਰੈ ਤੁਮ ਪਾਇਨ ਜਾਵ ਤਹਾ ਰੇ। ੪੮੨।","roman":"So ham kau tum dehu bataai parai tum paain jaav tahaa re | 482 |","meaning_en":"","page":410}]},{"type":"verse","number":[483],"number_text":"੪੮੩।","page":410,"lines":[{"gurmukhi":"ਬੇਲ ਬਿਰਾਜਤ ਹੈ ਜਿਹ ਜਾ ਗੁਲ ਚੰਪਕ ਕਾ ਸੁ ਪ੍ਰਭਾ ਅਤਿ ਪਾਈ।","roman":"Bel biraajat hai jih jaa gul chanpak kaa su prabhaa ati paaee |","meaning_en":"","page":410},{"gurmukhi":"ਮੌਲਿਸਿਰੀ ਗੁਲ ਲਾਲ ਗੁਲਾਬ ਧਰਾ ਤਿਨ ਫੂਲਨ ਸੋ ਛਬਿ ਛਾਈ।","roman":"Maulisiree gul laal gulaab dharaa tin phoolan so chhabi chhaaee |","meaning_en":"","page":410},{"gurmukhi":"ਚੰਪਕ ਮਉਲਸਿਰੀ ਬਟ ਤਾਲ ਲਵੰਗ ਲਤਾ ਕਚਨਾਰ ਸੁਹਾਈ।","roman":"Chanpak maulsiree bat taal lavang lataa kachnaar suhaaee |","meaning_en":"","page":410},{"gurmukhi":"ਬਾਰਿ ਝਰੈ ਝਰਨਾ ਗਿਰਿ ਤੇ ਕਬਿ ਸ੍ਯਾਮ ਕਹੈ ਅਤਿ ਹੀ ਸੁਖਦਾਈ। ੪੮੩।","roman":"Baari jharai jharnaa giri te kabi syaam kahai ati hee sukhdaaee | 483 |","meaning_en":"","page":410}]},{"type":"verse","number":[484],"number_text":"੪੮੪।","page":410,"lines":[{"gurmukhi":"ਤਿਹ ਕਾਨਨ ਕੋ ਹਰਿ ਕੇ ਹਿਤ ਤੇ ਗੁਪੀਆ ਬ੍ਰਿਜ ਕੀ ਇਹ ਭਾਤਿ ਸ ਕਹੈ।","roman":"Tih kaanan ko hari ke hit te gupeeaa brij kee ih bhaati sa kahai |","meaning_en":"","page":410},{"gurmukhi":"ਬਰ ਪੀਪਰ ਹੇਰਿ ਹਿਯਾ ਨ ਕਹੂੰ ਜਿਹ ਕੇ ਹਿਤ ਸੋ ਸਿਰਿ ਧੂਪ ਸਹੈ।","roman":"Bar peepar heri hiyaa na kahoon jih ke hit so siri dhoop sahai |","meaning_en":"","page":410},{"gurmukhi":"ਅਹੋ ਕਿਉ ਤਜਿ ਆਵਤ ਹੋ ਭਰਤਾ ਬਿਨੁ ਕਾਨ੍ਹ ਪਿਖੇ ਨਹਿ ਧਾਮਿ ਰਹੈ।","roman":"Aho kiu taji aavat ho bhartaa binu kaanh pikhe nahi dhaami rahai |","meaning_en":"","page":410},{"gurmukhi":"ਇਕ ਬਾਤ ਕਰੈ ਸੁਨ ਕੈ ਇਕ ਬੋਲਬ ਰੂਖਨ ਕੋ ਹਰਿ ਜਾਨਿ ਗਹੈ। ੪੮੪।","roman":"Ik baat karai sun kai ik bolab rookhan ko hari jaani gahai | 484 |","meaning_en":"","page":410}]},{"type":"verse","number":[485],"number_text":"੪੮੫।","page":410,"lines":[{"gurmukhi":"ਕਾਨ੍ਹ ਬਿਯੋਗ ਕੋ ਮਾਨਿ ਬਧੂ ਬ੍ਰਿਜ ਡੋਲਤ ਹੈ ਬਨ ਬੀਚ ਦਿਵਾਨੀ।","roman":"Kaanh biyog ko maani badhoo brij dolat hai ban beech divaanee |","meaning_en":"","page":410},{"gurmukhi":"ਕੂੰਜਨ ਜਯੋ ਕੁਰਲਾਤ ਫਿਰੈ ਤਿਹ ਜਾ ਜਿਹ ਜਾ ਕਛੁ ਖਾਨ ਨ ਪਾਨੀ।","roman":"Koonjan jayo kurlaat phirai tih jaa jih jaa kachhu khaan na paanee |","meaning_en":"","page":410},{"gurmukhi":"ਏਕ ਗਿਰੈ ਮੁਰਝਾਇ ਧਰਾ ਪਰ ਏਕ ਉਠੈ ਕਹਿ ਕੈ ਇਹ ਬਾਨੀ।","roman":"Ek girai murjhaai dharaa par ek uthai kahi kai ih baanee |","meaning_en":"","page":410},{"gurmukhi":"ਨੇਹੁ ਬਢਾਇ ਮਹਾ ਹਮ ਸੋ ਕਤ ਜਾਤ ਭਯੋ ਭਗਵਾਨ ਗੁਮਾਨੀ। ੪੮੫।","roman":"Nehu badhaai mahaa ham so kat jaat bhayo bhagvaan gumaanee | 485 |","meaning_en":"","page":410}]},{"type":"verse","number":[486],"number_text":"੪੮੬।","page":410,"lines":[{"gurmukhi":"ਨੈਨ ਨਚਾਇ ਮਨੋ ਮ੍ਰਿਗ ਸੇ ਸਭ ਗੋਪਿਨ ਕੋ ਮਨ ਚੋਰਿ ਲਯੋ ਹੈ।","roman":"Nain nachaai mano mrig se sabh gopin ko man chori layo hai |","meaning_en":"","page":410},{"gurmukhi":"ਤਾਹੀ ਕੈ ਬੀਚ ਰਹਿਯੋ ਗਡਿ ਕੈ ਤਿਹ ਤੇ ਨਹਿ ਛੂਟਨ ਨੈਕੁ ਭਯੋ ਹੈ।","roman":"Taahee kai beech rahiyo gadi kai tih te nahi chhootan naiku bhayo hai |","meaning_en":"","page":410},{"gurmukhi":"ਤਾਹੀ ਕੇ ਹੇਤ ਫਿਰੈ ਬਨ ਮੈ ਤਜਿ ਕੈ ਗ੍ਰਿਹ ਸ੍ਵਾਸ ਨ ਏਕ ਲਯੋ ਹੈ।","roman":"Taahee ke het phirai ban mai taji kai grih svaas na ek layo hai |","meaning_en":"","page":410},{"gurmukhi":"ਸੋ ਬਿਰਥਾ ਹਮ ਸੋ ਬਨ ਭ੍ਰਾਤ ਕਹੋ ਹਰਿ ਜੀ ਕਿਹ ਓਰਿ ਗਯੋ ਹੈ। ੪੮੬।","roman":"So birthaa ham so ban bhraat kaho hari jee kih ori gayo hai | 486 |","meaning_en":"","page":410}]},{"type":"verse","number":[487],"number_text":"੪੮੭।","page":410,"lines":[{"gurmukhi":"ਜਿਨ ਹੂੰ ਬਨ ਬੀਚ ਮਰੀਚ ਮਰਿਯੋ ਪੁਰ ਰਾਵਨਿ ਸੇਵਕ ਜਾਹਿ ਦਹਿਯੋ ਹੈ।","roman":"Jin hoon ban beech mareech mariyo pur raavni sevak jaahi dahiyo hai |","meaning_en":"","page":410},{"gurmukhi":"ਤਾਹੀ ਸੋ ਹੇਤ ਕਰਿਯੋ ਹਮ ਹੂੰ ਬਹੁ ਲੋਗਨ ਕੋ ਉਪਹਾਸ ਸਹਿਯੋ ਹੈ।","roman":"Taahee so het kariyo ham hoon bahu logan ko uphaas sahiyo hai |","meaning_en":"","page":410},{"gurmukhi":"ਵਾਸਰ ਸੇ ਦ੍ਰਿਗ ਸੁੰਦਰ ਸੋ ਮਿਲਿ ਗ੍ਵਾਰਿਨਿਯਾ ਇਹ ਭਾਤਿ ਕਹਿਯੋ ਹੈ।","roman":"Vaasar se drig sundar so mili gvaariniyaa ih bhaati kahiyo hai |","meaning_en":"","page":410},{"gurmukhi":"ਤਾਹੀ ਕੀ ਚੋਟ ਚਟਾਕ ਲਗੇ ਹਮਰੋ ਮਨੂਆ ਮ੍ਰਿਗ ਠਉਰ ਰਹਿਯੋ ਹੈ। ੪੮੭।","roman":"Taahee kee chot chataak lage hamro manooaa mrig thaur rahiyo hai | 487 |","meaning_en":"","page":410}]},{"type":"verse","number":[488],"number_text":"੪੮੮।","page":411,"lines":[{"gurmukhi":"ਬੇਦ ਪੜੈ ਸਮ ਕੋ ਫਲ ਹੋ ਬਹੁ ਮੰਗਨ ਕੋ ਜੋਊ ਦਾਨ ਦਿਵਾਵੈ।","roman":"Bed parai sam ko phal ho bahu mangan ko jo'oo daan divaavai |","meaning_en":"","page":411},{"gurmukhi":"ਕੀਨ ਅਕੀਨ ਲਖੈ ਫਲ ਹੋ ਜੋਊ ਆਥਿਤ ਲੋਗਨ ਅੰਨ ਜਿਵਾਵੈ।","roman":"Keen akeen lakhai phal ho jo'oo aathit logan ann jivaavai |","meaning_en":"","page":411},{"gurmukhi":"ਦਾਨ ਲਹੈ ਹਮਰੇ ਜੀਅ ਕੋ ਇਹ ਕੇ ਸਮ ਕੋ ਨ ਸੋਊ ਫਲ ਪਾਵੈ।","roman":"Daan lahai hamre jeea ko ih ke sam ko na so'oo phal paavai |","meaning_en":"","page":411},{"gurmukhi":"ਜੋ ਬਨ ਮੈ ਹਮ ਕੋ ਜਰਰਾ ਇਕ ਏਕ ਘਰੀ ਭਗਵਾਨ ਦਿਖਾਵੈ। ੪੮੮।","roman":"Jo ban mai ham ko jarraa ik ek gharee bhagvaan dikhaavai | 488 |","meaning_en":"","page":411}]},{"type":"verse","number":[489],"number_text":"੪੮੯।","page":411,"lines":[{"gurmukhi":"ਜਾਹਿ ਬਿਭੀਛਨ ਲੰਕ ਦਈ ਅਰੁ ਦੈਤਨ ਕੇ ਕੁਪਿ ਕੈ ਗਨ ਮਾਰੇ।","roman":"Jaahi bibheechhan lank daee aru daitan ke kupi kai gan maare |","meaning_en":"","page":411},{"gurmukhi":"ਪੈ ਤਿਨ ਹੂੰ ਕਬਿ ਸ੍ਯਾਮ ਕਹੈ ਸਭ ਸਾਧਨ ਰਾਖਿ ਅਸਾਧ ਸੰਘਾਰੇ।","roman":"Pai tin hoon kabi syaam kahai sabh saadhan raakhi asaadh sanghaare |","meaning_en":"","page":411},{"gurmukhi":"ਸੋ ਇਹ ਜਾ ਹਮ ਤੇ ਛਪ ਗਯੋ ਅਤਿ ਹੀ ਕਰ ਕੈ ਸੰਗਿ ਪ੍ਰੀਤਿ ਹਮਾਰੇ।","roman":"So ih jaa ham te chhap gayo ati hee kar kai sangi preeti hamaare |","meaning_en":"","page":411},{"gurmukhi":"ਪਾਇ ਪਰੋ ਕਹੀਯੋ ਬਨ ਭ੍ਰਾਤ ਕਹੋ ਹਰਿ ਜੀ ਕਿਹ ਓਰਿ ਪਧਾਰੇ। ੪੮੯।","roman":"Paai paro kaheeyo ban bhraat kaho hari jee kih ori padhaare | 489 |","meaning_en":"","page":411}]},{"type":"verse","number":[490],"number_text":"੪੯੦।","page":411,"lines":[{"gurmukhi":"ਗ੍ਵਾਰਿਨ ਖੋਜਿ ਰਹੀ ਬਨ ਮੈ ਹਰਿ ਜੀ ਬਨ ਮੈ ਨਹੀ ਖੋਜਤ ਪਾਏ।","roman":"Gvaarin khoji rahee ban mai hari jee ban mai nahee khojat paae |","meaning_en":"","page":411},{"gurmukhi":"ਏਕ ਬਿਚਾਰ ਕਰਿਯੋ ਮਨ ਮੈ ਫਿਰ ਕੈ ਨ ਗਯੋ ਕਬਹੂੰ ਉਹ ਜਾਏ।","roman":"Ek bichaar kariyo man mai phir kai na gayo kabhoon uh jaae |","meaning_en":"","page":411},{"gurmukhi":"ਫੇਰਿ ਫਿਰੀ ਮਨ ਮੈ ਗਿਨਤੀ ਕਰਿ ਪਾਰਥ ਸੂਤ ਕੀ ਡੋਰ ਲਗਾਏ।","roman":"Pheri phiree man mai gintee kari paarath soot kee dor lagaae |","meaning_en":"","page":411},{"gurmukhi":"ਯੌ ਉਪਜੀ ਉਪਮਾ ਚਕਈ ਜਨੁ ਆਵਤ ਹੈ ਕਰ ਮੈ ਫਿਰਿ ਧਾਏ। ੪੯੦।","roman":"Yau upjee upmaa chakaee janu aavat hai kar mai phiri dhaae | 490 |","meaning_en":"","page":411}]},{"type":"verse","number":[491],"number_text":"੪੯੧।","page":411,"lines":[{"gurmukhi":"ਆਇ ਕੇ ਢੂੰਢਿ ਰਹੀ ਸੋਊ ਠਉਰ ਤਹਾ ਭਗਵਾਨ ਨ ਢੂੰਢਡ ਪਾਏ।","roman":"Aai ke dhoondhi rahee so'oo thaur tahaa bhagvaan na dhoondhad paae |","meaning_en":"","page":411},{"gurmukhi":"ਇਉ ਜੁ ਰਹੀ ਸਭ ਹੀ ਚਕਿ ਕੈ ਜਨੁ ਚਿਤ੍ਰ ਲਿਖੀ ਪ੍ਰਿਤਿਮਾ ਛਬਿ ਪਾਏ।","roman":"Iu ju rahee sabh hee chaki kai janu chitr likhee pritimaa chhabi paae |","meaning_en":"","page":411},{"gurmukhi":"ਅਉਰ ਉਪਾਵ ਕਰਿਯੋ ਪੁਨਿ ਗ੍ਵਾਰਿਨ ਕਾਨ੍ਹ ਹੀ ਭੀਤਰਿ ਚਿਤ ਲਗਾਏ।","roman":"Aur upaav kariyo puni gvaarin kaanh hee bheetri chit lagaae |","meaning_en":"","page":411},{"gurmukhi":"ਗਾਇ ਉਠੀ ਤਿਹ ਕੇ ਗੁਨ ਏਕ ਬਜਾਇ ਉਠੀ ਇਕ ਸ੍ਵਾਗ ਲਗਾਏ। ੪੯੧।","roman":"Gaai uthee tih ke gun ek bajaai uthee ik svaag lagaae | 491 |","meaning_en":"","page":411}]},{"type":"verse","number":[492],"number_text":"੪੯੨।","page":411,"lines":[{"gurmukhi":"ਹੋਤ ਬਕੀ ਇਕ ਹੋਤ ਤ੍ਰਿਣਾਵ੍ਰਤ ਏਕ ਅਘਾਸੁਰ ਹ੍ਵੈ ਕਰਿ ਧਾਵੈ।","roman":"Hot bakee ik hot trinaavrat ek aghaasur hvai kari dhaavai |","meaning_en":"","page":411},{"gurmukhi":"ਹੋਇ ਹਰੀ ਤਿਨ ਮੈ ਧਸਿ ਕੈ ਧਰਨੀ ਪਰ ਤਾ ਕਹੁ ਮਾਰਿ ਗਿਰਾਵੈ।","roman":"Hoi haree tin mai dhasi kai dharnee par taa kahu maari giraavai |","meaning_en":"","page":411},{"gurmukhi":"ਕਾਨ੍ਹ ਸੋ ਲਾਗ ਰਹਿਯੋ ਤਿਨ ਕੌ ਅਤ ਹੀ ਮਨ ਨੈਕ ਨ ਛੂਟਨ ਪਾਵੈ।","roman":"Kaanh so laag rahiyo tin kau at hee man naik na chhootan paavai |","meaning_en":"","page":411},{"gurmukhi":"ਇਉ ਉਪਜੀ ਉਪਮਾ ਬਨੀਆ ਜਨੁ ਸਾਲਨ ਕੇ ਹਿਤ ਰੋਰ ਬਨਾਵੈ। ੪੯੨।","roman":"Iu upjee upmaa baneeaa janu saalan ke hit ror banaavai | 492 |","meaning_en":"","page":411}]},{"type":"heading","kind":"speaker","name":"ਰਾਜਾ ਪਰੀਛਤ ਬਾਚ ਸੁਕ ਸੋ","gurmukhi":"ਰਾਜਾ ਪਰੀਛਤ ਬਾਚ ਸੁਕ ਸੋ","roman":"Raajaa pareechhat baach suk so","meaning_en":"","page":411},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":411},{"type":"verse","number":[493],"number_text":"੪੯੩।","page":411,"lines":[{"gurmukhi":"ਸੁਕ ਸੰਗ ਰਾਜੇ ਕਹੁ ਕਹੀ ਜੂਥ ਦਿਜਨ ਕੇ ਨਾਥ।","roman":"Suk sang raaje kahu kahee jooth dijan ke naath |","meaning_en":"","page":411},{"gurmukhi":"ਅਗਨਿ ਭਾਵ ਕਿਹ ਬਿਧਿ ਕਹੈ ਕ੍ਰਿਸਨ ਭਾਵ ਕੇ ਸਾਥ।੪੯੩।","roman":"Agni bhaav kih bidhi kahai krisan bhaav ke saath | 493 |","meaning_en":"","page":411}]},{"type":"heading","kind":"speaker","name":"ਸੁਕ ਬਾਚ ਰਾਜਾ ਸੋ","gurmukhi":"ਸੁਕ ਬਾਚ ਰਾਜਾ ਸੋ","roman":"Suk baach raajaa so","meaning_en":"","page":412},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":412},{"type":"verse","number":[494],"number_text":"੪੯੪।","page":412,"lines":[{"gurmukhi":"ਰਾਜਨ ਪਾਸ ਬ੍ਯਾਸ ਕੋ ਬਾਲ ਕਥਾ ਸੁ ਅਰੌਚਕ ਭਾਤਿ ਸੁਨਾਵੈ।","roman":"Raajan paas byaas ko baal kathaa su arauchak bhaati sunaavai |","meaning_en":"","page":412},{"gurmukhi":"ਗ੍ਵਾਰਨੀਆ ਬਿਰਹਾਨੁਲ ਭਾਵ ਕਰੈ ਬਿਰਹਾਨਲ ਕੋ ਉਪਜਾਵੈ।","roman":"Gvaarneeaa birhaanul bhaav karai birhaanal ko upjaavai |","meaning_en":"","page":412},{"gurmukhi":"ਪੰਚ ਭੂ ਆਤਮ ਲੋਗਨ ਕੋ ਇਹ ਕਉਤੁਕ ਕੈ ਅਤਿ ਹੀ ਡਰ ਪਾਵੈ।","roman":"Panch bhoo aatam logan ko ih kautuk kai ati hee dar paavai |","meaning_en":"","page":412},{"gurmukhi":"ਕਾਨ੍ਹ ਕੋ ਧ੍ਯਾਨ ਕਰੇ ਜਬ ਹੀ ਬਿਰਹਾਨਲ ਕੀ ਲਪਟਾਨ ਬੁਝਾਵੈ। ੪੯੪।","roman":"Kaanh ko dhyaan kare jab hee birhaanal kee laptaan bujhaavai | 494 |","meaning_en":"","page":412}]},{"type":"verse","number":[495],"number_text":"੪੯੫।","page":412,"lines":[{"gurmukhi":"ਬ੍ਰਿਖਭਾਸੁਰ ਗ੍ਵਾਰਨਿ ਏਕ ਬਨੈ ਬਛੁਰਾਸੁਰ ਮੂਰਤਿ ਏਕ ਧਰੈ।","roman":"Brikhbhaasur gvaarni ek banai bachhuraasur moorti ek dharai |","meaning_en":"","page":412},{"gurmukhi":"ਇਕ ਹ੍ਵੈ ਚਤੁਰਾਨਨ ਗ੍ਵਾਰ ਹਰੈ ਇਕ ਹ੍ਵੈ ਬ੍ਰਹਮਾ ਫਿਰਿ ਪਾਇ ਪਰੈ।","roman":"Ik hvai chaturaanan gvaar harai ik hvai brahmaa phiri paai parai |","meaning_en":"","page":412},{"gurmukhi":"ਇਕ ਹ੍ਵੈ ਬਗੁਲਾ ਭਗਵਾਨ ਕੇ ਸਾਥ ਮਹਾ ਕਰ ਕੈ ਮਨਿ ਕੋਪ ਲਰੈ।","roman":"Ik hvai bagulaa bhagvaan ke saath mahaa kar kai mani kop larai |","meaning_en":"","page":412},{"gurmukhi":"ਇਹ ਭਾਤਿ ਬਧੂ ਬ੍ਰਿਜ ਖੇਲ ਕਰੈ ਜਿਹ ਭਾਤਿ ਕਿਧੋ ਨੰਦ ਲਾਲ ਕਰੈ। ੪੯੫।","roman":"Ih bhaati badhoo brij khel karai jih bhaati kidho nand laal karai | 495 |","meaning_en":"","page":412}]},{"type":"verse","number":[496],"number_text":"੪੯੬।","page":412,"lines":[{"gurmukhi":"ਕਾਨ੍ਹ ਚਰਿਤ੍ਰ ਸਭੈ ਕਰ ਕੈ ਸਭ ਗ੍ਵਾਰਿਨ ਫੇਰਿ ਲਗੀ ਗੁਨ ਗਾਵਨ।","roman":"Kaanh charitr sabhai kar kai sabh gvaarin pheri lagee gun gaavan |","meaning_en":"","page":412},{"gurmukhi":"ਤਾਲ ਬਜਾਇ ਬਜਾ ਮੁਰਲੀ ਕਬਿ ਸ੍ਯਾਮ ਕਹੈ ਅਤਿ ਹੀ ਕਰਿ ਭਾਵਨ।","roman":"Taal bajaai bajaa murlee kabi syaam kahai ati hee kari bhaavan |","meaning_en":"","page":412},{"gurmukhi":"ਫੇਰਿ ਚਿਤਾਰ ਕਹਿਯੋ ਹਮਰੇ ਸੰਗਿ ਖੇਲ ਕਰਿਯੋ ਹਰਿ ਜੀ ਇਹ ਠਾਵਨ।","roman":"Pheri chitaar kahiyo hamre sangi khel kariyo hari jee ih thaavan |","meaning_en":"","page":412},{"gurmukhi":"ਗ੍ਵਾਰਿਨ ਸ੍ਯਾਮ ਕੀ ਭੂਲ ਗਈ ਸੁਧਿ ਬੀਚ ਲਗੀ ਮਨ ਕੇ ਦੁਖ ਪਾਵਨ।੪੯੬।","roman":"Gvaarin syaam kee bhool gaee sudhi beech lagee man ke dukh paavan | 496 |","meaning_en":"","page":412}]},{"type":"verse","number":[497],"number_text":"੪੯੭।","page":412,"lines":[{"gurmukhi":"ਅਤਿ ਹੋਇ ਗਈ ਤਨ ਮੈ ਹਰਿ ਸਾਥ ਸੁ ਗੋਪਿਨ ਕੀ ਸਭ ਹੀ ਘਰਨੀ।","roman":"Ati hoi gaee tan mai hari saath su gopin kee sabh hee gharnee |","meaning_en":"","page":412},{"gurmukhi":"ਤਿਹ ਰੂਪ ਨਿਹਾਰ ਕੈ ਬਸਿ ਭਈ ਜੁ ਹੁਤੀ ਅਤਿ ਰੂਪਨ ਕੀ ਧਰਨੀ।","roman":"Tih roop nihaar kai basi bhaee ju hutee ati roopan kee dharnee |","meaning_en":"","page":412},{"gurmukhi":"ਇਹ ਭਾਤਿ ਪਰੀ ਮੁਰਝਾਇ ਧਰੀ ਕਬਿ ਨੇ ਉਪਮਾ ਤਿਹ ਕੀ ਬਰਨੀ।","roman":"Ih bhaati paree murjhaai dharee kabi ne upmaa tih kee barnee |","meaning_en":"","page":412},{"gurmukhi":"ਜਿਮ ਘੰਟਕ ਹੇਰ ਮੈ ਭੂਮਿ ਕੇ ਬੀਚ ਪਰੈ ਗਿਰ ਬਾਨ ਲਗੇ ਹਰਨੀ। ੪੯੭।","roman":"Jim ghantak her mai bhoomi ke beech parai gir baan lage harnee | 497 |","meaning_en":"","page":412}]},{"type":"verse","number":[498],"number_text":"੪੯੮।","page":412,"lines":[{"gurmukhi":"ਬਰੁਨੀ ਸਰ ਭਉਹਨ ਕੋ ਧਨੁ ਕੈ ਸੁ ਸਿੰਗਾਰ ਕੇ ਸਾਜਨ ਸਾਥ ਕਰੀ।","roman":"Barunee sar bhauhan ko dhanu kai su singaar ke saajan saath karee |","meaning_en":"","page":412},{"gurmukhi":"ਰਸ ਕੋ ਮਨ ਮੈ ਅਤਿ ਹੀ ਕਰਿ ਕੋਪ ਸੁ ਕਾਨ੍ਹ ਕੇ ਸਾਮੁਹਿ ਜਾਇ ਅਰੀ।","roman":"Ras ko man mai ati hee kari kop su kaanh ke saamuhi jaai aree |","meaning_en":"","page":412},{"gurmukhi":"ਅਤਿ ਹੀ ਕਰਿ ਨੇਹੁ ਕੋ ਕ੍ਰੋਧੁ ਮਨੈ ਤਿਹ ਠਉਰ ਤੇ ਪੈਗ ਨ ਏਕ ਟਰੀ।","roman":"Ati hee kari nehu ko krodhu manai tih thaur te paig na ek taree |","meaning_en":"","page":412},{"gurmukhi":"ਮਨੋ ਮੈਨ ਹੀ ਸੋ ਅਤਿ ਹੀ ਰਨ ਕੈ ਧਰਨੀ ਪਰ ਗ੍ਵਾਰਿਨ ਜੂਝਿ ਪਰੀ। ੪੯੮।","roman":"Mano main hee so ati hee ran kai dharnee par gvaarin joojhi paree | 498 |","meaning_en":"","page":412}]},{"type":"verse","number":[499],"number_text":"੪੯੯।","page":412,"lines":[{"gurmukhi":"ਤਿਨ ਗ੍ਵਾਰਿਨ ਕੋ ਅਤਿ ਹੀ ਪਿਖਿ ਪ੍ਰੇਮ ਤਬੈ ਪ੍ਰਗਟੇ ਭਗਵਾਨ ਸਿਤਾਬੀ।","roman":"Tin gvaarin ko ati hee pikhi prem tabai pragte bhagvaan sitaabee |","meaning_en":"","page":412},{"gurmukhi":"ਜੋਤਿ ਭਈ ਧਰਨੀ ਪਰ ਇਉ ਰਜਨੀ ਮਹਿ ਛੂਟਤ ਜਿਉ ਮਹਤਾਬੀ।","roman":"Joti bhaee dharnee par iu rajnee mahi chhootat jiu mahtaabee |","meaning_en":"","page":412},{"gurmukhi":"ਚਉਕ ਪਰੀ ਤਬ ਹੀ ਇਹ ਇਉ ਜੈਸੇ ਚਉਕ ਪਰੈ ਤਮ ਮੈ ਡਰਿ ਖੁਆਬੀ।","roman":"Chauk paree tab hee ih iu jaise chauk parai tam mai dari khuaabee |","meaning_en":"","page":412},{"gurmukhi":"ਛਾਡਿ ਚਲਿਯੋ ਤਨ ਕੋ ਮਨ ਇਉ ਜਿਮ ਭਾਜਤ ਹੈ ਗ੍ਰਿਹ ਛਾਡਿ ਸਰਾਬੀ।੪੯੯।","roman":"Chhaadi chaliyo tan ko man iu jim bhaajat hai grih chhaadi saraabee | 499 |","meaning_en":"","page":412}]},{"type":"verse","number":[500],"number_text":"੫੦੦।","page":413,"lines":[{"gurmukhi":"ਗ੍ਵਾਰਿਨ ਧਾਇ ਚਲੀ ਮਿਲਬੇ ਕਹੁ ਜੋ ਪਿਖਏ ਭਗਵਾਨ ਗੁਮਾਨੀ।","roman":"Gvaarin dhaai chalee milbe kahu jo pikhae bhagvaan gumaanee |","meaning_en":"","page":413},{"gurmukhi":"ਜਿਉ ਮ੍ਰਿਗਨੀ ਮ੍ਰਿਗ ਦੇਖਿ ਚਲੈ ਜੁ ਹੁਤੀ ਅਤਿ ਰੂਪ ਬਿਖੈ ਅਭਿਮਾਨੀ।","roman":"Jiu mrignee mrig dekhi chalai ju hutee ati roop bikhai abhimaanee |","meaning_en":"","page":413},{"gurmukhi":"ਤਾ ਛਬਿ ਕੀ ਅਤਿ ਹੀ ਉਪਮਾ ਕਬਿ ਨੈ ਮੁਖ ਤੇ ਇਹ ਭਾਤਿ ਬਖਾਨੀ।","roman":"Taa chhabi kee ati hee upmaa kabi nai mukh te ih bhaati bakhaanee |","meaning_en":"","page":413},{"gurmukhi":"ਜਿਉ ਜਲ ਚਾਤ੍ਰਿਕ ਬੂੰਦ ਪਰੈ ਜਿਮ ਕੂਦਿ ਪਰੈ ਮਛਲੀ ਪਿਖਿ ਪਾਨੀ। ੫੦੦।","roman":"Jiu jal chaatrik boond parai jim koodi parai machhlee pikhi paanee | 500 |","meaning_en":"","page":413}]},{"type":"verse","number":[501],"number_text":"੫੦੧।","page":413,"lines":[{"gurmukhi":"ਰਾਜਤ ਹੈ ਪੀਅਰੋ ਪਟ ਕੰਧਿ ਬਿਰਾਜਤ ਹੈ ਮ੍ਰਿਗ ਸੇ ਦ੍ਰਿਗ ਦੋਊ।","roman":"Raajat hai peearo pat kandhi biraajat hai mrig se drig do'oo |","meaning_en":"","page":413},{"gurmukhi":"ਛਾਜਤ ਹੈ ਮਨਿ ਸੋ ਉਰ ਮੈ ਨਦੀਆ ਪਤਿ ਸਾਥ ਲੀਏ ਫੁਨਿ ਜੋਊ।","roman":"Chhaajat hai mani so ur mai nadeeaa pati saath lee'e phuni jo'oo |","meaning_en":"","page":413},{"gurmukhi":"ਕਾਨ੍ਹ ਫਿਰੈ ਤਿਨ ਗੋਪਿਨ ਮੈ ਜਿਹ ਕੀ ਜਗ ਮੈ ਸਮ ਤੁਲਿ ਨ ਕੋਊ।","roman":"Kaanh phirai tin gopin mai jih kee jag mai sam tuli na ko'oo |","meaning_en":"","page":413},{"gurmukhi":"ਗ੍ਵਾਰਿਨ ਰੀਝ ਰਹੀ ਬ੍ਰਿਜ ਕੀ ਸੋਊ ਰੀਝਤ ਹੈ ਚਕ ਦੇਖਤ ਸੋਊ। ੫੦੧।","roman":"Gvaarin reejh rahee brij kee so'oo reejhat hai chak dekhat so'oo | 501 |","meaning_en":"","page":413}]},{"type":"heading","kind":"chhand","name":"ਕਬਿਤੁ","gurmukhi":"ਕਬਿਤੁ","roman":"Kabitu","meaning_en":"","page":413},{"type":"verse","number":[502],"number_text":"੫੦੨।","page":413,"lines":[{"gurmukhi":"ਕਉਨ ਜਿਉ ਪ੍ਰਭਾਤ ਤੈ ਬਿਛਰਿਯੋ ਮਿਲੀ ਬਾਤ ਤੈ","roman":"Kaun jiu prabhaat tai bichhriyo milee baat tai","meaning_en":"","page":413},{"gurmukhi":"ਗੁਨੀ ਜਿਉ ਸੁਰ ਸਾਤ ਤੈ ਬਚਾਯੋ ਚੋਰ ਗਾਤ ਤੈ।","roman":"Gunee jiu sur saat tai bachaayo chor gaat tai |","meaning_en":"","page":413},{"gurmukhi":"ਜੈਸੇ ਧਨੀ ਧਨ ਤੈ ਅਉ ਰਿਨੀ ਲੋਕ ਮਨਿ ਤੈ","roman":"Jaise dhanee dhan tai au rinee lok mani tai","meaning_en":"","page":413},{"gurmukhi":"ਲਰਈਯਾ ਜੈਸੇ ਰਨ ਤੈ ਤਜਈਯਾ ਜਿਉ ਨਸਾਤ ਤੈ।","roman":"Laraeeyaa jaise ran tai tajaeeyaa jiu nasaat tai |","meaning_en":"","page":413},{"gurmukhi":"ਜੈਸੇ ਦੁਖੀ ਸੂਖ ਤੈ ਅਭੂਖੀ ਜੈਸੇ ਭੂਖ ਤੈ","roman":"Jaise dukhee sookh tai abhookhee jaise bhookh tai","meaning_en":"","page":413},{"gurmukhi":"ਸੁ ਰਾਜਾ ਸਤ੍ਰ ਆਪਨੇ ਕੋ ਸੁਨੇ ਜੈਸੇ ਘਾਤ ਤੈ।","roman":"Su raajaa satr aapne ko sune jaise ghaat tai |","meaning_en":"","page":413},{"gurmukhi":"ਹੋਤ ਹੈ ਪ੍ਰਸੰਨ ਜੇਤੇ ਏਤੇ ਏਤੀ ਬਾਤਨ ਤੈ","roman":"Hot hai prasann jete ete etee baatan tai","meaning_en":"","page":413},{"gurmukhi":"ਹੋਤ ਹੈ ਪ੍ਰਸੰਨ੍ਯ ਗੋਪੀ ਤੈਸੇ ਕਾਨ੍ਹ ਬਾਤ ਤੈ। ੫੦੨।","roman":"Hot hai prasanny gopee taise kaanh baat tai | 502 |","meaning_en":"","page":413}]},{"type":"heading","kind":"speaker","name":"ਕਾਨ੍ਹ ਜੂ ਬਾਚ","gurmukhi":"ਕਾਨ੍ਹ ਜੂ ਬਾਚ","roman":"Kaanh joo baach","meaning_en":"","page":413},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":413},{"type":"verse","number":[503],"number_text":"੫੦੩।","page":413,"lines":[{"gurmukhi":"ਹਸਿ ਬਾਤ ਕਹੀ ਸੰਗਿ ਗੋਪਿਨ ਕਾਨ ਚਲੋ ਜਮੁਨਾ ਤਟਿ ਖੇਲ ਕਰੈ।","roman":"Hasi baat kahee sangi gopin kaan chalo jamunaa tati khel karai |","meaning_en":"","page":413},{"gurmukhi":"ਚਿਟਕਾਰਨ ਸੋ ਭਿਰ ਕੈ ਤਿਹ ਜਾ ਤੁਮਹੂੰ ਹੂੰ ਤਰੋ ਹਮਹੂੰ ਹੂੰ ਤਰੈ।","roman":"Chitkaaran so bhir kai tih jaa tumhoon hoon taro hamhoon hoon tarai |","meaning_en":"","page":413},{"gurmukhi":"ਗੁਹਿ ਕੈ ਬਨ ਫੂਲਨ ਸੁੰਦਰ ਹਾਰ ਸੋ ਕੇਲ ਕਰੈ ਤਿਨ ਡਾਰਿ ਗਰੈ।","roman":"Guhi kai ban phoolan sundar haar so kel karai tin daari garai |","meaning_en":"","page":413},{"gurmukhi":"ਬਿਰਹਾ ਛੁਧ ਕੋ ਤਿਹ ਠਉਰ ਬਿਖੈ ਹਸ ਕੈ ਰਸ ਕੈ ਸੰਗਿ ਪੇਟ ਭਰੈ। ੫੦੩।","roman":"Birhaa chhudh ko tih thaur bikhai has kai ras kai sangi pet bharai | 503 |","meaning_en":"","page":413}]},{"type":"verse","number":[504],"number_text":"੫੦੪।","page":413,"lines":[{"gurmukhi":"ਆਇਸੁ ਮਾਨਿ ਤਬੈ ਹਰਿ ਕੋ ਸਭ ਧਾਇ ਚਲੀ ਗੁਪੀਆ ਤਿਹ ਠਉਰੈ।","roman":"Aaisu maani tabai hari ko sabh dhaai chalee gupeeaa tih thaurai |","meaning_en":"","page":413},{"gurmukhi":"ਏਕ ਚਲੈ ਮੁਸਕਾਇ ਭਲੀ ਬਿਧਿ ਏਕ ਚਲੈ ਹਰੂਏ ਇਕ ਦਉਰੈ।","roman":"Ek chalai muskaai bhalee bidhi ek chalai harooe ik daurai |","meaning_en":"","page":413},{"gurmukhi":"ਸ੍ਯਾਮ ਕਹੈ ਉਪਮਾ ਤਿਹ ਕੀ ਜਲ ਮੈ ਜਮੁਨਾ ਕਹੁ ਗ੍ਵਾਰਿਨ ਹਉਰੈ।","roman":"Syaam kahai upmaa tih kee jal mai jamunaa kahu gvaarin haurai |","meaning_en":"","page":413},{"gurmukhi":"ਰੀਝ ਰਹੈ ਬਨ ਕੇ ਮ੍ਰਿਗ ਦੇਖਿ ਸੁ ਅਉਰ ਪਿਖੈ ਗਜ ਗਾਮਨ ਸਉਰੈ। ੫੦੪।","roman":"Reejh rahai ban ke mrig dekhi su aur pikhai gaj gaaman saurai | 504 |","meaning_en":"","page":413}]},{"type":"verse","number":[505],"number_text":"੫੦੫।","page":414,"lines":[{"gurmukhi":"ਸ੍ਯਾਮ ਸਮੇਤ ਸਭੈ ਗੁਪੀਆ ਜਮੁਨਾ ਜਲ ਕੋ ਤਰਿ ਪਾਰਿ ਪਰਈਯਾ।","roman":"Syaam samet sabhai gupeeaa jamunaa jal ko tari paari paraeeyaa |","meaning_en":"","page":414},{"gurmukhi":"ਪਾਰ ਭਈ ਜਬ ਹੀ ਹਿਤ ਸੋ ਗਿਰਦਾ ਕਰ ਕੈ ਤਿਹ ਕੋ ਤਿਸਟਈਯਾ।","roman":"Paar bhaee jab hee hit so girdaa kar kai tih ko tistaeeyaa |","meaning_en":"","page":414},{"gurmukhi":"ਤਾ ਛਬਿ ਕੀ ਅਤਿ ਹੀ ਉਪਮਾ ਕਬਿ ਨੈ ਮੁਖ ਤੇ ਇਹ ਭਾਤਿ ਸੁਨਈਯਾ।","roman":"Taa chhabi kee ati hee upmaa kabi nai mukh te ih bhaati sunaeeyaa |","meaning_en":"","page":414},{"gurmukhi":"ਕਾਨ੍ਹ ਭਯੋ ਸਸਿ ਸੁਧ ਮਨੋ ਸਮ ਰਾਜਤ ਗ੍ਵਾਰਿਨ ਤੀਰ ਤਰਈਯਾ। ੫੦੫।","roman":"Kaanh bhayo sasi sudh mano sam raajat gvaarin teer taraeeyaa | 505 |","meaning_en":"","page":414}]},{"type":"verse","number":[506],"number_text":"੫੦੬।","page":414,"lines":[{"gurmukhi":"ਬਾਤ ਲਗੀ ਕਹਨੇ ਮੁਖ ਤੇ ਕਵਿ ਸ੍ਯਾਮ ਕਹੈ ਮਿਲ ਕੈ ਸਭ ਗ੍ਵਾਰਿਨ।","roman":"Baat lagee kahne mukh te kavi syaam kahai mil kai sabh gvaarin |","meaning_en":"","page":414},{"gurmukhi":"ਚੰਦ੍ਰਮੁਖੀ ਮ੍ਰਿਗ ਸੇ ਦ੍ਰਿਗਨੀ ਲਖੀਯੈ ਤਿਨ ਭਾਨ ਅਨੰਤ ਅਪਾਰਨਿ।","roman":"Chandramukhee mrig se drignee lakheeyai tin bhaan anant apaarni |","meaning_en":"","page":414},{"gurmukhi":"ਕਾਨ੍ਹ ਕੇ ਸਾਥ ਕਰੀ ਚਰਚਾ ਮਿਲਿ ਕੈ ਬ੍ਰਿਜ ਕੀ ਸਭ ਸੁੰਦਰ ਬਾਰਨਿ।","roman":"Kaanh ke saath karee charchaa mili kai brij kee sabh sundar baarni |","meaning_en":"","page":414},{"gurmukhi":"ਛੋਰਿ ਦਈ ਗ੍ਰਿਹ ਕੀ ਸਭ ਲਾਜ ਜੁ ਹੋਇ ਮਹਾ ਰਸ ਕੀ ਚਸਕਾਰਨਿ। ੫੦੬।","roman":"Chhori daee grih kee sabh laaj ju hoi mahaa ras kee chaskaarni | 506 |","meaning_en":"","page":414}]},{"type":"verse","number":[507],"number_text":"੫੦੭।","page":414,"lines":[{"gurmukhi":"ਕੈ ਰਸ ਕੇ ਹਰਿ ਕਾਰਨੁ ਕੈ ਕਰਿ ਕਸਟ ਬਡੋ ਕੋਊ ਮੰਤਰ ਸਾਧੋ।","roman":"Kai ras ke hari kaarnu kai kari kasat bado ko'oo mantar saadho |","meaning_en":"","page":414},{"gurmukhi":"ਕੈ ਕੋਊ ਜੰਤ੍ਰ ਬਡੋਈ ਸਧਿਯੋ ਇਨ ਕੋ ਅਪਨੇ ਮਨ ਭੀਤਰ ਬਾਧੋ।","roman":"Kai ko'oo jantr badoee sadhiyo in ko apne man bheetar baadho |","meaning_en":"","page":414},{"gurmukhi":"ਕੈ ਕੇਹੂੰ ਤੰਤ੍ਰ ਕੇ ਸਾਥ ਕਿਧੋ ਕਬਿ ਸ੍ਯਾਮ ਕਹੈ ਅਤਿ ਹੀ ਕਰਿ ਧਾਧੋ।","roman":"Kai kehoon tantr ke saath kidho kabi syaam kahai ati hee kari dhaadho |","meaning_en":"","page":414},{"gurmukhi":"ਚੋਰਿ ਲਯੋ ਮਨੁ ਗ੍ਵਾਰਿਨ ਕੋ ਛਿਨ ਭੀਤਰ ਦੀਨ ਦਯਾਨਿਧਿ ਮਾਧੋ। ੫੦੭।","roman":"Chori layo manu gvaarin ko chhin bheetar deen dayaanidhi maadho | 507 |","meaning_en":"","page":414}]},{"type":"heading","kind":"speaker","name":"ਗੋਪੀ ਵਾਚ","gurmukhi":"ਗੋਪੀ ਵਾਚ","roman":"Gopee vaach","meaning_en":"","page":414},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":414},{"type":"verse","number":[508],"number_text":"੫੦੮।","page":414,"lines":[{"gurmukhi":"ਕਾਨ੍ਹ ਕੇ ਗ੍ਵਾਰਿਨ ਸਾਥ ਕਹਿਯੋ ਹਮ ਕੋ ਤਜਿ ਕੈ ਕਿਹ ਓਰਿ ਗਏ ਥੇ।","roman":"Kaanh ke gvaarin saath kahiyo ham ko taji kai kih ori gae the |","meaning_en":"","page":414},{"gurmukhi":"ਪ੍ਰੀਤਿ ਬਢਾਇ ਮਹਾ ਹਮ ਸੋ ਜਮੁਨਾ ਤਟਿ ਪੈ ਰਸ ਕੇਲ ਕਏ ਥੇ।","roman":"Preeti badhaai mahaa ham so jamunaa tati pai ras kel kae the |","meaning_en":"","page":414},{"gurmukhi":"ਯੌ ਤਜਿ ਗੇ ਜਿਮ ਰਾਹਿ ਮੁਸਾਫਿਰ ਸ੍ਯਾਮ ਕਹਿਯੋ ਤੁਮ ਨਾਹਿ ਨਏ ਥੇ।","roman":"Yau taji ge jim raahi musaaphir syaam kahiyo tum naahi nae the |","meaning_en":"","page":414},{"gurmukhi":"ਫੂਲ ਖਿਰੇ ਮੁਖ ਆਏ ਕਹਾ ਅਪਨੀ ਬਿਰੀਆ ਕਹੂੰ ਭਉਰ ਭਏ ਥੇ। ੫੦੮।","roman":"Phool khire mukh aae kahaa apnee bireeaa kahoon bhaur bhae the | 508 |","meaning_en":"","page":414}]},{"type":"heading","kind":"section_heading","name":"ਅਥ ਚਤੁਰ ਪੁਰਖ ਭੇਦ ਕਥਨੰ","gurmukhi":"ਅਥ ਚਤੁਰ ਪੁਰਖ ਭੇਦ ਕਥਨੰ","roman":"Ath chatur purakh bhed kathnan","meaning_en":"","page":414},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":414},{"type":"verse","number":[509],"number_text":"੫੦੯।","page":414,"lines":[{"gurmukhi":"ਨਰ ਏਕ ਅਕੀਨ ਹੀ ਪ੍ਰੀਤ ਕਰੈ ਇਕ ਕੀਨ ਕਰੈ ਇਕ ਕੀਨ ਜੁ ਜਾਨੈ।","roman":"Nar ek akeen hee preet karai ik keen karai ik keen ju jaanai |","meaning_en":"","page":414},{"gurmukhi":"ਏਕ ਨ ਪ੍ਰੀਤਿ ਕੇ ਭੇਦ ਜਨੈ ਜੋਊ ਪ੍ਰੀਤਿ ਕਰੈ ਅਰਿ ਕੈ ਤਿਹ ਮਾਨੈ।","roman":"Ek na preeti ke bhed janai jo'oo preeti karai ari kai tih maanai |","meaning_en":"","page":414},{"gurmukhi":"ਸੋ ਨਰ ਮੂੜ ਬਿਖੈ ਕਹੀਯੈ ਜਗਿ ਜੋ ਨਰ ਰੰਚ ਨ ਪ੍ਰੀਤਿ ਪਛਾਨੈ।","roman":"So nar moor bikhai kaheeyai jagi jo nar ranch na preeti pachhaanai |","meaning_en":"","page":414},{"gurmukhi":"ਸੋ ਚਰਚਾ ਰਸ ਕੀ ਇਹ ਭਾਤਿ ਸੁ ਗ੍ਵਾਰਿਨੀਆ ਸੰਗਿ ਕਾਨ੍ਹ ਬਖਾਨੈ। ੫੦੯।","roman":"So charchaa ras kee ih bhaati su gvaarineeaa sangi kaanh bakhaanai | 509 |","meaning_en":"","page":414}]},{"type":"heading","kind":"speaker","name":"ਗੋਪੀ ਬਾਚ","gurmukhi":"ਗੋਪੀ ਬਾਚ","roman":"Gopee baach","meaning_en":"","page":415},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":415},{"type":"verse","number":[510],"number_text":"੫੧੦।","page":415,"lines":[{"gurmukhi":"ਗ੍ਵਾਰਿਨੀਆ ਇਹ ਭਾਤਿ ਕਹੈ ਕਰਿ ਨੇਹ ਕੋ ਅੰਤਿ ਦਗਾ ਕੋਊ ਦੈ ਹੈ।","roman":"Gvaarineeaa ih bhaati kahai kari neh ko anti dagaa ko'oo dai hai |","meaning_en":"","page":415},{"gurmukhi":"ਦੋ ਜਨ ਛਾਡਿ ਪਰੋ ਹਰਿ ਗਯੋ ਜਨ ਜੋ ਛਲ ਸੋ ਤਿਹ ਕੋ ਹਰਿ ਲੈ ਹੈ।","roman":"Do jan chhaadi paro hari gayo jan jo chhal so tih ko hari lai hai |","meaning_en":"","page":415},{"gurmukhi":"ਜੋ ਬਟਹਾ ਜਨ ਘਾਵਤ ਹੈ ਕੋਊ ਜਾਤ ਚਲਿਯੋ ਪਿਖ ਕੈ ਮਧਿਮੈ ਹੈ।","roman":"Jo bathaa jan ghaavat hai ko'oo jaat chaliyo pikh kai madhimai hai |","meaning_en":"","page":415},{"gurmukhi":"ਪੈ ਖਿਝ ਕੈ ਅਤਿ ਹੀ ਗੁਪੀਆ ਇਹ ਭਾਤਿ ਕਹਿਯੋ ਤਿਨ ਕੀ ਸਮ ਏ ਹੈ। ੫੧੦।","roman":"Pai khijh kai ati hee gupeeaa ih bhaati kahiyo tin kee sam e hai | 510 |","meaning_en":"","page":415}]},{"type":"verse","number":[511],"number_text":"੫੧੧।","page":415,"lines":[{"gurmukhi":"ਜਬ ਹੀ ਇਹ ਗ੍ਵਾਰਿਨ ਬਾਤ ਕਹੀ ਤਬ ਹੀ ਤਿਨ ਕੇ ਸੰਗ ਕਾਨ੍ਹ ਹਸੈ।","roman":"Jab hee ih gvaarin baat kahee tab hee tin ke sang kaanh hasai |","meaning_en":"","page":415},{"gurmukhi":"ਜਿਹ ਨਾਮ ਕੇ ਲੇਤ ਜਰਾ ਮੁਖ ਤੇ ਤਜ ਕੈ ਗਨਕਾ ਸਭ ਪਾਪ ਨਸੇ।","roman":"Jih naam ke let jaraa mukh te taj kai gankaa sabh paap nase |","meaning_en":"","page":415},{"gurmukhi":"ਨ ਜਪਿਯੋ ਜਿਹ ਜਾਪ ਸੋਊ ਉਜਰੇ ਜਿਹ ਜਾਪ ਜਪਿਯੋ ਸੋਊ ਧਾਮ ਬਸੇ।","roman":"Na japiyo jih jaap so'oo ujre jih jaap japiyo so'oo dhaam base |","meaning_en":"","page":415},{"gurmukhi":"ਤਿਨ ਗੋਪਿਨ ਸੋ ਇਹ ਭਾਤਿ ਕਹਿਯੋ ਹਮਹੂੰ ਅਤਿ ਹੀ ਰਸ ਬੀਚ ਫਸੇ। ੫੧੧।","roman":"Tin gopin so ih bhaati kahiyo hamhoon ati hee ras beech phase | 511 |","meaning_en":"","page":415}]},{"type":"verse","number":[512],"number_text":"੫੧੨।","page":415,"lines":[{"gurmukhi":"ਕਹਿ ਕੈ ਇਹ ਬਾਤ ਹਸੇ ਹਰਿ ਜੂ ਉਠ ਕੈ ਜਮੁਨਾ ਜਲ ਬੀਚ ਤਰੇ।","roman":"Kahi kai ih baat hase hari joo uth kai jamunaa jal beech tare |","meaning_en":"","page":415},{"gurmukhi":"ਛਿਨ ਏਕ ਲਗਿਯੋ ਨ ਤਬੈ ਤਿਹ ਕੋ ਲਖਿ ਕੈ ਜਮੁਨਾ ਕਹ ਪਾਰ ਪਰੇ।","roman":"Chhin ek lagiyo na tabai tih ko lakhi kai jamunaa kah paar pare |","meaning_en":"","page":415},{"gurmukhi":"ਲਖਿ ਕੈ ਜਲ ਕੋ ਸੰਗ ਗੋਪਿਨ ਕੇ ਭਗਵਾਨ ਮਹਾ ਉਪਹਾਸ ਕਰੇ।","roman":"Lakhi kai jal ko sang gopin ke bhagvaan mahaa uphaas kare |","meaning_en":"","page":415},{"gurmukhi":"ਬਹੁ ਹੋਰਨਿ ਤੈ ਅਰੁ ਬ੍ਯਾਹਨਿ ਤੈ ਕੁਰਮਾਤਨ ਤੈ ਅਤਿ ਸੋਊ ਖਰੇ। ੫੧੨।","roman":"Bahu horni tai aru byaahni tai kurmaatan tai ati so'oo khare | 512 |","meaning_en":"","page":415}]},{"type":"heading","kind":"speaker","name":"ਕਾਨ੍ਹ ਬਾਚ","gurmukhi":"ਕਾਨ੍ਹ ਬਾਚ","roman":"Kaanh baach","meaning_en":"","page":415},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":415},{"type":"verse","number":[513],"number_text":"੫੧੩।","page":415,"lines":[{"gurmukhi":"ਰਜਨੀ ਪਰ ਗੀ ਤਬ ਹੀ ਭਗਵਾਨ ਕਹਿਯੋ ਹਸਿ ਕੈ ਹਮ ਰਾਸ ਕਰੈ।","roman":"Rajnee par gee tab hee bhagvaan kahiyo hasi kai ham raas karai |","meaning_en":"","page":415},{"gurmukhi":"ਸਸਿ ਰਾਜਤ ਹੈ ਸਿਤ ਗੋਪਿਨ ਕੇ ਮੁਖ ਸੁੰਦਰ ਸੇਤ ਹੀ ਹਾਰ ਡਰੈ।","roman":"Sasi raajat hai sit gopin ke mukh sundar set hee haar darai |","meaning_en":"","page":415},{"gurmukhi":"ਹਿਤ ਸੋ ਬ੍ਰਿਜ ਭੂਮਿ ਬਿਖੈ ਸਭ ਹੀ ਰਸ ਖੇਲ ਕਰੈ ਕਰ ਡਾਰ ਗਰੈ।","roman":"Hit so brij bhoomi bikhai sabh hee ras khel karai kar daar garai |","meaning_en":"","page":415},{"gurmukhi":"ਤੁਮ ਕੋ ਜੋਊ ਸੋਕ ਬਢਿਯੋ ਬਿਛੁਰੇ ਹਮ ਸੋ ਮਿਲਿ ਕੈ ਅਬ ਸੋਕ ਹਰੈ। ੫੧੩।","roman":"Tum ko jo'oo sok badhiyo bichhure ham so mili kai ab sok harai | 513 |","meaning_en":"","page":415}]},{"type":"verse","number":[514],"number_text":"੫੧੪।","page":415,"lines":[{"gurmukhi":"ਐਹੋ ਤ੍ਰੀਯਾ ਕਹਿ ਸ੍ਰੀ ਜਦੁਬੀਰ ਸਭੈ ਤੁਮ ਰਾਸ ਕੋ ਖੇਲ ਕਰੋ।","roman":"Aiho treeyaa kahi sree jadubeer sabhai tum raas ko khel karo |","meaning_en":"","page":415},{"gurmukhi":"ਗਹਿ ਕੈ ਕਰ ਸੋ ਕਰੁ ਮੰਡਲ ਕੈ ਨ ਕਛੂ ਮਨ ਭੀਤਰ ਲਾਜ ਧਰੋ।","roman":"Gahi kai kar so karu mandal kai na kachhoo man bheetar laaj dharo |","meaning_en":"","page":415},{"gurmukhi":"ਹਮਹੂੰ ਤੁਮਰੇ ਸੰਗ ਰਾਸ ਕਰੈ ਨਚਿ ਹੈ ਨਚਿਯੋ ਨਹ ਨੈਕੁ ਡਰੋ।","roman":"Hamhoon tumre sang raas karai nachi hai nachiyo nah naiku daro |","meaning_en":"","page":415},{"gurmukhi":"ਸਭ ਹੀ ਮਨ ਬੀਚ ਅਸੋਕ ਕਰੋ ਅਤਿ ਹੀ ਮਨ ਸੋਕਨ ਕੋ ਸੁ ਹਰੋ। ੫੧੪।","roman":"Sabh hee man beech asok karo ati hee man sokan ko su haro | 514 |","meaning_en":"","page":415}]},{"type":"verse","number":[515],"number_text":"੫੧੫।","page":415,"lines":[{"gurmukhi":"ਤਿਨ ਸੋ ਭਗਵਾਨ ਕਹੀ ਫਿਰ ਯੋ ਸਜਨੀ ਹਮਰੀ ਬਿਨਤੀ ਸੁਨਿ ਲੀਜੈ।","roman":"Tin so bhagvaan kahee phir yo sajnee hamree bintee suni leejai |","meaning_en":"","page":415},{"gurmukhi":"ਆਨੰਦ ਬੀਚ ਕਰੋ ਮਨ ਕੇ ਜਿਹ ਤੇ ਹਮਰੇ ਤਨ ਕੋ ਮਨ ਜੀਜੈ।","roman":"Aanand beech karo man ke jih te hamre tan ko man jeejai |","meaning_en":"","page":415},{"gurmukhi":"ਮਿਤਵਾ ਜਿਹ ਤੇ ਹਿਤ ਮਾਨਤ ਹੈ ਤਬ ਹੀ ਉਠ ਕੈ ਸੋਊ ਕਾਰਜ ਕੀਜੈ।","roman":"Mitvaa jih te hit maanat hai tab hee uth kai so'oo kaaraj keejai |","meaning_en":"","page":416},{"gurmukhi":"ਦੈ ਰਸ ਕੋ ਸਿਰਪਾਵ ਤਿਸੈ ਮਨ ਕੋ ਸਭ ਸੋਕ ਬਿਦਾ ਕਰਿ ਦੀਜੈ। ੫੧੫।","roman":"Dai ras ko sirpaav tisai man ko sabh sok bidaa kari deejai | 515 |","meaning_en":"","page":416}]},{"type":"verse","number":[516],"number_text":"੫੧੬।","page":416,"lines":[{"gurmukhi":"ਹਸਿ ਕੈ ਭਗਵਾਨ ਕਹੀ ਫਿਰਿ ਯੌ ਰਸ ਕੀ ਬਤੀਯਾ ਹਮ ਤੇ ਸੁਨ ਲਈਯੈ।","roman":"Hasi kai bhagvaan kahee phiri yau ras kee bateeyaa ham te sun laeeyai |","meaning_en":"","page":416},{"gurmukhi":"ਜਾ ਕੈ ਲੀਏ ਮਿਤਵਾ ਹਿਤ ਮਾਨਤ ਸੋ ਸੁਨ ਕੈ ਉਠਿ ਕਾਰਜ ਕਈਯੈ।","roman":"Jaa kai lee'e mitvaa hit maanat so sun kai uthi kaaraj kaeeyai |","meaning_en":"","page":416},{"gurmukhi":"ਗੋਪਿਨ ਸਾਥ ਕ੍ਰਿਪਾ ਕਰਿ ਕੈ ਕਬਿ ਸ੍ਯਾਮ ਕਹਿਯੋ ਮੁਸਲੀਧਰ ਭਈਯੈ।","roman":"Gopin saath kripaa kari kai kabi syaam kahiyo musleedhar bhaeeyai |","meaning_en":"","page":416},{"gurmukhi":"ਜਾ ਸੰਗ ਹੇਤ ਮਹਾ ਕਰੀਯੈ ਬਿਨੁ ਦਾਮਨ ਤਾ ਹੀ ਕੇ ਹਾਥਿ ਬਿਕਈਯੈ।੫੧੬।","roman":"Jaa sang het mahaa kareeyai binu daaman taa hee ke haathi bikaeeyai | 516 |","meaning_en":"","page":416}]},{"type":"verse","number":[517],"number_text":"੫੧੭।","page":416,"lines":[{"gurmukhi":"ਕਾਨਰ ਕੀ ਸੁਨ ਕੈ ਬਤੀਆ ਮਨ ਮੈ ਤਿਨ ਗ੍ਵਾਰਿਨ ਧੀਰ ਗਹਿਯੋ ਹੈ।","roman":"Kaanar kee sun kai bateeaa man mai tin gvaarin dheer gahiyo hai |","meaning_en":"","page":416},{"gurmukhi":"ਦੋਖ ਜਿਤੋ ਮਨ ਭੀਤਰ ਥੋ ਰਸ ਪਾਵਕ ਮੋ ਤ੍ਰਿਣ ਤੁਲਿ ਦਹਿਯੋ ਹੈ।","roman":"Dokh jito man bheetar tho ras paavak mo trin tuli dahiyo hai |","meaning_en":"","page":416},{"gurmukhi":"ਰਾਸ ਕਰਿਯੋ ਸਭ ਹੀ ਮਿਲਿ ਕੈ ਜਸੁਧਾ ਸੁਤ ਕੋ ਤਿਨ ਮਾਨਿ ਕਹਿਯੋ ਹੈ।","roman":"Raas kariyo sabh hee mili kai jasudhaa sut ko tin maani kahiyo hai |","meaning_en":"","page":416},{"gurmukhi":"ਰੀਝ ਰਹੀ ਪ੍ਰਿਥਮੀ ਪ੍ਰਿਥਮੀ ਗਨ ਅਉ ਨਭ ਮੰਡਲ ਰੀਝ ਰਹਿਯੋ ਹੈ। ੫੧੭।","roman":"Reejh rahee prithmee prithmee gan au nabh mandal reejh rahiyo hai | 517 |","meaning_en":"","page":416}]},{"type":"verse","number":[518],"number_text":"੫੧੮।","page":416,"lines":[{"gurmukhi":"ਗਾਵਤ ਏਕ ਬਜਾਵਤ ਤਾਲ ਸਭੈ ਬ੍ਰਿਜ ਨਾਰਿ ਮਹਾ ਹਿਤ ਸੋ।","roman":"Gaavat ek bajaavat taal sabhai brij naari mahaa hit so |","meaning_en":"","page":416},{"gurmukhi":"ਭਗਵਾਨ ਕੋ ਮਾਨਿ ਕਹਿਯੋ ਤਬ ਹੀ ਕਬਿ ਸ੍ਯਾਮ ਕਹੈ ਅਤਿ ਹੀ ਚਿਤ ਸੋ।","roman":"Bhagvaan ko maani kahiyo tab hee kabi syaam kahai ati hee chit so |","meaning_en":"","page":416},{"gurmukhi":"ਇਨ ਸੀਖ ਲਈ ਗਤਿ ਗਾਮਨ ਤੇ ਸੁਰ ਭਾਮਨ ਤੇ ਕਿ ਕਿਧੋ ਕਿਤ ਸੋ।","roman":"In seekh laee gati gaaman te sur bhaaman te ki kidho kit so |","meaning_en":"","page":416},{"gurmukhi":"ਅਬ ਮੋਹਿ ਇਹੈ ਸਮਝਿਯੋ ਸੁ ਪਰੈ ਜਿਹ ਕਾਨ੍ਹ ਸਿਖੇ ਇਨ ਹੂੰ ਤਿਤ ਸੋ। ੫੧੮।","roman":"Ab mohi ihai samjhiyo su parai jih kaanh sikhe in hoon tit so | 518 |","meaning_en":"","page":416}]},{"type":"verse","number":[519],"number_text":"੫੧੯।","page":416,"lines":[{"gurmukhi":"ਮੋਰ ਕੋ ਪੰਖ ਬਿਰਾਜਤ ਸੀਸ ਸੁ ਰਾਜਤ ਕੁੰਡਲ ਕਾਨਨ ਦੋਊ।","roman":"Mor ko pankh biraajat sees su raajat kundal kaanan do'oo |","meaning_en":"","page":416},{"gurmukhi":"ਲਾਲ ਕੀ ਮਾਲ ਸੁ ਛਾਜਤ ਕੰਠਹਿ ਤਾ ਉਪਮਾ ਸਮ ਹੈ ਨਹਿ ਕੋਊ।","roman":"Laal kee maal su chhaajat kanthhi taa upmaa sam hai nahi ko'oo |","meaning_en":"","page":416},{"gurmukhi":"ਜੋ ਰਿਪੁ ਪੈ ਮਗ ਜਾਤ ਚਲਿਯੋ ਸੁਨਿ ਕੈ ਉਪਮਾ ਚਲਿ ਦੇਖਤ ਓਊ।","roman":"Jo ripu pai mag jaat chaliyo suni kai upmaa chali dekhat o'oo |","meaning_en":"","page":416},{"gurmukhi":"ਅਉਰ ਕੀ ਬਾਤ ਕਹਾ ਕਹੀਯੈ ਕਬਿ ਸ੍ਯਾਮ ਸੁਰਾਦਿਕ ਰੀਝਤ ਸੋਊ।੫੧੯।","roman":"Aur kee baat kahaa kaheeyai kabi syaam suraadik reejhat so'oo | 519 |","meaning_en":"","page":416}]},{"type":"verse","number":[520],"number_text":"੫੨੦।","page":416,"lines":[{"gurmukhi":"ਗੋਪਿਨ ਸੰਗ ਤਹਾ ਭਗਵਾਨ ਮਨੈ ਅਤਿ ਹੀ ਹਿਤ ਕੋ ਕਰ ਗਾਵੈ।","roman":"Gopin sang tahaa bhagvaan manai ati hee hit ko kar gaavai |","meaning_en":"","page":416},{"gurmukhi":"ਰੀਝ ਰਹੈ ਖਗ ਠਉਰ ਸਮੇਤ ਸੁ ਯਾ ਬਿਧਿ ਗ੍ਵਾਰਿਨ ਕਾਨ੍ਹ ਰਿਝਾਵੈ।","roman":"Reejh rahai khag thaur samet su yaa bidhi gvaarin kaanh rijhaavai |","meaning_en":"","page":416},{"gurmukhi":"ਜਾ ਕਹੁ ਖੋਜਿ ਕਈ ਗਣ ਗੰਧ੍ਰਬ ਕਿੰਨਰ ਭੇਦ ਨ ਰੰਚਕ ਪਾਵੈ।","roman":"Jaa kahu khoji kaee gan gandhrab kinnar bhed na ranchak paavai |","meaning_en":"","page":416},{"gurmukhi":"ਗਾਵਤ ਸੋ ਹਰਿ ਜੂ ਤਿਹ ਜਾ ਤਜ ਕੈ ਮ੍ਰਿਗਨੀ ਚਲਿ ਕੈ ਮ੍ਰਿਗ ਆਵੈ। ੫੨੦।","roman":"Gaavat so hari joo tih jaa taj kai mrignee chali kai mrig aavai | 520 |","meaning_en":"","page":416}]},{"type":"verse","number":[521],"number_text":"੫੨੧।","page":416,"lines":[{"gurmukhi":"ਗਾਵਤ ਸਾਰੰਗ ਸੁਧ ਮਲਾਰ ਬਿਭਾਸ ਬਿਲਾਵਲ ਅਉ ਫੁਨਿ ਗਉਰੀ।","roman":"Gaavat saarang sudh malaar bibhaas bilaaval au phuni gauree |","meaning_en":"","page":416},{"gurmukhi":"ਜਾ ਸੁਰ ਸ੍ਰੋਨਨ ਮੈ ਸੁਨ ਕੈ ਸੁਰ ਭਾਮਿਨ ਧਾਵਤ ਡਾਰਿ ਪਿਛਉਰੀ।","roman":"Jaa sur sronan mai sun kai sur bhaamin dhaavat daari pichhauree |","meaning_en":"","page":416},{"gurmukhi":"ਸੋ ਸੁਨ ਕੈ ਸਭ ਗ੍ਵਾਰਨਿਯਾ ਰਸ ਕੈ ਸੰਗ ਹੋਇ ਗਈ ਜਨੁ ਬਉਰੀ।","roman":"So sun kai sabh gvaarniyaa ras kai sang hoi gaee janu bauree |","meaning_en":"","page":416},{"gurmukhi":"ਤਿਆਗ ਕੈ ਕਾਨਨ ਤਾ ਸੁਨ ਕੈ ਮ੍ਰਿਗ ਲੈ ਮ੍ਰਿਗਨੀ ਚਲਿ ਆਵਤ ਦਉਰੀ। ੫੨੧।","roman":"Tiaag kai kaanan taa sun kai mrig lai mrignee chali aavat dauree | 521 |","meaning_en":"","page":416}]},{"type":"verse","number":[522],"number_text":"੫੨੨।","page":417,"lines":[{"gurmukhi":"ਏਕ ਨਚੈ ਇਕ ਗਾਵਤ ਗੀਤ ਬਜਾਵਤ ਤਾਲ ਦਿਖਾਵਤ ਭਾਵਨ।","roman":"Ek nachai ik gaavat geet bajaavat taal dikhaavat bhaavan |","meaning_en":"","page":417},{"gurmukhi":"ਰਾਸ ਬਿਖੈ ਅਤਿ ਹੀ ਰਸ ਸੋ ਸੁ ਰਿਝਾਵਨ ਕਾਜ ਸਭੈ ਮਨ ਭਾਵਨਿ।","roman":"Raas bikhai ati hee ras so su rijhaavan kaaj sabhai man bhaavni |","meaning_en":"","page":417},{"gurmukhi":"ਚਾਦਨੀ ਸੁੰਦਰ ਰਾਤਿ ਬਿਖੈ ਕਬਿ ਸ੍ਯਾਮ ਕਹੈ ਸੁ ਬਿਖੈ ਰੁਤ ਸਾਵਨ।","roman":"Chaadnee sundar raati bikhai kabi syaam kahai su bikhai rut saavan |","meaning_en":"","page":417},{"gurmukhi":"ਗ੍ਵਾਰਨਿਯਾ ਤਜਿ ਕੈ ਪੁਰ ਕੋ ਮਿਲਿ ਖੇਲਿ ਕਰੈ ਰਸ ਨੀਕਨਿ ਠਾਵਨ। ੫੨੨।","roman":"Gvaarniyaa taji kai pur ko mili kheli karai ras neekni thaavan | 522 |","meaning_en":"","page":417}]},{"type":"verse","number":[523],"number_text":"੫੨੩।","page":417,"lines":[{"gurmukhi":"ਸੁੰਦਰ ਠਉਰ ਬਿਖੈ ਕਬਿ ਸ੍ਯਾਮ ਕਹੈ ਮਿਲਿ ਗ੍ਵਾਰਿਨ ਖੇਲ ਕਰਿਯੋ ਹੈ।","roman":"Sundar thaur bikhai kabi syaam kahai mili gvaarin khel kariyo hai |","meaning_en":"","page":417},{"gurmukhi":"ਮਾਨਹੁ ਆਪ ਹੀ ਤੇ ਬ੍ਰਹਮਾ ਸੁਰ ਮੰਡਲ ਸੁਧਿ ਬਨਾਇ ਧਰਿਯੋ ਹੈ।","roman":"Maanhu aap hee te brahmaa sur mandal sudhi banaai dhariyo hai |","meaning_en":"","page":417},{"gurmukhi":"ਜਾ ਪਿਖ ਕੇ ਖਗ ਰੀਝ ਰਹੈ ਮ੍ਰਿਗ ਤਿਆਗ ਤਿਸੈ ਨਹੀ ਚਾਰੋ ਚਰਿਯੋ ਹੈ।","roman":"Jaa pikh ke khag reejh rahai mrig tiaag tisai nahee chaaro chariyo hai |","meaning_en":"","page":417},{"gurmukhi":"ਅਉਰ ਕੀ ਬਾਤ ਕਹਾ ਕਹੀਯੇ ਜਿਹ ਕੇ ਪਿਖਏ ਭਗਵਾਨ ਛਰਿਯੋ ਹੈ। ੫੨੩।","roman":"Aur kee baat kahaa kaheeye jih ke pikhae bhagvaan chhariyo hai | 523 |","meaning_en":"","page":417}]},{"type":"verse","number":[524],"number_text":"੫੨੪।","page":417,"lines":[{"gurmukhi":"ਇਤ ਤੇ ਨੰਦਲਾਲ ਸਖਾ ਲੀਏ ਸੰਗਿ ਉਤੈ ਫੁਨਿ ਗ੍ਵਾਰਿਨ ਜੂਥ ਸਬੈ।","roman":"It te nandlaal sakhaa lee'e sangi utai phuni gvaarin jooth sabai |","meaning_en":"","page":417},{"gurmukhi":"ਬਹਸਾ ਬਹਸੀ ਤਹ ਹੋਨ ਲਗੀ ਰਸ ਬਾਤਨ ਸੋ ਕਬਿ ਸ੍ਯਾਮ ਤਬੈ।","roman":"Bahsaa bahsee tah hon lagee ras baatan so kabi syaam tabai |","meaning_en":"","page":417},{"gurmukhi":"ਜਿਹ ਕੋ ਬ੍ਰਹਮਾ ਨਹੀ ਅੰਤ ਲਖੈ ਨਹ ਨਾਰਦ ਪਾਵਤ ਜਾਹਿ ਛਬੈ।","roman":"Jih ko brahmaa nahee ant lakhai nah naarad paavat jaahi chhabai |","meaning_en":"","page":417},{"gurmukhi":"ਮ੍ਰਿਗ ਜਿਉ ਮ੍ਰਿਗਨੀ ਮਹਿ ਰਾਜਤ ਹੈ ਹਰਿ ਤਿਉ ਗਨ ਗ੍ਵਾਰਿਨ ਬੀਚ ਫਬੈ। ੫੨੪।","roman":"Mrig jiu mrignee mahi raajat hai hari tiu gan gvaarin beech phabai | 524 |","meaning_en":"","page":417}]},{"type":"verse","number":[525],"number_text":"੫੨੫।","page":417,"lines":[{"gurmukhi":"ਨੰਦ ਲਾਲ ਲਲਾ ਇਤ ਗਾਵਤ ਹੈ ਉਤ ਤੇ ਸਭ ਗ੍ਵਾਰਨਿਯਾ ਮਿਲਿ ਗਾਵੈ।","roman":"Nand laal lalaa it gaavat hai ut te sabh gvaarniyaa mili gaavai |","meaning_en":"","page":417},{"gurmukhi":"ਫਾਗੁਨ ਕੀ ਰੁਤਿ ਊਪਰਿ ਆਬਨ ਮਾਨਹੁ ਕੋਕਿਲਕਾ ਕੁਕਹਾਵੈ।","roman":"Phaagun kee ruti oopri aaban maanhu kokilkaa kukhaavai |","meaning_en":"","page":417},{"gurmukhi":"ਤੀਰ ਨਦੀ ਸੋਊ ਗਾਵਤ ਗੀਤ ਜੋਊ ਉਨ ਕੇ ਮਨ ਭੀਤਰ ਭਾਵੈ।","roman":"Teer nadee so'oo gaavat geet jo'oo un ke man bheetar bhaavai |","meaning_en":"","page":417},{"gurmukhi":"ਨੈਨ ਨਛਤ੍ਰ ਪਸਾਰਿ ਪਿਖੈ ਸੁਰ ਦੇਵ ਬਧੂ ਮਿਲਿ ਦੇਖਨਿ ਆਵੈ। ੫੨੫।","roman":"Nain nachhatr pasaari pikhai sur dev badhoo mili dekhni aavai | 525 |","meaning_en":"","page":417}]},{"type":"verse","number":[526],"number_text":"੫੨੬।","page":417,"lines":[{"gurmukhi":"ਮੰਡਲ ਰਾਸ ਬਚਿਤ੍ਰ ਮਹਾ ਸਮ ਜੇ ਹਰਿ ਕੀ ਭਗਵਾਨ ਰਚਿਯੋ ਹੈ।","roman":"Mandal raas bachitr mahaa sam je hari kee bhagvaan rachiyo hai |","meaning_en":"","page":417},{"gurmukhi":"ਤਾਹੀ ਕੇ ਬੀਚ ਕਹੈ ਕਬਿ ਇਉ ਰਸ ਕੰਚਨ ਕੀ ਸਮਤੁਲਿ ਮਚਿਯੋ ਹੈ।","roman":"Taahee ke beech kahai kabi iu ras kanchan kee samtuli machiyo hai |","meaning_en":"","page":417},{"gurmukhi":"ਤਾ ਸੀ ਬਨਾਇਬੇ ਕੋ ਬ੍ਰਹਮਾ ਨ ਬਨੀ ਕਰਿ ਕੈ ਜੁਗ ਕੋਟਿ ਪਚਿਯੋ ਹੈ।","roman":"Taa see banaaibe ko brahmaa na banee kari kai jug koti pachiyo hai |","meaning_en":"","page":417},{"gurmukhi":"ਕੰਚਨ ਕੇ ਤਨਿ ਗੋਪਨਿ ਕੋ ਤਿਹ ਮਧਿ ਮਨੀ ਮਨ ਤੁਲਿ ਗਚਿਯੋ ਹੈ। ੫੨੬।","roman":"Kanchan ke tani gopni ko tih madhi manee man tuli gachiyo hai | 526 |","meaning_en":"","page":417}]},{"type":"verse","number":[527],"number_text":"੫੨੭।","page":417,"lines":[{"gurmukhi":"ਜਲ ਮੈ ਸਫਰੀ ਜਿਮ ਕੇਲ ਕਰੈ ਤਿਮ ਗ੍ਵਾਰਨਿਯਾ ਹਰਿ ਕੇ ਸੰਗਿ ਡੋਲੈ।","roman":"Jal mai saphree jim kel karai tim gvaarniyaa hari ke sangi dolai |","meaning_en":"","page":417},{"gurmukhi":"ਜਿਉ ਜਨ ਫਾਗ ਕੋ ਖੇਲਤ ਹੈ ਤਿਹ ਭਾਤਿ ਹੀ ਕਾਨ੍ਹ ਕੇ ਸਾਥ ਕਲੋਲੈ।","roman":"Jiu jan phaag ko khelat hai tih bhaati hee kaanh ke saath kalolai |","meaning_en":"","page":417},{"gurmukhi":"ਕੋਕਿਲਕਾ ਜਿਮ ਬੋਲਤ ਹੈ ਤਿਮ ਗਾਵਤ ਤਾ ਕੀ ਬਰਾਬਰ ਬੋਲੈ।","roman":"Kokilkaa jim bolat hai tim gaavat taa kee baraabar bolai |","meaning_en":"","page":417},{"gurmukhi":"ਸ੍ਯਾਮ ਕਹੈ ਸਭ ਗ੍ਵਾਰਨਿਯਾ ਇਹ ਭਾਤਨ ਸੋ ਰਸ ਕਾਨ੍ਹਿ ਨਿਚੋਲੈ। ੫੨੭।","roman":"Syaam kahai sabh gvaarniyaa ih bhaatan so ras kaanhi nicholai | 527 |","meaning_en":"","page":417}]},{"type":"verse","number":[528],"number_text":"੫੨੮।","page":417,"lines":[{"gurmukhi":"ਰਸ ਕੀ ਚਰਚਾ ਤਿਨ ਸੋ ਭਗਵਾਨ ਕਰੀ ਹਿਤ ਸੋ ਨ ਕਛੂ ਕਮ ਕੈ।","roman":"Ras kee charchaa tin so bhagvaan karee hit so na kachhoo kam kai |","meaning_en":"","page":417},{"gurmukhi":"ਇਹ ਭਾਤਿ ਕਹਿਯੋ ਕਬਿ ਸ੍ਯਾਮ ਕਹੈ ਤੁਮਰੇ ਮਾਹਿ ਖੇਲ ਬਨਿਓ ਹਮ ਕੈ।","roman":"Ih bhaati kahiyo kabi syaam kahai tumre maahi khel banio ham kai |","meaning_en":"","page":417},{"gurmukhi":"ਕਹਿ ਕੈ ਇਹ ਬਾਤ ਦੀਯੋ ਹਸਿ ਕੈ ਸੁ ਪ੍ਰਭਾ ਸੁਭ ਦੰਤਨ ਯੌ ਦਮਕੈ।","roman":"Kahi kai ih baat deeyo hasi kai su prabhaa subh dantan yau damkai |","meaning_en":"","page":418},{"gurmukhi":"ਜਨੁ ਦਿਉਸ ਭਲੇ ਰੁਤਿ ਸਾਵਨ ਕੀ ਅਤਿ ਅਭ੍ਰਨ ਮੈ ਚਪਲਾ ਚਮਕੈ। ੫੨੮।","roman":"Janu dius bhale ruti saavan kee ati abhran mai chaplaa chamkai | 528 |","meaning_en":"","page":418}]},{"type":"verse","number":[529],"number_text":"੫੨੯।","page":418,"lines":[{"gurmukhi":"ਐਹੋ ਲਲਾ ਨੰਦ ਲਾਲ ਕਹੈ ਸਭ ਗ੍ਵਾਰਨਿਯਾ ਅਤਿ ਮੈਨ ਭਰੀ।","roman":"Aiho lalaa nand laal kahai sabh gvaarniyaa ati main bharee |","meaning_en":"","page":418},{"gurmukhi":"ਹਮਰੇ ਸੰਗ ਆਵਹੁ ਖੇਲ ਕਰੋ ਨ ਕਛੂ ਮਨ ਭੀਤਰ ਸੰਕ ਕਰੀ।","roman":"Hamre sang aavhu khel karo na kachhoo man bheetar sank karee |","meaning_en":"","page":418},{"gurmukhi":"ਨੈਨ ਨਚਾਇ ਕਛੂ ਮੁਸਕਾਇ ਕੈ ਭਉਹ ਦੁਊ ਕਰਿ ਟੇਢਿ ਧਰੀ।","roman":"Nain nachaai kachhoo muskaai kai bhauh duoo kari tedhi dharee |","meaning_en":"","page":418},{"gurmukhi":"ਮਨ ਯੌ ਉਪਜੀ ਉਪਮਾ ਰਸ ਕੀ ਮਨੋ ਕਾਨ੍ਹ ਕੇ ਕੰਠਹਿ ਫਾਸਿ ਡਰੀ। ੫੨੯।","roman":"Man yau upjee upmaa ras kee mano kaanh ke kanthhi phaasi daree | 529 |","meaning_en":"","page":418}]},{"type":"verse","number":[530],"number_text":"੫੩੦।","page":418,"lines":[{"gurmukhi":"ਖੇਲਤ ਗ੍ਵਾਰਿਨ ਮਧਿ ਸੋਊ ਕਬਿ ਸ੍ਯਾਮ ਕਹੈ ਹਰਿ ਜੂ ਛਬਿ ਵਾਰੋ।","roman":"Khelat gvaarin madhi so'oo kabi syaam kahai hari joo chhabi vaaro |","meaning_en":"","page":418},{"gurmukhi":"ਖੇਲਤ ਹੈ ਸੋਊ ਮੈਨ ਭਰੀ ਇਨ ਹੂੰ ਪਰ ਮਾਨਹੁ ਚੇਟਕ ਡਾਰੋ।","roman":"Khelat hai so'oo main bharee in hoon par maanhu chetak daaro |","meaning_en":"","page":418},{"gurmukhi":"ਤੀਰ ਨਦੀ ਬ੍ਰਿਜ ਭੂਮਿ ਬਿਖੈ ਅਤਿ ਹੋਤ ਹੈ ਸੁੰਦਰ ਭਾਤਿ ਅਖਾਰੋ।","roman":"Teer nadee brij bhoomi bikhai ati hot hai sundar bhaati akhaaro |","meaning_en":"","page":418},{"gurmukhi":"ਰੀਝ ਰਹੈ ਪ੍ਰਿਥਮੀ ਕੇ ਸਭੈ ਜਨ ਰੀਝ ਰਹਿਯੋ ਸੁਰ ਮੰਡਲ ਸਾਰੋ। ੫੩੦।","roman":"Reejh rahai prithmee ke sabhai jan reejh rahiyo sur mandal saaro | 530 |","meaning_en":"","page":418}]},{"type":"verse","number":[531],"number_text":"੫੩੧।","page":418,"lines":[{"gurmukhi":"ਗਾਵਤ ਏਕ ਨਚੈ ਇਕ ਗ੍ਵਾਰਨਿ ਤਾਰਿਨ ਕਿੰਕਨ ਕੀ ਧੁਨਿ ਬਾਜੈ।","roman":"Gaavat ek nachai ik gvaarni taarin kinkan kee dhuni baajai |","meaning_en":"","page":418},{"gurmukhi":"ਜਿਉ ਮ੍ਰਿਗ ਰਾਜਤ ਬੀਚ ਮ੍ਰਿਗੀ ਹਰਿ ਤਿਉ ਗਨ ਗ੍ਵਾਰਿਨ ਬੀਚ ਬਿਰਾਜੈ।","roman":"Jiu mrig raajat beech mrigee hari tiu gan gvaarin beech biraajai |","meaning_en":"","page":418},{"gurmukhi":"ਨਾਚਤ ਸੋਊ ਮਹਾ ਹਿਤ ਸੋ ਕਬਿ ਸ੍ਯਾਮ ਪ੍ਰਭਾ ਤਿਨ ਕੀ ਇਮ ਛਾਜੈ।","roman":"Naachat so'oo mahaa hit so kabi syaam prabhaa tin kee im chhaajai |","meaning_en":"","page":418},{"gurmukhi":"ਗਾਇਬ ਪੇਖਿ ਰਿਸੈ ਗਨ ਗੰਧ੍ਰਬ ਨਾਚਬ ਦੇਖਿ ਬਧੂ ਸੁਰ ਲਾਜੈ। ੫੩੧।","roman":"Gaaib pekhi risai gan gandhrab naachab dekhi badhoo sur laajai | 531 |","meaning_en":"","page":418}]},{"type":"verse","number":[532],"number_text":"੫੩੨।","page":418,"lines":[{"gurmukhi":"ਰਸ ਕਾਰਨ ਕੋ ਭਗਵਾਨ ਤਹਾ ਕਬਿ ਸ੍ਯਾਮ ਕਹੈ ਰਸ ਖੇਲ ਕਰਿਯੋ।","roman":"Ras kaaran ko bhagvaan tahaa kabi syaam kahai ras khel kariyo |","meaning_en":"","page":418},{"gurmukhi":"ਮਨ ਯੌ ਉਪਜੀ ਉਪਮਾ ਹਰਿ ਜੂ ਇਨ ਪੈ ਜਨੁ ਚੇਟਕ ਮੰਤ੍ਰ ਡਰਿਯੋ।","roman":"Man yau upjee upmaa hari joo in pai janu chetak mantr dariyo |","meaning_en":"","page":418},{"gurmukhi":"ਪਿਖ ਕੈ ਜਿਹ ਕੋ ਸੁਰ ਅਛ੍ਰਨ ਕੇ ਗਿਰਿ ਬੀਚ ਲਜਾਇ ਬਪੈ ਸੁ ਧਰਿਯੋ।","roman":"Pikh kai jih ko sur achhran ke giri beech lajaai bapai su dhariyo |","meaning_en":"","page":418},{"gurmukhi":"ਗੁਪੀਆ ਸੰਗਿ ਕਾਨ੍ਹ ਕੇ ਡੋਲਤ ਹੈ ਇਨ ਕੋ ਮਨੂਆ ਜਬ ਕਾਨ੍ਹ ਹਰਿਯੋ।੫੩੨।","roman":"Gupeeaa sangi kaanh ke dolat hai in ko manooaa jab kaanh hariyo | 532 |","meaning_en":"","page":418}]},{"type":"verse","number":[533],"number_text":"੫੩੩।","page":418,"lines":[{"gurmukhi":"ਸ੍ਯਾਮ ਕਹੈ ਸਭ ਹੀ ਗੁਪੀਆ ਹਰਿ ਕੇ ਸੰਗਿ ਡੋਲਤ ਹੈ ਸਭ ਹੂਈਆ।","roman":"Syaam kahai sabh hee gupeeaa hari ke sangi dolat hai sabh hooeeaa |","meaning_en":"","page":418},{"gurmukhi":"ਗਾਵਤ ਏਕ ਫਿਰੈ ਇਕ ਨਾਚਤ ਏਕ ਫਿਰੈ ਰਸ ਰੰਗ ਅਕੂਈਆ।","roman":"Gaavat ek phirai ik naachat ek phirai ras rang akooeeaa |","meaning_en":"","page":418},{"gurmukhi":"ਏਕ ਕਹੈ ਭਗਵਾਨ ਹਰੀ ਇਕ ਲੈ ਹਰਿ ਨਾਮੁ ਪਰੈ ਗਿਰਿ ਭੂਈਆ।","roman":"Ek kahai bhagvaan haree ik lai hari naamu parai giri bhooeeaa |","meaning_en":"","page":418},{"gurmukhi":"ਯੌ ਉਪਜੀ ਉਪਮਾ ਪਿਖਿ ਚੁੰਮਕ ਲਾਗੀ ਫਿਰੈ ਤਿਹ ਕੇ ਸੰਗ ਸੂਈਆ। ੫੩੩।","roman":"Yau upjee upmaa pikhi chunmak laagee phirai tih ke sang sooeeaa | 533 |","meaning_en":"","page":418}]},{"type":"verse","number":[534],"number_text":"੫੩੪।","page":419,"lines":[{"gurmukhi":"ਸੰਗ ਗ੍ਵਾਰਿਨ ਕਾਨ੍ਹ ਕਹੀ ਹਸਿ ਕੈ ਕਬਿ ਸ੍ਯਾਮ ਕਹੈ ਅਧ ਰਾਤਿ ਸਮੈ।","roman":"Sang gvaarin kaanh kahee hasi kai kabi syaam kahai adh raati samai |","meaning_en":"","page":419},{"gurmukhi":"ਹਮ ਹੂੰ ਤੁਮ ਹੂੰ ਤਜਿ ਕੈ ਸਭ ਖੇਲ ਸਭੈ ਮਿਲ ਕੈ ਹਮ ਧਾਮਿ ਰਮੈ।","roman":"Ham hoon tum hoon taji kai sabh khel sabhai mil kai ham dhaami ramai |","meaning_en":"","page":419},{"gurmukhi":"ਹਰਿ ਆਇਸੁ ਮਾਨਿ ਚਲੀ ਗ੍ਰਿਹ ਕੋ ਸਭ ਗ੍ਵਾਰਨੀਯਾ ਕਰਿ ਦੂਰ ਗਮੈ।","roman":"Hari aaisu maani chalee grih ko sabh gvaarneeyaa kari door gamai |","meaning_en":"","page":419},{"gurmukhi":"ਅਬ ਜਾਇ ਟਿਕੈ ਸਭ ਆਸਨ ਮੈ ਕਰਿ ਕੈ ਸਭ ਪ੍ਰਾਤ ਕੀ ਨੇਹ ਤਮੈ। ੫੩੪।","roman":"Ab jaai tikai sabh aasan mai kari kai sabh praat kee neh tamai | 534 |","meaning_en":"","page":419}]},{"type":"verse","number":[535],"number_text":"੫੩੫।","page":419,"lines":[{"gurmukhi":"ਹਰਿ ਸੋ ਅਰੁ ਗੋਪਿਨ ਸੰਗਿ ਕਿਧੋ ਕਬਿ ਸ੍ਯਾਮ ਕਹੈ ਅਤਿ ਖੇਲ ਭਯੋ ਹੈ।","roman":"Hari so aru gopin sangi kidho kabi syaam kahai ati khel bhayo hai |","meaning_en":"","page":419},{"gurmukhi":"ਲੈ ਹਰਿ ਜੀ ਤਿਨ ਕੋ ਸੰਗ ਆਪਨ ਤਿਆਗ ਕੈ ਖੇਲ ਕੋ ਧਾਮਿ ਅਯੋ ਹੈ।","roman":"Lai hari jee tin ko sang aapan tiaag kai khel ko dhaami ayo hai |","meaning_en":"","page":419},{"gurmukhi":"ਤਾ ਛਬਿ ਕੋ ਜਸੁ ਉਚ ਮਹਾ ਕਬਿ ਨੇ ਅਪੁਨੇ ਮਨਿ ਚੀਨ ਲਯੋ ਹੈ।","roman":"Taa chhabi ko jasu uch mahaa kabi ne apune mani cheen layo hai |","meaning_en":"","page":419},{"gurmukhi":"ਕਾਗਜੀਏ ਰਸ ਕੋ ਅਤਿ ਹੀ ਸੁ ਮਨੋ ਗਨਤੀ ਕਰਿ ਜੋਰੁ ਦਯੋ ਹੈ। ੫੩੫।","roman":"Kaagjee'e ras ko ati hee su mano gantee kari joru dayo hai | 535 |","meaning_en":"","page":419}]},{"type":"heading","kind":"section_heading","name":"ਅਥ ਕਰਿ ਪਕਰ ਖੇਲਬੋ ਕਥਨੰ। ਰਾਸ ਮੰਡਲ","gurmukhi":"ਅਥ ਕਰਿ ਪਕਰ ਖੇਲਬੋ ਕਥਨੰ। ਰਾਸ ਮੰਡਲ","roman":"Ath kari pakar khelbo kathnan | raas mandal","meaning_en":"","page":419},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":419},{"type":"verse","number":[536],"number_text":"੫੩੬।","page":419,"lines":[{"gurmukhi":"ਪ੍ਰਾਤ ਭਏ ਹਰਿ ਜੂ ਤਜਿ ਕੈ ਗ੍ਰਿਹ ਧਾਇ ਗਏ ਉਠਿ ਠਉਰ ਕਹਾ ਕੋ।","roman":"Praat bhae hari joo taji kai grih dhaai gae uthi thaur kahaa ko |","meaning_en":"","page":419},{"gurmukhi":"ਫੂਲ ਰਹੇ ਜਿਹਿ ਫੂਲ ਭਲੀ ਬਿਧਿ ਤੀਰ ਬਹੈ ਜਮੁਨਾ ਸੋ ਤਹਾ ਕੋ।","roman":"Phool rahe jihi phool bhalee bidhi teer bahai jamunaa so tahaa ko |","meaning_en":"","page":419},{"gurmukhi":"ਖੇਲਤ ਹੈ ਸੋਊ ਭਾਤਿ ਭਲੀ ਕਬਿ ਸ੍ਯਾਮ ਕਹੈ ਕਛੁ ਤ੍ਰਾਸ ਨ ਤਾ ਕੋ।","roman":"Khelat hai so'oo bhaati bhalee kabi syaam kahai kachhu traas na taa ko |","meaning_en":"","page":419},{"gurmukhi":"ਸੰਗ ਬਜਾਵਤ ਹੈ ਮੁਰਲੀ ਸੋਊ ਗਊਅਨ ਕੇ ਮਿਸ ਗ੍ਵਾਰਨਿਯਾ ਕੋ। ੫੩੬।","roman":"Sang bajaavat hai murlee so'oo gaooan ke mis gvaarniyaa ko | 536 |","meaning_en":"","page":419}]},{"type":"verse","number":[537],"number_text":"੫੩੭।","page":419,"lines":[{"gurmukhi":"ਰਾਸ ਕਥਾ ਕਬਿ ਸ੍ਯਾਮ ਕਹੈ ਸੁਨ ਕੈ ਬ੍ਰਿਖਭਾਨੁ ਸੁਤਾ ਸੋਊ ਧਾਈ।","roman":"Raas kathaa kabi syaam kahai sun kai brikhbhaanu sutaa so'oo dhaaee |","meaning_en":"","page":419},{"gurmukhi":"ਜਾ ਮੁਖ ਸੁਧ ਨਿਸਾਪਤਿ ਸੋ ਜਿਹ ਕੇ ਤਨ ਕੰਚਨ ਸੀ ਛਬਿ ਛਾਈ।","roman":"Jaa mukh sudh nisaapti so jih ke tan kanchan see chhabi chhaaee |","meaning_en":"","page":419},{"gurmukhi":"ਜਾ ਕੀ ਪ੍ਰਭਾ ਕਬਿ ਦੇਤ ਸਭੈ ਸੋਊ ਤਾ ਮੈ ਰਜੈ ਬਰਨੀ ਨਹਿ ਜਾਈ।","roman":"Jaa kee prabhaa kabi det sabhai so'oo taa mai rajai barnee nahi jaaee |","meaning_en":"","page":419},{"gurmukhi":"ਸ੍ਯਾਮ ਕੀ ਸੋਭ ਸੁ ਗੋਪਿਨ ਤੇ ਸੁਨਿ ਕੈ ਤਰੁਨੀ ਹਰਨੀ ਜਿਮ ਧਾਈ। ੫੩੭।","roman":"Syaam kee sobh su gopin te suni kai tarunee harnee jim dhaaee | 537 |","meaning_en":"","page":419}]},{"type":"heading","kind":"chhand","name":"ਕਬਿਤੁ","gurmukhi":"ਕਬਿਤੁ","roman":"Kabitu","meaning_en":"","page":419},{"type":"verse","number":[538],"number_text":"੫੩੮।","page":419,"lines":[{"gurmukhi":"ਸੇਤ ਧਰੇ ਸਾਰੀ ਬ੍ਰਿਖਭਾਨੁ ਕੀ ਕੁਮਾਰੀ","roman":"Set dhare saaree brikhbhaanu kee kumaaree","meaning_en":"","page":419},{"gurmukhi":"ਜਸ ਹੀ ਕੀ ਮਨੋ ਬਾਰੀ ਐਸੀ ਰਚੀ ਹੈ ਨ ਕੋ ਦਈ।","roman":"Jas hee kee mano baaree aisee rachee hai na ko daee |","meaning_en":"","page":419},{"gurmukhi":"ਰੰਭਾ ਉਰਬਸੀ ਅਉਰ ਸਚੀ ਸੁ ਮਦੋਦਰੀ","roman":"Ranbhaa urabsee aur sachee su madodree","meaning_en":"","page":419},{"gurmukhi":"ਪੈ ਐਸੀ ਪ੍ਰਭਾ ਕਾਕੀ ਜਗ ਬੀਚ ਨ ਕਛੂ ਭਈ।","roman":"Pai aisee prabhaa kaakee jag beech na kachhoo bhaee |","meaning_en":"","page":419},{"gurmukhi":"ਮੋਤਿਨ ਕੇ ਹਾਰ ਗਰੇ ਡਾਰਿ ਰੁਚਿ ਸੋ ਸੁਧਾਰ","roman":"Motin ke haar gare daari ruchi so sudhaar","meaning_en":"","page":419},{"gurmukhi":"ਕਾਨ੍ਹ ਜੂ ਪੈ ਚਲੀ ਕਬਿ ਸ੍ਯਾਮ ਰਸ ਕੇ ਲਈ।","roman":"Kaanh joo pai chalee kabi syaam ras ke laee |","meaning_en":"","page":419},{"gurmukhi":"ਸੇਤੈ ਸਾਜ ਸਾਜਿ ਚਲੀ ਸਾਵਰੇ ਕੀ ਪ੍ਰੀਤਿ ਕਾਜ","roman":"Setai saaj saaji chalee saavre kee preeti kaaj","meaning_en":"","page":419},{"gurmukhi":"ਚਾਦਨੀ ਮੈ ਰਾਧਾ ਮਾਨੋ ਚਾਦਨੀ ਸੀ ਹ੍ਵੈ ਗਈ। ੫੩੮।","roman":"Chaadnee mai raadhaa maano chaadnee see hvai gaee | 538 |","meaning_en":"","page":419}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":420},{"type":"verse","number":[539],"number_text":"੫੩੯।","page":420,"lines":[{"gurmukhi":"ਅੰਜਨ ਆਡਿ ਸੁ ਧਾਰ ਭਲੇ ਪਟ ਭੂਖਨ ਅੰਗ ਸੁ ਧਾਰ ਚਲੀ।","roman":"Anjan aadi su dhaar bhale pat bhookhan ang su dhaar chalee |","meaning_en":"","page":420},{"gurmukhi":"ਜਨੁ ਦੂਸਰ ਚੰਦ੍ਰਕਲਾ ਪ੍ਰਗਟੀ ਜਨੁ ਰਾਜਤ ਕੰਜ ਕੀ ਸੇਤ ਕਲੀ।","roman":"Janu doosar chandraklaa pragtee janu raajat kanj kee set kalee |","meaning_en":"","page":420},{"gurmukhi":"ਹਰਿ ਕੇ ਪਗ ਭੇਟਨ ਕਾਜ ਚਲੀ ਕਬਿ ਸ੍ਯਾਮ ਕਹੈ ਸੰਗ ਰਾਧੇ ਅਲੀ।","roman":"Hari ke pag bhetan kaaj chalee kabi syaam kahai sang raadhe alee |","meaning_en":"","page":420},{"gurmukhi":"ਜਨੁ ਜੋਤਿ ਤਰਿਯਨ ਗ੍ਵਾਰਿਨ ਤੇ ਇਹ ਚੰਦ ਕੀ ਚਾਦਨੀ ਬਾਲੀ ਭਲੀ। ੫੩੯।","roman":"Janu joti tariyan gvaarin te ih chand kee chaadnee baalee bhalee | 539 |","meaning_en":"","page":420}]},{"type":"verse","number":[540],"number_text":"੫੪੦।","page":420,"lines":[{"gurmukhi":"ਕਾਨ੍ਹ ਸੋ ਪ੍ਰੀਤਿ ਬਢੀ ਤਿਹ ਕੀ ਮਨ ਮੈ ਅਤਿ ਹੀ ਨਹਿ ਨੈਕੁ ਘਟੀ ਹੈ।","roman":"Kaanh so preeti badhee tih kee man mai ati hee nahi naiku ghatee hai |","meaning_en":"","page":420},{"gurmukhi":"ਰੂਪ ਸਚੀ ਅਰੁ ਪੈ ਰਤਿ ਤੈ ਮਨ ਤ੍ਰੀਯਨ ਤੇ ਨਹਿ ਨੈਕੁ ਲਟੀ ਹੈ।","roman":"Roop sachee aru pai rati tai man treeyan te nahi naiku latee hai |","meaning_en":"","page":420},{"gurmukhi":"ਰਾਸ ਮੈ ਖੇਲਨਿ ਕਾਜ ਚਲੀ ਸਜਿ ਸਾਜਿ ਸਭੈ ਕਬਿ ਸ੍ਯਾਮ ਨਟੀ ਹੈ।","roman":"Raas mai khelni kaaj chalee saji saaji sabhai kabi syaam natee hai |","meaning_en":"","page":420},{"gurmukhi":"ਸੁੰਦਰ ਗ੍ਵਾਰਿਨ ਕੈ ਘਨ ਮੈ ਮਨੋ ਰਾਧਿਕਾ ਚੰਦ੍ਰਕਲਾ ਪ੍ਰਗਟੀ ਹੈ। ੫੪੦।","roman":"Sundar gvaarin kai ghan mai mano raadhikaa chandraklaa pragtee hai | 540 |","meaning_en":"","page":420}]},{"type":"verse","number":[541],"number_text":"੫੪੧।","page":420,"lines":[{"gurmukhi":"ਬ੍ਰਹਮਾ ਪਿਖਿ ਕੈ ਜਿਹ ਰੀਝ ਰਹਿਓ ਜਿਹ ਕੋ ਦਿਖ ਕੈ ਸਿਵ ਧ੍ਯਾਨ ਛੁਟਾ ਹੈ।","roman":"Brahmaa pikhi kai jih reejh rahio jih ko dikh kai siv dhyaan chhutaa hai |","meaning_en":"","page":420},{"gurmukhi":"ਜਾ ਨਿਰਖੇ ਰਤਿ ਰੀਝ ਰਹੀ ਰਤਿ ਕੇ ਪਤਿ ਕੋ ਪਿਖਿ ਮਾਨ ਟੁਟਾ ਹੈ।","roman":"Jaa nirkhe rati reejh rahee rati ke pati ko pikhi maan tutaa hai |","meaning_en":"","page":420},{"gurmukhi":"ਕੋਕਿਲ ਕੰਠ ਚੁਰਾਇ ਲੀਯੋ ਜਿਨਿ ਭਾਵਨ ਕੋ ਸਭ ਭਾਵ ਲੁਟਾ ਹੈ।","roman":"Kokil kanth churaai leeyo jini bhaavan ko sabh bhaav lutaa hai |","meaning_en":"","page":420},{"gurmukhi":"ਗ੍ਵਾਰਿਨ ਕੇ ਘਨ ਬੀਚ ਬਿਰਾਜਤ ਰਾਧਿਕਾ ਮਾਨਹੁ ਬਿਜੁ ਛਟਾ ਹੈ। ੫੪੧।","roman":"Gvaarin ke ghan beech biraajat raadhikaa maanhu biju chhataa hai | 541 |","meaning_en":"","page":420}]},{"type":"verse","number":[542],"number_text":"੫੪੨।","page":420,"lines":[{"gurmukhi":"ਕਾਨ੍ਹ ਕੇ ਪੂਜਨ ਪਾਇ ਚਲੀ ਬ੍ਰਿਖਭਾਨੁ ਸੁਤਾ ਸਭ ਸਾਜ ਸਜੈ।","roman":"Kaanh ke poojan paai chalee brikhbhaanu sutaa sabh saaj sajai |","meaning_en":"","page":420},{"gurmukhi":"ਜਿਹ ਕੋ ਪਿਖ ਕੈ ਮਨਿ ਮੋਹਿ ਰਹੈ ਕਬਿ ਸ੍ਯਾਮ ਕਹੈ ਦੁਤਿ ਸੀਸ ਰਜੈ।","roman":"Jih ko pikh kai mani mohi rahai kabi syaam kahai duti sees rajai |","meaning_en":"","page":420},{"gurmukhi":"ਜਿਨ ਅੰਗ ਪ੍ਰਭਾ ਕਬਿ ਦੇਤ ਸਭੈ ਸੋਊ ਅੰਗ ਧਰੇ ਤ੍ਰਿਯ ਰਾਜ ਛਜੈ।","roman":"Jin ang prabhaa kabi det sabhai so'oo ang dhare triy raaj chhajai |","meaning_en":"","page":420},{"gurmukhi":"ਜਿਹ ਕੋ ਪਿਖਿ ਕੰਦ੍ਰਪ ਰੀਝ ਰਹੈ ਜਿਹ ਕੋ ਦਿਖਿ ਚਾਦਨੀ ਚੰਦ ਲਜੈ। ੫੪੨।","roman":"Jih ko pikhi kandrap reejh rahai jih ko dikhi chaadnee chand lajai | 542 |","meaning_en":"","page":420}]},{"type":"verse","number":[543],"number_text":"੫੪੩।","page":420,"lines":[{"gurmukhi":"ਸਿਤ ਸੁੰਦਰੁ ਸਾਜ ਸਭੈ ਸਜਿ ਕੈ ਬ੍ਰਿਖਭਾਨ ਸੁਤਾ ਇਹ ਭਾਤਿ ਬਨੀ।","roman":"Sit sundru saaj sabhai saji kai brikhbhaan sutaa ih bhaati banee |","meaning_en":"","page":420},{"gurmukhi":"ਮੁਖ ਰਾਜਤ ਸੁਧ ਨਿਸਾਪਤਿ ਸੋ ਜਿਹ ਮੈ ਅਤਿ ਚਾਦਨੀ ਰੂਪ ਘਨੀ।","roman":"Mukh raajat sudh nisaapti so jih mai ati chaadnee roop ghanee |","meaning_en":"","page":420},{"gurmukhi":"ਰਸ ਕੋ ਕਰਿ ਰਾਧਿਕਾ ਕੋਪ ਚਲੀ ਮਨੋ ਸਾਜ ਸੋ ਸਾਜ ਕੈ ਮੈਨ ਅਨੀ।","roman":"Ras ko kari raadhikaa kop chalee mano saaj so saaj kai main anee |","meaning_en":"","page":420},{"gurmukhi":"ਤਿਹ ਪੇਖਿ ਭਏ ਭਗਵਾਨ ਖੁਸੀ ਸੋਊ ਤ੍ਰੀਯਨ ਤੇ ਤ੍ਰਿਯ ਰਾਜ ਗਨੀ। ੫੪੩।","roman":"Tih pekhi bhae bhagvaan khusee so'oo treeyan te triy raaj ganee | 543 |","meaning_en":"","page":420}]},{"type":"heading","kind":"speaker","name":"ਰਾਧੇ ਬਾਚ ਗੋਪਿਨ ਸੋ","gurmukhi":"ਰਾਧੇ ਬਾਚ ਗੋਪਿਨ ਸੋ","roman":"Raadhe baach gopin so","meaning_en":"","page":420},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":420},{"type":"verse","number":[544],"number_text":"੫੪੪।","page":420,"lines":[{"gurmukhi":"ਬ੍ਰਿਖਭਾਨੁ ਸੁਤਾ ਹਰਿ ਪੇਖਿ ਹਸੀ ਇਹ ਭਾਤਿ ਕਹਿਯੋ ਸੰਗ ਗ੍ਵਾਰਿਨ ਕੈ।","roman":"Brikhbhaanu sutaa hari pekhi hasee ih bhaati kahiyo sang gvaarin kai |","meaning_en":"","page":420},{"gurmukhi":"ਸਮ ਦਾਰਿਮ ਦਾਤ ਨਿਕਾਸ ਕਿਧੋ ਸਮ ਚੰਦ ਮੁਖੀ ਬ੍ਰਿਜ ਬਾਰਨ ਕੈ।","roman":"Sam daarim daat nikaas kidho sam chand mukhee brij baaran kai |","meaning_en":"","page":420},{"gurmukhi":"ਹਮ ਅਉ ਹਰਿ ਜੀ ਅਤਿ ਹੋਡ ਪਰੀ ਰਸ ਹੀ ਕੇ ਸੁ ਬੀਚ ਮਹਾ ਰਨ ਕੈ।","roman":"Ham au hari jee ati hod paree ras hee ke su beech mahaa ran kai |","meaning_en":"","page":421},{"gurmukhi":"ਤਜਿ ਕੇ ਸਭ ਸੰਕਿ ਨਿਸੰਕ ਭਿਰੋ ਸੰਗ ਐਸੇ ਕਹਿਯੋ ਹਸਿ ਗ੍ਵਾਰਿਨ ਕੈ। ੫੪੪।","roman":"Taji ke sabh sanki nisank bhiro sang aise kahiyo hasi gvaarin kai | 544 |","meaning_en":"","page":421}]},{"type":"verse","number":[545],"number_text":"੫੪੫।","page":421,"lines":[{"gurmukhi":"ਹਸਿ ਬਾਤ ਕਹੀ ਸੰਗ ਗੋਪਿਨ ਕੇ ਕਬਿ ਸ੍ਯਾਮ ਕਹੈ ਬ੍ਰਿਖਭਾਨੁ ਜਈ।","roman":"Hasi baat kahee sang gopin ke kabi syaam kahai brikhbhaanu jaee |","meaning_en":"","page":421},{"gurmukhi":"ਮਨੋ ਆਪ ਹੀ ਤੇ ਬ੍ਰਹਮਾ ਸੁ ਰਚੀ ਰੁਚਿ ਸੋ ਇਹ ਰੂਪ ਅਨੂਪ ਮਈ।","roman":"Mano aap hee te brahmaa su rachee ruchi so ih roop anoop maee |","meaning_en":"","page":421},{"gurmukhi":"ਹਰਿ ਕੋ ਪਿਖਿ ਕੈ ਨਿਹੁਰਾਇ ਗਈ ਉਪਮਾ ਤਿਹ ਕੀ ਕਬਿ ਭਾਖ ਦਈ।","roman":"Hari ko pikhi kai nihuraai gaee upmaa tih kee kabi bhaakh daee |","meaning_en":"","page":421},{"gurmukhi":"ਮਨੋ ਜੋਬਨ ਭਾਰ ਸਹਿਯੋ ਨ ਗਯੋ ਤਿਹ ਤੇ ਬ੍ਰਿਜ ਭਾਮਿਨਿ ਨੀਚਿ ਭਈ। ੫੪੫।","roman":"Mano joban bhaar sahiyo na gayo tih te brij bhaamini neechi bhaee | 545 |","meaning_en":"","page":421}]},{"type":"verse","number":[546],"number_text":"੫੪੬।","page":421,"lines":[{"gurmukhi":"ਸਭ ਹੀ ਮਿਲਿ ਰਾਸ ਕੋ ਖੇਲ ਕਰੈ ਸਭ ਗ੍ਵਾਰਨਿਯਾ ਅਤਿ ਹੀ ਹਿਤ ਤੇ।","roman":"Sabh hee mili raas ko khel karai sabh gvaarniyaa ati hee hit te |","meaning_en":"","page":421},{"gurmukhi":"ਬ੍ਰਿਖਭਾਨੁ ਸੁਤਾ ਸੁਭ ਸਾਜ ਸਜੇ ਸੁ ਬਿਰਾਜਤ ਸਾਜ ਸਭੈ ਸਿਤ ਤੇ।","roman":"Brikhbhaanu sutaa subh saaj saje su biraajat saaj sabhai sit te |","meaning_en":"","page":421},{"gurmukhi":"ਫੁਨਿ ਊਚ ਪ੍ਰਭਾ ਅਤਿ ਹੀ ਤਿਨ ਕੀ ਕਬਿ ਸ੍ਯਾਮ ਬਿਚਾਰ ਕਹੀ ਚਿਤ ਤੇ।","roman":"Phuni ooch prabhaa ati hee tin kee kabi syaam bichaar kahee chit te |","meaning_en":"","page":421},{"gurmukhi":"ਉਤ ਤੇ ਘਨਸ੍ਯਾਮ ਬਿਰਾਜਤ ਹੈ ਹਰਿ ਰਾਧਿਕਾ ਬਿਦੁਲਤਾ ਇਤ ਤੇ। ੫੪੬।","roman":"Ut te ghansyaam biraajat hai hari raadhikaa bidultaa it te | 546 |","meaning_en":"","page":421}]},{"type":"verse","number":[547],"number_text":"੫੪੭।","page":421,"lines":[{"gurmukhi":"ਬ੍ਰਿਖਭਾਨੁ ਸੁਤਾ ਤਹਿ ਖੇਲਤ ਰਾਸਿ ਸੁ ਸ੍ਯਾਮ ਕਹੈ ਸਖੀਯਾ ਸੰਗ ਲੈ।","roman":"Brikhbhaanu sutaa tahi khelat raasi su syaam kahai sakheeyaa sang lai |","meaning_en":"","page":421},{"gurmukhi":"ਉਤ ਚੰਦ੍ਰ ਭਗਾ ਸਭ ਗ੍ਵਾਰਿਨ ਕੋ ਤਨ ਚੰਦਨ ਕੇ ਸੰਗ ਲੇਪਹਿ ਕੈ।","roman":"Ut chandr bhagaa sabh gvaarin ko tan chandan ke sang lephi kai |","meaning_en":"","page":421},{"gurmukhi":"ਜਿਨ ਕੇ ਮ੍ਰਿਗ ਸੇ ਦ੍ਰਿਗ ਸੁੰਦਰ ਰਾਜਤ ਛਾਜਤ ਗਾਮਨਿ ਪੈ ਜਿਨ ਗੈ।","roman":"Jin ke mrig se drig sundar raajat chhaajat gaamni pai jin gai |","meaning_en":"","page":421},{"gurmukhi":"ਮਨਿ ਯੌ ਉਪਜੀ ਉਪਮਾ ਨਹਿ ਚੰਦ ਕੀ ਚਾਦਨੀ ਜੋਬਨ ਵਾਰਨ ਮੈ। ੫੪੭।","roman":"Mani yau upjee upmaa nahi chand kee chaadnee joban vaaran mai | 547 |","meaning_en":"","page":421}]},{"type":"heading","kind":"speaker","name":"ਚੰਦ੍ਰਭਗਾ ਬਾਚ ਰਾਧੇ ਪ੍ਰਤਿ","gurmukhi":"ਚੰਦ੍ਰਭਗਾ ਬਾਚ ਰਾਧੇ ਪ੍ਰਤਿ","roman":"Chandrabhgaa baach raadhe prati","meaning_en":"","page":421},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":421},{"type":"verse","number":[548],"number_text":"੫੪੮।","page":421,"lines":[{"gurmukhi":"ਬਤੀਯਾ ਫੁਨਿ ਚੰਦ੍ਰਭਗਾ ਮੁਖ ਤੇ ਇਹ ਭਾਤਿ ਕਹੀ ਬ੍ਰਿਖਭਾਨ ਸੁਤਾ ਸੋ।","roman":"Bateeyaa phuni chandrabhgaa mukh te ih bhaati kahee brikhbhaan sutaa so |","meaning_en":"","page":421},{"gurmukhi":"ਆਵਹੁ ਖੇਲ ਕਰੇ ਹਰਿ ਸੋ ਹਮ ਨਾਹਕ ਖੇਲ ਕਰੋ ਤੁਮ ਕਾ ਸੋ।","roman":"Aavhu khel kare hari so ham naahak khel karo tum kaa so |","meaning_en":"","page":421},{"gurmukhi":"ਤਾ ਕੀ ਪ੍ਰਭਾ ਕਬਿ ਸ੍ਯਾਮ ਕਹੈ ਉਪਜੀ ਹੈ ਜੋਊ ਅਪਨੇ ਮਨੂਆ ਸੋ।","roman":"Taa kee prabhaa kabi syaam kahai upjee hai jo'oo apne manooaa so |","meaning_en":"","page":421},{"gurmukhi":"ਗ੍ਵਾਰਿਨ ਜੋਤਿ ਤਰਈਯਨ ਕੀ ਛਪਗੀ ਦੁਤਿ ਰਾਧਿਕਾ ਚੰਦ੍ਰ ਕਲਾ ਸੋ। ੫੪੮।","roman":"Gvaarin joti taraeeyan kee chhapgee duti raadhikaa chandr kalaa so | 548 |","meaning_en":"","page":421}]},{"type":"heading","kind":"speaker","name":"ਰਾਧੇ ਬਾਚ","gurmukhi":"ਰਾਧੇ ਬਾਚ","roman":"Raadhe baach","meaning_en":"","page":421},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":421},{"type":"verse","number":[549],"number_text":"੫੪੯।","page":421,"lines":[{"gurmukhi":"ਸੁਨਿ ਚੰਦ੍ਰਭਗਾ ਕੀ ਸਭੈ ਬਤੀਯਾ ਬ੍ਰਿਖਭਾਨ ਸੁਤਾ ਤਬ ਐਸੇ ਕਹਿਯੋ ਹੈ।","roman":"Suni chandrabhgaa kee sabhai bateeyaa brikhbhaan sutaa tab aise kahiyo hai |","meaning_en":"","page":421},{"gurmukhi":"ਯਾਹੀ ਕੇ ਹੇਤ ਸੁਨੋ ਸਜਨੀ ਹਮ ਲੋਕਨ ਕੋ ਉਪਹਾਸ ਸਹਿਯੋ ਹੈ।","roman":"Yaahee ke het suno sajnee ham lokan ko uphaas sahiyo hai |","meaning_en":"","page":421},{"gurmukhi":"ਸ੍ਰਉਨਨ ਮੈ ਸੁਨਿ ਰਾਸ ਕਥਾ ਤਬ ਹੀ ਮਨ ਮੈ ਹਮ ਧ੍ਯਾਨ ਗਹਿਯੋ ਹੈ।","roman":"Sraunan mai suni raas kathaa tab hee man mai ham dhyaan gahiyo hai |","meaning_en":"","page":421},{"gurmukhi":"ਸ੍ਯਾਮ ਕਹੈ ਅਖੀਆ ਪਿਖ ਕੈ ਹਮਰੇ ਮਨ ਕੋ ਤਨ ਮੋਹਿ ਰਹਿਯੋ ਹੈ। ੫੪੯।","roman":"Syaam kahai akheeaa pikh kai hamre man ko tan mohi rahiyo hai | 549 |","meaning_en":"","page":421}]},{"type":"verse","number":[550],"number_text":"੫੫੦।","page":422,"lines":[{"gurmukhi":"ਤਬ ਚੰਦ੍ਰਭਗਾ ਇਹ ਭਾਤਿ ਕਹਿਯੋ ਸਜਨੀ ਹਮਰੀ ਬਤੀਆ ਸੁਨਿ ਲੀਜੈ।","roman":"Tab chandrabhgaa ih bhaati kahiyo sajnee hamree bateeaa suni leejai |","meaning_en":"","page":422},{"gurmukhi":"ਦੇਖਹੁ ਸ੍ਯਾਮ ਬਿਰਾਜਤ ਹੈ ਜਿਹ ਕੇ ਮੁਖ ਕੇ ਪਿਖਏ ਫੁਨਿ ਜੀਜੈ।","roman":"Dekhhu syaam biraajat hai jih ke mukh ke pikhae phuni jeejai |","meaning_en":"","page":422},{"gurmukhi":"ਜਾ ਕੇ ਕਰੇ ਮਿਤ ਹੋਇ ਖੁਸੀ ਸੁਨੀਐ ਉਠ ਕੈ ਸੋਊ ਕਾਜ ਕਰੀਜੈ।","roman":"Jaa ke kare mit hoi khusee suneeai uth kai so'oo kaaj kareejai |","meaning_en":"","page":422},{"gurmukhi":"ਤਾਹੀ ਤੇ ਰਾਧੇ ਕਹੋ ਤੁਮ ਸੋ ਅਬ ਚਾਰ ਭਈ ਤੁ ਬਿਚਾਰ ਨ ਕੀਜੈ। ੫੫੦।","roman":"Taahee te raadhe kaho tum so ab chaar bhaee tu bichaar na keejai | 550 |","meaning_en":"","page":422}]},{"type":"heading","kind":"speaker","name":"ਕਬਿਯੋ ਬਾਚ","gurmukhi":"ਕਬਿਯੋ ਬਾਚ","roman":"Kabiyo baach","meaning_en":"","page":422},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":422},{"type":"verse","number":[551],"number_text":"੫੫੧।","page":422,"lines":[{"gurmukhi":"ਕਾਨ੍ਹ ਕੇ ਭੇਟਨ ਪਾਇ ਚਲੀ ਬਤੀਯਾ ਸੁਨਿ ਚੰਦ੍ਰਭਗਾ ਫੁਨਿ ਕੈਸੇ।","roman":"Kaanh ke bhetan paai chalee bateeyaa suni chandrabhgaa phuni kaise |","meaning_en":"","page":422},{"gurmukhi":"ਮਾਨਹੁ ਨਾਗ ਸੁਤਾ ਇਹ ਸੁੰਦਰਿ ਤਿਆਗਿ ਚਲੀ ਗ੍ਰਿਹਿ ਪਤ੍ਰ ਧਰੈ ਸੇ।","roman":"Maanhu naag sutaa ih sundri tiaagi chalee grihi patr dharai se |","meaning_en":"","page":422},{"gurmukhi":"ਗ੍ਵਾਰਨਿ ਮੰਦਰਿ ਤੇ ਨਿਕਸੀ ਕਬਿ ਸ੍ਯਾਮ ਕਹੈ ਉਪਮਾ ਤਿਹ ਐਸੇ।","roman":"Gvaarni mandri te niksee kabi syaam kahai upmaa tih aise |","meaning_en":"","page":422},{"gurmukhi":"ਮਾਨਹੁ ਸ੍ਯਾਮ ਘਨੈ ਤਜਿ ਕੈ ਪ੍ਰਗਟੀ ਹੈ ਸੋਊ ਬਿਜਲੀ ਦੁਤਿ ਜੈਸੇ। ੫੫੧।","roman":"Maanhu syaam ghanai taji kai pragtee hai so'oo bijlee duti jaise | 551 |","meaning_en":"","page":422}]},{"type":"verse","number":[552],"number_text":"੫੫੨।","page":422,"lines":[{"gurmukhi":"ਰਾਸਹਿ ਕੀ ਰਚਨਾ ਭਗਵਾਨ ਕਹੈ ਕਬਿ ਸ੍ਯਾਮ ਬਚਿਤ੍ਰ ਕਰੀ ਹੈ।","roman":"Raashi kee rachnaa bhagvaan kahai kabi syaam bachitr karee hai |","meaning_en":"","page":422},{"gurmukhi":"ਰਾਜਤ ਹੈ ਤਰਏ ਜਮੁਨਾ ਅਤਿ ਹੀ ਤਹ ਚਾਦਨੀ ਚੰਦ ਕਰੀ ਹੈ।","roman":"Raajat hai tarae jamunaa ati hee tah chaadnee chand karee hai |","meaning_en":"","page":422},{"gurmukhi":"ਸੇਤ ਪਟੈ ਸੰਗ ਰਾਜਤ ਗ੍ਵਾਰਿਨ ਤਾ ਕੀ ਪ੍ਰਭਾ ਕਬਿ ਨੇ ਸੁ ਕਰੀ ਹੈ।","roman":"Set patai sang raajat gvaarin taa kee prabhaa kabi ne su karee hai |","meaning_en":"","page":422},{"gurmukhi":"ਮਾਨਹੁ ਰਾਸ ਬਗੀਚਨ ਮੈ ਇਹ ਫੂਲਨ ਕੀ ਫੁਲਵਾਰਿ ਜਰੀ ਹੈ। ੫੫੨।","roman":"Maanhu raas bageechan mai ih phoolan kee phulvaari jaree hai | 552 |","meaning_en":"","page":422}]},{"type":"verse","number":[553],"number_text":"੫੫੩।","page":422,"lines":[{"gurmukhi":"ਚੰਦ੍ਰਭਗਾ ਹੂੰ ਕੋ ਮਾਨਿ ਕਹਿਯੋ ਬ੍ਰਿਖਭਾਨ ਸੁਤਾ ਹਰਿ ਪਾਇਨ ਲਾਗੀ।","roman":"Chandrabhgaa hoon ko maani kahiyo brikhbhaan sutaa hari paain laagee |","meaning_en":"","page":422},{"gurmukhi":"ਮੈਨ ਸੀ ਸੁੰਦਰ ਮੂਰਤਿ ਪੇਖਿ ਕੈ ਤਾਹੀ ਕੇ ਦੇਖਿਬੇ ਕੋ ਅਨੁਰਾਗੀ।","roman":"Main see sundar moorti pekhi kai taahee ke dekhibe ko anuraagee |","meaning_en":"","page":422},{"gurmukhi":"ਸੋਵਤ ਥੀ ਜਨੁ ਲਾਜ ਕੀ ਨੀਦ ਮੈ ਲਾਜ ਕੀ ਨੀਦ ਤਜੀ ਅਬ ਜਾਗੀ।","roman":"Sovat thee janu laaj kee need mai laaj kee need tajee ab jaagee |","meaning_en":"","page":422},{"gurmukhi":"ਜਾ ਕੋ ਮੁਨੀ ਨਹਿ ਅੰਤੁ ਲਹੈ ਇਹ ਤਾਹੀ ਸੋ ਖੇਲ ਕਰੈ ਬਡਭਾਗੀ। ੫੫੩।","roman":"Jaa ko munee nahi antu lahai ih taahee so khel karai badbhaagee | 553 |","meaning_en":"","page":422}]},{"type":"heading","kind":"speaker","name":"ਕਾਨ੍ਹ ਬਾਚ ਰਾਧਾ ਸੋ","gurmukhi":"ਕਾਨ੍ਹ ਬਾਚ ਰਾਧਾ ਸੋ","roman":"Kaanh baach raadhaa so","meaning_en":"","page":422},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":422},{"type":"verse","number":[554],"number_text":"੫੫੪।","page":422,"lines":[{"gurmukhi":"ਕ੍ਰਿਸਨ ਰਾਧਿਕਾ ਸੰਗ ਕਹਿਯੋ ਅਤਿ ਹੀ ਬਿਹਸਿ ਕੈ ਬਾਤ।","roman":"Krisan raadhikaa sang kahiyo ati hee bihsi kai baat |","meaning_en":"","page":422},{"gurmukhi":"ਖੇਲਹੁ ਗਾਵਹੁ ਪ੍ਰੇਮ ਸੋ ਸੁਨਿ ਸਮ ਕੰਚਨ ਗਾਤ। ੫੫੪।","roman":"Khelhu gaavhu prem so suni sam kanchan gaat | 554 |","meaning_en":"","page":422}]},{"type":"verse","number":[555],"number_text":"੫੫੫।","page":422,"lines":[{"gurmukhi":"ਕ੍ਰਿਸਨ ਬਾਤ ਸੁਨਿ ਰਾਧਿਕਾ ਅਤਿ ਹੀ ਬਿਹਸਿ ਕੈ ਚੀਤ।","roman":"Krisan baat suni raadhikaa ati hee bihsi kai cheet |","meaning_en":"","page":422},{"gurmukhi":"ਰਾਸ ਬਿਖੈ ਗਾਵਨ ਲਗੀ ਗ੍ਵਾਰਿਨ ਸੋ ਮਿਲਿ ਗੀਤ। ੫੫੫।","roman":"Raas bikhai gaavan lagee gvaarin so mili geet | 555 |","meaning_en":"","page":422}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":422},{"type":"verse","number":[556],"number_text":"੫੫੬।","page":422,"lines":[{"gurmukhi":"ਚੰਦ੍ਰਭਗਾ ਅਰੁ ਚੰਦ੍ਰਮੁਖੀ ਮਿਲ ਕੈ ਬ੍ਰਿਖਭਾਨੁ ਸੁਤਾ ਗਾਵੈ।","roman":"Chandrabhgaa aru chandramukhee mil kai brikhbhaanu sutaa gaavai |","meaning_en":"","page":422},{"gurmukhi":"ਸੋਰਠਿ ਸਾਰੰਗ ਸੁਧ ਮਲਾਰ ਬਿਲਾਵਲ ਭੀਤਰ ਤਾਨ ਬਸਾਵੈ।","roman":"Sorthi saarang sudh malaar bilaaval bheetar taan basaavai |","meaning_en":"","page":422},{"gurmukhi":"ਰੀਝ ਰਹੀ ਬ੍ਰਿਜ ਹੂੰ ਕੀ ਤ੍ਰੀਯਾ ਸੋਊ ਰੀਝ ਰਹੈ ਧੁਨਿ ਜੋ ਸੁਨਿ ਪਾਵੈ।","roman":"Reejh rahee brij hoon kee treeyaa so'oo reejh rahai dhuni jo suni paavai |","meaning_en":"","page":422},{"gurmukhi":"ਸੋ ਸੁਨ ਕੈ ਇਨ ਪੈ ਹਿਤ ਕੈ ਬਨ ਤਿਆਗਿ ਮ੍ਰਿਗੀ ਮ੍ਰਿਗ ਅਉ ਚਲਿ ਆਵੈ। ੫੫੬।","roman":"So sun kai in pai hit kai ban tiaagi mrigee mrig au chali aavai | 556 |","meaning_en":"","page":422}]},{"type":"verse","number":[557],"number_text":"੫੫੭।","page":423,"lines":[{"gurmukhi":"ਤਿਨ ਸੇਂਧੁਰ ਮਾਗ ਦਈ ਸਿਰ ਪੈ ਰਸ ਸੋ ਤਿਨ ਕੋ ਅਤਿ ਹੀ ਮਨੁ ਭੀਨੋ।","roman":"Tin sendhur maag daee sir pai ras so tin ko ati hee manu bheeno |","meaning_en":"","page":423},{"gurmukhi":"ਬੇਸਰ ਆਡ ਸੁ ਕੰਠਸਿਰੀ ਅਰੁ ਮੋਤਿਸਿਰੀ ਹੂੰ ਕੋ ਸਾਜ ਨਵੀਨੋ।","roman":"Besar aad su kanthsiree aru motisiree hoon ko saaj naveeno |","meaning_en":"","page":423},{"gurmukhi":"ਭੂਖਨ ਅੰਗ ਸਭੈ ਸਜਿ ਸੁੰਦਰਿ ਆਖਨ ਭੀਤਰ ਕਾਜਰ ਦੀਨੋ।","roman":"Bhookhan ang sabhai saji sundri aakhan bheetar kaajar deeno |","meaning_en":"","page":423},{"gurmukhi":"ਤਾਹੀ ਸੁ ਤੇ ਕਬਿ ਸ੍ਯਾਮ ਕਹੈ ਭਗਵਾਨ ਕੋ ਚਿਤ ਚੁਰਾਇ ਕੈ ਲੀਨੋ। ੫੫੭।","roman":"Taahee su te kabi syaam kahai bhagvaan ko chit churaai kai leeno | 557 |","meaning_en":"","page":423}]},{"type":"verse","number":[558],"number_text":"੫੫੮।","page":423,"lines":[{"gurmukhi":"ਚੰਦ ਕੀ ਚਾਦਨੀ ਮੈ ਕਬਿ ਸ੍ਯਾਮ ਜਬੈ ਹਰਿ ਖੇਲਨਿ ਰਾਸ ਲਗਿਯੋ ਹੈ।","roman":"Chand kee chaadnee mai kabi syaam jabai hari khelni raas lagiyo hai |","meaning_en":"","page":423},{"gurmukhi":"ਰਾਧੇ ਕੋ ਆਨਨ ਸੁੰਦਰ ਪੇਖਿ ਕੈ ਚਾਦ ਸੋ ਤਾਹੀ ਕੇ ਬੀਚ ਪਗਿਯੋ ਹੈ।","roman":"Raadhe ko aanan sundar pekhi kai chaad so taahee ke beech pagiyo hai |","meaning_en":"","page":423},{"gurmukhi":"ਹਰਿ ਕੋ ਤਿਨ ਚਿਤ ਚੁਰਾਇ ਲੀਯੋ ਸੁ ਕਿਧੋ ਕਬਿ ਕੋ ਮਨ ਯੌ ਉਮਗਿਯੋ ਹੈ।","roman":"Hari ko tin chit churaai leeyo su kidho kabi ko man yau umgiyo hai |","meaning_en":"","page":423},{"gurmukhi":"ਨੈਨਨ ਕੋ ਰਸ ਦੇ ਭਿਲਵਾ ਬ੍ਰਿਖਭਾਨ ਠਗੀ ਭਗਵਾਨ ਠਗਿਯੋ ਹੈ। ੫੫੮।","roman":"Nainan ko ras de bhilvaa brikhbhaan thagee bhagvaan thagiyo hai | 558 |","meaning_en":"","page":423}]},{"type":"verse","number":[559],"number_text":"੫੫੯।","page":423,"lines":[{"gurmukhi":"ਜਿਹ ਕੋ ਪਿਖ ਕੈ ਮੁਖ ਮੈਨ ਲਜੈ ਜਿਹ ਕੋ ਦਿਖ ਕੈ ਮੁਖਿ ਚੰਦ੍ਰ ਲਜੈ।","roman":"Jih ko pikh kai mukh main lajai jih ko dikh kai mukhi chandr lajai |","meaning_en":"","page":423},{"gurmukhi":"ਕਬਿ ਸ੍ਯਾਮ ਕਹੇ ਸੋਊ ਖੇਲਤ ਹੈ ਸੰਗ ਕਾਨਰ ਕੇ ਸੁਭ ਸਾਜ ਸਜੈ।","roman":"Kabi syaam kahe so'oo khelat hai sang kaanar ke subh saaj sajai |","meaning_en":"","page":423},{"gurmukhi":"ਸੋਊ ਸੂਰਤਿਵੰਤ ਰਚੀ ਬ੍ਰਹਮਾ ਕਰ ਕੈ ਅਤਿ ਹੀ ਰੁਚਿ ਕੈ ਨ ਕਜੈ।","roman":"So'oo soortivant rachee brahmaa kar kai ati hee ruchi kai na kajai |","meaning_en":"","page":423},{"gurmukhi":"ਮਨਿ ਮਾਲ ਕੇ ਬੀਚ ਬਿਰਾਜਤ ਜਿਉ ਤਿਮ ਤ੍ਰਿਯਨ ਮੈ ਤ੍ਰਿਯ ਰਾਜ ਰਜੈ। ੫੫੯।","roman":"Mani maal ke beech biraajat jiu tim triyan mai triy raaj rajai | 559 |","meaning_en":"","page":423}]},{"type":"verse","number":[560],"number_text":"੫੬੦।","page":423,"lines":[{"gurmukhi":"ਗਾਇ ਕੈ ਗੀਤ ਭਲੀ ਬਿਧਿ ਸੁੰਦਰਿ ਰੀਝਿ ਬਜਾਵਤ ਭੀ ਫਿਰਿ ਤਾਰੀ।","roman":"Gaai kai geet bhalee bidhi sundri reejhi bajaavat bhee phiri taaree |","meaning_en":"","page":423},{"gurmukhi":"ਅੰਜਨ ਆਡ ਸੁਧਾਰ ਭਲੇ ਪਟ ਸਾਜਨ ਕੋ ਸਜ ਕੈ ਸੁ ਗੁਵਾਰੀ।","roman":"Anjan aad sudhaar bhale pat saajan ko saj kai su guvaaree |","meaning_en":"","page":423},{"gurmukhi":"ਤਾ ਛਬਿ ਕੀ ਅਤਿ ਹੀ ਸੁ ਪ੍ਰਭਾ ਕਬਿ ਨੈ ਮੁਖਿ ਤੇ ਇਹ ਭਾਤਿ ਉਚਾਰੀ।","roman":"Taa chhabi kee ati hee su prabhaa kabi nai mukhi te ih bhaati uchaaree |","meaning_en":"","page":423},{"gurmukhi":"ਮਾਨਹੁ ਕਾਨ੍ਹ ਹੀ ਕੇ ਰਸ ਤੇ ਇਹ ਫੂਲ ਰਹੀ ਤ੍ਰੀਯ ਆਨੰਦ ਬਾਰੀ। ੫੬੦।","roman":"Maanhu kaanh hee ke ras te ih phool rahee treey aanand baaree | 560 |","meaning_en":"","page":423}]},{"type":"verse","number":[561],"number_text":"੫੬੧।","page":423,"lines":[{"gurmukhi":"ਤਾ ਕੀ ਪ੍ਰਭਾ ਕਬਿ ਸ੍ਯਾਮ ਕਹੈ ਜੋਊ ਰਾਜਤ ਰਾਸ ਬਿਖੈ ਸਖੀਆ ਹੈ।","roman":"Taa kee prabhaa kabi syaam kahai jo'oo raajat raas bikhai sakheeaa hai |","meaning_en":"","page":423},{"gurmukhi":"ਜਾ ਮੁਖ ਉਪਮਾ ਚੰਦ੍ਰ ਛਟਾ ਸਮ ਛਾਜਤ ਕਉਲਨ ਸੀ ਅਖੀਆ ਹੈ।","roman":"Jaa mukh upmaa chandr chhataa sam chhaajat kaulan see akheeaa hai |","meaning_en":"","page":423},{"gurmukhi":"ਤਾ ਕੀ ਕਿਧੌ ਅਤਿ ਹੀ ਉਪਮਾ ਕਬਿ ਨੈ ਮਨ ਭੀਤਰ ਯੌ ਲਖੀਆ ਹੈ।","roman":"Taa kee kidhau ati hee upmaa kabi nai man bheetar yau lakheeaa hai |","meaning_en":"","page":423},{"gurmukhi":"ਲੋਗਨ ਕੇ ਮਨ ਕੀ ਹਰਤਾ ਸੁ ਮੁਨੀਨਨ ਕੇ ਮਨ ਕੀ ਚਖੀਆ ਹੈ। ੫੬੧।","roman":"Logan ke man kee hartaa su muneenan ke man kee chakheeaa hai | 561 |","meaning_en":"","page":423}]},{"type":"verse","number":[562],"number_text":"੫੬੨।","page":423,"lines":[{"gurmukhi":"ਰੂਪ ਸਚੀ ਇਕ ਚੰਦ੍ਰਪ੍ਰਭਾ ਇਕ ਮੈਨਕਲਾ ਇਕ ਮੈਨ ਕੀ ਮੂਰਤਿ।","roman":"Roop sachee ik chandraprabhaa ik mainaklaa ik main kee moorti |","meaning_en":"","page":423},{"gurmukhi":"ਬਿਜੁਛਟਾ ਇਕ ਦਾਰਿਮ ਦਾਤ ਬਰਾਬਰ ਜਾਹੀ ਕੀ ਹੈ ਨ ਕਛੂ ਰਤਿ।","roman":"Bijuchhtaa ik daarim daat baraabar jaahee kee hai na kachhoo rati |","meaning_en":"","page":423},{"gurmukhi":"ਦਾਮਿਨਿ ਅਉ ਮ੍ਰਿਗ ਕੀ ਮ੍ਰਿਗਨੀ ਸਰਮਾਇ ਜਿਸੈ ਪਿਖਿ ਹੋਤ ਹੈ ਚੂਰਤਿ।","roman":"Daamini au mrig kee mrignee sarmaai jisai pikhi hot hai choorti |","meaning_en":"","page":423},{"gurmukhi":"ਸੋਊ ਕਥਾ ਕਬਿ ਸ੍ਯਾਮ ਕਹੈ ਸਭ ਰੀਝ ਰਹੀ ਹਰਿ ਕੀ ਪਿਖਿ ਮੂਰਤਿ।੫੬੨।","roman":"So'oo kathaa kabi syaam kahai sabh reejh rahee hari kee pikhi moorti | 562 |","meaning_en":"","page":423}]},{"type":"verse","number":[563],"number_text":"੫੬੩।","page":424,"lines":[{"gurmukhi":"ਬ੍ਰਿਖਭਾਨੁ ਸੁਤਾ ਹਸਿ ਬਾਤ ਕਹੀ ਤਿਹ ਕੇ ਸੰਗ ਜੋ ਹਰਿ ਅਤਿ ਅਗਾਧੋ।","roman":"Brikhbhaanu sutaa hasi baat kahee tih ke sang jo hari ati agaadho |","meaning_en":"","page":424},{"gurmukhi":"ਸ੍ਯਾਮ ਕਹੈ ਬਤੀਯਾ ਹਰਿ ਕੋ ਸੰਗ ਐਸੇ ਕਹੀ ਪਟ ਕੋ ਤਜਿ ਰਾਧੋ।","roman":"Syaam kahai bateeyaa hari ko sang aise kahee pat ko taji raadho |","meaning_en":"","page":424},{"gurmukhi":"ਰਾਸ ਬਿਖੈ ਤੁਮ ਨਾਚਹੁ ਜੁ ਤਜ ਕੈ ਅਤਿ ਹੀ ਮਨ ਲਾਜ ਕੋ ਬਾਧੋ।","roman":"Raas bikhai tum naachhu ju taj kai ati hee man laaj ko baadho |","meaning_en":"","page":424},{"gurmukhi":"ਤਾ ਮੁਖ ਕੀ ਛਬਿ ਯੌ ਪ੍ਰਗਟੀ ਮਨੋ ਅਭ੍ਰਨ ਤੇ ਨਿਕਸਿਯੋ ਸਸਿ ਆਧੋ। ੫੬੩।","roman":"Taa mukh kee chhabi yau pragtee mano abhran te niksiyo sasi aadho | 563 |","meaning_en":"","page":424}]},{"type":"verse","number":[564],"number_text":"੫੬੪।","page":424,"lines":[{"gurmukhi":"ਜਿਨ ਕੇ ਸਿਰਿ ਸੇਂਧਰ ਮਾਗ ਬਿਰਾਜਤ ਰਾਜਤ ਹੈ ਬਿੰਦੂਆ ਜਿਨ ਪੀਲੇ।","roman":"Jin ke siri sendhar maag biraajat raajat hai bindooaa jin peele |","meaning_en":"","page":424},{"gurmukhi":"ਕੰਚਨ ਭਾ ਅਰੁ ਚੰਦ੍ਰ ਪ੍ਰਭਾ ਜਿਨ ਕੇ ਤਨ ਲੀਨ ਸਭੈ ਫੁਨਿ ਲੀਲੇ।","roman":"Kanchan bhaa aru chandr prabhaa jin ke tan leen sabhai phuni leele |","meaning_en":"","page":424},{"gurmukhi":"ਏਕ ਧਰੇ ਸਿਤ ਸੁੰਦਰ ਸਾਜ ਧਰੇ ਇਕ ਲਾਲ ਸਜੇ ਇਕ ਨੀਲੇ।","roman":"Ek dhare sit sundar saaj dhare ik laal saje ik neele |","meaning_en":"","page":424},{"gurmukhi":"ਸ੍ਯਾਮ ਕਹੇ ਸੋਊ ਰੀਝ ਰਹੈ ਪਿਖਿ ਕੈ ਦ੍ਰਿਗ ਕੰਜ ਸੇ ਕਾਨ੍ਹ ਰਸੀਲੇ। ੫੬੪।","roman":"Syaam kahe so'oo reejh rahai pikhi kai drig kanj se kaanh raseele | 564 |","meaning_en":"","page":424}]},{"type":"verse","number":[565],"number_text":"੫੬੫।","page":424,"lines":[{"gurmukhi":"ਸਭ ਗ੍ਵਾਰਨਿਯਾ ਤਹ ਖੇਲਤ ਹੈ ਸੁਭ ਅੰਗਨ ਸੁੰਦਰ ਸਾਜ ਕਈ।","roman":"Sabh gvaarniyaa tah khelat hai subh angan sundar saaj kaee |","meaning_en":"","page":424},{"gurmukhi":"ਸੋਊ ਰਾਸ ਬਿਖੈ ਤਹ ਖੇਲਤ ਹੈ ਹਰਿ ਸੋ ਮਨ ਮੈ ਅਤਿ ਹੀ ਉਮਈ।","roman":"So'oo raas bikhai tah khelat hai hari so man mai ati hee umaee |","meaning_en":"","page":424},{"gurmukhi":"ਕਬਿ ਸ੍ਯਾਮ ਕਹੈ ਤਿਨ ਕੀ ਉਪਮਾ ਜੁ ਹੁਤੀ ਤਹ ਗ੍ਵਾਰਿਨ ਰੂਪ ਰਈ।","roman":"Kabi syaam kahai tin kee upmaa ju hutee tah gvaarin roop raee |","meaning_en":"","page":424},{"gurmukhi":"ਮਨੋ ਸ੍ਯਾਮਹਿ ਕੋ ਤਨ ਗੋਰਿਨ ਪੇਖਿ ਕੈ ਸ੍ਯਾਮਹਿ ਸੀ ਸਭ ਹੋਇ ਗਈ। ੫੬੫।","roman":"Mano syaamhi ko tan gorin pekhi kai syaamhi see sabh hoi gaee | 565 |","meaning_en":"","page":424}]},{"type":"verse","number":[566],"number_text":"੫੬੬।","page":424,"lines":[{"gurmukhi":"ਕੇਲ ਕੈ ਰਾਸ ਮੈ ਰੀਝ ਰਹੀ ਕਬਿ ਸ੍ਯਾਮ ਕਹੈ ਮਨ ਆਨੰਦ ਕੈ ਕੈ।","roman":"Kel kai raas mai reejh rahee kabi syaam kahai man aanand kai kai |","meaning_en":"","page":424},{"gurmukhi":"ਚੰਦ੍ਰਮੁਖੀ ਤਨ ਕੰਚਨ ਭਾ ਹਸਿ ਸੁੰਦਰ ਬਾਤ ਕਹੀ ਉਮਗੈ ਕੈ।","roman":"Chandramukhee tan kanchan bhaa hasi sundar baat kahee umgai kai |","meaning_en":"","page":424},{"gurmukhi":"ਪੇਖਤ ਮੂਰਤਿ ਭੀ ਰਸ ਕੇ ਬਸਿ ਆਪਨ ਤੇ ਬਢ ਵਾਹਿ ਲਖੈ ਕੈ।","roman":"Pekhat moorti bhee ras ke basi aapan te badh vaahi lakhai kai |","meaning_en":"","page":424},{"gurmukhi":"ਜਿਉ ਮ੍ਰਿਗਨੀ ਮ੍ਰਿਗ ਪੇਖਤ ਤਿਉ ਬ੍ਰਿਖਭਾਨ ਸੁਤਾ ਭਗਵਾਨ ਚਿਤੈ ਕੈ। ੫੬੬।","roman":"Jiu mrignee mrig pekhat tiu brikhbhaan sutaa bhagvaan chitai kai | 566 |","meaning_en":"","page":424}]},{"type":"verse","number":[567],"number_text":"੫੬੭।","page":424,"lines":[{"gurmukhi":"ਬ੍ਰਿਖਭਾਨੁ ਸੁਤਾ ਪਿਖਿ ਰੀਝ ਰਹੀ ਅਤਿ ਸੁੰਦਰਿ ਸੁੰਦਰ ਕਾਨ੍ਹ ਕੋ ਆਨਨ।","roman":"Brikhbhaanu sutaa pikhi reejh rahee ati sundri sundar kaanh ko aanan |","meaning_en":"","page":424},{"gurmukhi":"ਰਾਜਤ ਤੀਰ ਨਦੀ ਜਿਹ ਕੇ ਸੁ ਬਿਰਾਜਤ ਫੂਲਨ ਕੇ ਜੁਤ ਕਾਨਨ।","roman":"Raajat teer nadee jih ke su biraajat phoolan ke jut kaanan |","meaning_en":"","page":424},{"gurmukhi":"ਨੈਨ ਕੈ ਭਾਵਨ ਸੋ ਹਰਿ ਕੋ ਮਨੁ ਮੋਹਿ ਲਇਓ ਰਸ ਕੀ ਅਭਿਮਾਨਨ।","roman":"Nain kai bhaavan so hari ko manu mohi laio ras kee abhimaanan |","meaning_en":"","page":424},{"gurmukhi":"ਜਿਉ ਰਸ ਲੋਗਨ ਭਉਹਨ ਲੈ ਧਨੁ ਨੈਨਨ ਸੈਨ ਸੁ ਕੰਜ ਸੇ ਬਾਨਨ। ੫੬੭।","roman":"Jiu ras logan bhauhan lai dhanu nainan sain su kanj se baanan | 567 |","meaning_en":"","page":424}]},{"type":"verse","number":[568],"number_text":"੫੬੮।","page":424,"lines":[{"gurmukhi":"ਕਾਨ੍ਹ ਸੋ ਪ੍ਰੀਤਿ ਬਢੀ ਤਿਨ ਕੀ ਨ ਘਟੀ ਕਛੁ ਹੈ ਬਢਹੀ ਸੁ ਭਈ ਹੈ।","roman":"Kaanh so preeti badhee tin kee na ghatee kachhu hai badhhee su bhaee hai |","meaning_en":"","page":424},{"gurmukhi":"ਡਾਰ ਕੈ ਲਾਜ ਸਭੈ ਮਨ ਕੀ ਹਰਿ ਕੈ ਸੰਗਿ ਖੇਲਨ ਕੋ ਉਮਈ ਹੈ।","roman":"Daar kai laaj sabhai man kee hari kai sangi khelan ko umaee hai |","meaning_en":"","page":424},{"gurmukhi":"ਸ੍ਯਾਮ ਕਹੈ ਤਿਨ ਕੀ ਉਪਮਾ ਅਤਿ ਹੀ ਜੁ ਤ੍ਰੀਆ ਅਤਿ ਰੂਪ ਰਈ ਹੈ।","roman":"Syaam kahai tin kee upmaa ati hee ju treeaa ati roop raee hai |","meaning_en":"","page":424},{"gurmukhi":"ਸੁੰਦਰ ਕਾਨ੍ਹ ਕੌ ਪਿਖਿ ਕੈ ਤਨਮੈ ਸਭ ਗ੍ਵਾਰਿਨ ਹੋਇ ਗਈ ਹੈ। ੫੬੮।","roman":"Sundar kaanh kau pikhi kai tanmai sabh gvaarin hoi gaee hai | 568 |","meaning_en":"","page":424}]},{"type":"verse","number":[569],"number_text":"੫੬੯।","page":425,"lines":[{"gurmukhi":"ਨੈਨ ਮ੍ਰਿਗੀ ਤਨ ਕੰਚਨ ਕੇ ਸਭ ਚੰਦ੍ਰਮੁਖੀ ਮਨੋ ਸਿੰਧੁ ਰਚੀ ਹੈ।","roman":"Nain mrigee tan kanchan ke sabh chandramukhee mano sindhu rachee hai |","meaning_en":"","page":425},{"gurmukhi":"ਜਾ ਸਮ ਰੂਪ ਨ ਰਾਜਤ ਹੈ ਰਤਿ ਰਾਵਨ ਤ੍ਰੀਯ ਨ ਅਉਰ ਸਚੀ ਹੈ।","roman":"Jaa sam roop na raajat hai rati raavan treey na aur sachee hai |","meaning_en":"","page":425},{"gurmukhi":"ਤਾ ਮਹਿ ਰੀਝ ਮਹਾ ਕਰਤਾਰ ਕ੍ਰਿਪਾ ਕਟਿ ਕੇਹਰ ਕੈ ਸੁ ਗਚੀ ਹੈ।","roman":"Taa mahi reejh mahaa kartaar kripaa kati kehar kai su gachee hai |","meaning_en":"","page":425},{"gurmukhi":"ਤਾ ਸੰਗ ਪ੍ਰੀਤਿ ਕਹੈ ਕਬਿ ਸ੍ਯਾਮ ਮਹਾ ਭਗਵਾਨਹਿ ਕੀ ਸੁ ਮਚੀ ਹੈ। ੫੬੯।","roman":"Taa sang preeti kahai kabi syaam mahaa bhagvaanhi kee su machee hai | 569 |","meaning_en":"","page":425}]},{"type":"verse","number":[570],"number_text":"੫੭੦।","page":425,"lines":[{"gurmukhi":"ਰਾਗਨ ਅਉਰ ਸੁਭਾਵਨ ਕੀ ਅਤਿ ਗਾਰਨ ਕੀ ਤਹ ਮਾਡ ਪਰੀ।","roman":"Raagan aur subhaavan kee ati gaaran kee tah maad paree |","meaning_en":"","page":425},{"gurmukhi":"ਬ੍ਰਿਜ ਗੀਤਨ ਕੀ ਅਤਿ ਹਾਸਨ ਸੋ ਜਹ ਖੇਲਤ ਭੀ ਕਈ ਏਕ ਘਰੀ।","roman":"Brij geetan kee ati haasan so jah khelat bhee kaee ek gharee |","meaning_en":"","page":425},{"gurmukhi":"ਗਾਵਤ ਏਕ ਬਜਾਵਤ ਤਾਲ ਕਹੈ ਇਕ ਨਾਚਹੁ ਆਇ ਅਰੀ।","roman":"Gaavat ek bajaavat taal kahai ik naachhu aai aree |","meaning_en":"","page":425},{"gurmukhi":"ਕਬਿ ਸ੍ਯਾਮ ਕਹੈ ਤਿਹ ਠਉਰ ਬਿਖੈ ਜਿਹ ਠਉਰ ਬਿਖੈ ਹਰਿ ਰਾਸ ਕਰੀ।੫੭੦।","roman":"Kabi syaam kahai tih thaur bikhai jih thaur bikhai hari raas karee | 570 |","meaning_en":"","page":425}]},{"type":"verse","number":[571],"number_text":"੫੭੧।","page":425,"lines":[{"gurmukhi":"ਜਦੁਰਾਇ ਕੋ ਆਇਸੁ ਪਾਇ ਤ੍ਰੀਯਾ ਸਭ ਖੇਲਤ ਰਾਸ ਬਿਖੈ ਬਿਧਿ ਆਛੀ।","roman":"Jaduraai ko aaisu paai treeyaa sabh khelat raas bikhai bidhi aachhee |","meaning_en":"","page":425},{"gurmukhi":"ਇੰਦ੍ਰ ਸਭਾ ਜਿਹ ਸਿੰਧੁ ਸੁਤਾ ਜਿਮ ਖੇਲਨ ਕੇ ਹਿਤ ਕਾਛਨ ਕਾਛੀ।","roman":"Indr sabhaa jih sindhu sutaa jim khelan ke hit kaachhan kaachhee |","meaning_en":"","page":425},{"gurmukhi":"ਕੈ ਇਹ ਕਿੰਨਰ ਕੀ ਦੁਹਿਤਾ ਕਿਧੌ ਨਾਗਨ ਕੀ ਕਿਧੌ ਹੈ ਇਹ ਤਾਛੀ।","roman":"Kai ih kinnar kee duhitaa kidhau naagan kee kidhau hai ih taachhee |","meaning_en":"","page":425},{"gurmukhi":"ਰਾਸ ਬਿਖੈ ਇਮ ਨਾਚਤ ਹੈ ਜਿਮ ਕੇਲ ਕਰੈ ਜਲ ਭੀਤਰ ਮਾਛੀ। ੫੭੧।","roman":"Raas bikhai im naachat hai jim kel karai jal bheetar maachhee | 571 |","meaning_en":"","page":425}]},{"type":"verse","number":[572],"number_text":"੫੭੨।","page":425,"lines":[{"gurmukhi":"ਜਿਹ ਕੇ ਮੁਖਿ ਦੇਖਿ ਛਟਾ ਸੁਭ ਸੁੰਦਰ ਮਧਿਮ ਲਾਗਤ ਜੋਤਿ ਸਸੀ ਹੈ।","roman":"Jih ke mukhi dekhi chhataa subh sundar madhim laagat joti sasee hai |","meaning_en":"","page":425},{"gurmukhi":"ਭਉਰਨ ਭਾਇ ਸੋ ਛਾਜਤ ਹੈ ਮਦਨੈ ਮਨੋ ਤਾਨ ਕਮਾਨ ਕਸੀ ਹੈ।","roman":"Bhauran bhaai so chhaajat hai madnai mano taan kamaan kasee hai |","meaning_en":"","page":425},{"gurmukhi":"ਤਾਹੀ ਕੇ ਆਨਨ ਸੁੰਦਰ ਤੇ ਸੁਰ ਰਾਗਹ ਕੀ ਸਭ ਭਾਤਿ ਬਸੀ ਹੈ।","roman":"Taahee ke aanan sundar te sur raagah kee sabh bhaati basee hai |","meaning_en":"","page":425},{"gurmukhi":"ਜਿਉ ਮਧੁ ਬੀਚ ਫਸੈ ਮਖੀਆ ਮਤਿ ਲੋਗਨ ਕੀ ਇਹ ਭਾਤਿ ਫਸੀ ਹੈ। ੫੭੨।","roman":"Jiu madhu beech phasai makheeaa mati logan kee ih bhaati phasee hai | 572 |","meaning_en":"","page":425}]},{"type":"verse","number":[573],"number_text":"੫੭੩।","page":425,"lines":[{"gurmukhi":"ਫਿਰਿ ਸੁੰਦਰ ਆਨਨ ਤੇ ਹਰਿ ਜੂ ਬਿਧਿ ਸੁੰਦਰ ਸੋ ਇਕ ਤਾਨ ਬਸਾਯੋ।","roman":"Phiri sundar aanan te hari joo bidhi sundar so ik taan basaayo |","meaning_en":"","page":425},{"gurmukhi":"ਸੋਰਠਿ ਸਾਰੰਗ ਸੁਧ ਮਲਾਰ ਬਿਲਾਵਲ ਕੀ ਸੁਰ ਭੀਤਰ ਗਾਯੋ।","roman":"Sorthi saarang sudh malaar bilaaval kee sur bheetar gaayo |","meaning_en":"","page":425},{"gurmukhi":"ਸੋ ਅਪਨੇ ਸੁਨ ਸ੍ਰਉਨਨ ਮੈ ਬ੍ਰਿਜ ਗਵਾਰਨੀਯਾ ਅਤਿ ਹੀ ਸੁਖੁ ਪਾਯੋ।","roman":"So apne sun sraunan mai brij gavaarneeyaa ati hee sukhu paayo |","meaning_en":"","page":425},{"gurmukhi":"ਮੋਹਿ ਰਹੇ ਬਨ ਕੇ ਖਗ ਅਉ ਮ੍ਰਿਗ ਰੀਝ ਰਹੈ ਜਿਨ ਹੂੰ ਸੁਨਿ ਪਾਯੋ। ੫੭੩।","roman":"Mohi rahe ban ke khag au mrig reejh rahai jin hoon suni paayo | 573 |","meaning_en":"","page":425}]},{"type":"verse","number":[574],"number_text":"੫੭੪।","page":425,"lines":[{"gurmukhi":"ਤਹ ਗਾਵਤ ਗੀਤ ਭਲੈ ਹਰਿ ਜੂ ਕਬਿ ਸ੍ਯਾਮ ਕਹੈ ਕਰਿ ਭਾਵ ਛਬੈ।","roman":"Tah gaavat geet bhalai hari joo kabi syaam kahai kari bhaav chhabai |","meaning_en":"","page":425},{"gurmukhi":"ਮੁਰਲੀ ਜੁਤ ਗ੍ਵਰਨਿ ਭੀਤਰ ਰਾਜਤ ਜ੍ਯੋ ਮ੍ਰਿਗਨੀ ਮ੍ਰਿਗ ਬੀਚ ਫਬੈ।","roman":"Murlee jut gvarni bheetar raajat jyo mrignee mrig beech phabai |","meaning_en":"","page":425},{"gurmukhi":"ਜਿਹ ਕੋ ਸਭ ਲੋਗਨ ਮੈ ਜਸੁ ਗਾਵਤ ਛੂਟਤ ਹੈ ਤਿਨ ਤੇ ਨ ਕਬੈ।","roman":"Jih ko sabh logan mai jasu gaavat chhootat hai tin te na kabai |","meaning_en":"","page":425},{"gurmukhi":"ਤਿਨਿ ਖੇਲਨ ਕੋ ਮਨ ਗੋਪਿਨ ਕੋ ਛਿਨ ਬੀਚ ਲੀਯੋ ਫੁਨਿ ਚੋਰ ਸਬੈ। ੫੭੪।","roman":"Tini khelan ko man gopin ko chhin beech leeyo phuni chor sabai | 574 |","meaning_en":"","page":425}]},{"type":"verse","number":[575],"number_text":"੫੭੫।","page":425,"lines":[{"gurmukhi":"ਕਬਿ ਸ੍ਯਾਮ ਕਹੈ ਉਮਾ ਤਿਹ ਕੀ ਜਿਨ ਜੋਬਨ ਰੂਪ ਅਨੂਪ ਗਹਿਯੋ ਹੈ।","roman":"Kabi syaam kahai umaa tih kee jin joban roop anoop gahiyo hai |","meaning_en":"","page":425},{"gurmukhi":"ਜਾ ਮੁਖ ਦੇਖਿ ਅਨੰਦ ਬਢਿਯੋ ਜਿਹ ਕੋ ਸੁਨਿ ਸ੍ਰਉਨਨ ਸੋਕ ਦਹਿਯੋ ਹੈ।","roman":"Jaa mukh dekhi anand badhiyo jih ko suni sraunan sok dahiyo hai |","meaning_en":"","page":425},{"gurmukhi":"ਆਨੰਦ ਕੈ ਬ੍ਰਿਖਭਾਨੁ ਸੁਤਾ ਹਰਿ ਕੇ ਸੰਗ ਜ੍ਵਾਬ ਸੁ ਐਸ ਕਹਿਯੋ ਹੈ।","roman":"Aanand kai brikhbhaanu sutaa hari ke sang jvaab su ais kahiyo hai |","meaning_en":"","page":426},{"gurmukhi":"ਤਾ ਕੇ ਸੁਨੇ ਤ੍ਰੀਯਾ ਮੋਹਿ ਰਹੀ ਸੁਨਿ ਕੈ ਜਿਹ ਕੋ ਹਰਿ ਰੀਝ ਰਹਿਯੋ ਹੈ। ੫੭੫।","roman":"Taa ke sune treeyaa mohi rahee suni kai jih ko hari reejh rahiyo hai | 575 |","meaning_en":"","page":426}]},{"type":"verse","number":[576],"number_text":"੫੭੬।","page":426,"lines":[{"gurmukhi":"ਗ੍ਵਾਰਨੀਯਾ ਮਿਲ ਕੈ ਸੰਗਿ ਕਾਨ੍ਹ ਕੈ ਖੇਲਤ ਹੈ ਕਬਿ ਸ੍ਯਾਮ ਸਬੈ।","roman":"Gvaarneeyaa mil kai sangi kaanh kai khelat hai kabi syaam sabai |","meaning_en":"","page":426},{"gurmukhi":"ਨ ਰਹੀ ਤਿਨ ਕੋ ਸੁਧਿ ਅੰਗਨ ਕੀ ਨਹਿ ਚੀਰਨ ਕੀ ਤਿਨ ਕੋ ਸੁ ਤਬੈ।","roman":"Na rahee tin ko sudhi angan kee nahi cheeran kee tin ko su tabai |","meaning_en":"","page":426},{"gurmukhi":"ਸੁ ਗਨੋ ਕਹ ਲਉ ਤਿਨ ਕੀ ਉਪਮਾ ਅਤਿ ਹੀ ਗਨ ਮੈ ਮਨਿ ਤਾ ਕੀ ਛਬੈ।","roman":"Su gano kah lau tin kee upmaa ati hee gan mai mani taa kee chhabai |","meaning_en":"","page":426},{"gurmukhi":"ਮਨ ਭਾਵਨ ਗਾਵਨ ਕੀ ਚਰਚਾ ਕਛੁ ਥੋਰੀਯੈ ਹੈ ਸੁਨਿ ਲੇਹੁ ਅਬੈ। ੫੭੬।","roman":"Man bhaavan gaavan kee charchaa kachhu thoreeyai hai suni lehu abai | 576 |","meaning_en":"","page":426}]},{"type":"heading","kind":"speaker","name":"ਕਾਨ੍ਹ ਜੂ ਬਾਚ","gurmukhi":"ਕਾਨ੍ਹ ਜੂ ਬਾਚ","roman":"Kaanh joo baach","meaning_en":"","page":426},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":426},{"type":"verse","number":[577],"number_text":"੫੭੭।","page":426,"lines":[{"gurmukhi":"ਬਾਤ ਕਹੀ ਤਿਨ ਸੋ ਕ੍ਰਿਸਨ ਅਤਿ ਹੀ ਬਿਹਸਿ ਕੈ ਚੀਤਿ।","roman":"Baat kahee tin so krisan ati hee bihsi kai cheeti |","meaning_en":"","page":426},{"gurmukhi":"ਮੀਤ ਰਸਹਿ ਕੀ ਰੀਤਿ ਸੋ ਕਹਿਯੋ ਸੁ ਗਾਵਹੁ ਗੀਤ। ੫੭੭।","roman":"Meet rashi kee reeti so kahiyo su gaavhu geet | 577 |","meaning_en":"","page":426}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":426},{"type":"verse","number":[578],"number_text":"੫੭੮।","page":426,"lines":[{"gurmukhi":"ਬਤੀਆ ਸੁਨਿ ਕੈ ਸਭ ਗ੍ਵਾਰਨੀਯਾ ਸੁਭ ਗਾਵਤ ਸੁੰਦਰ ਗੀਤ ਸਭੈ।","roman":"Bateeaa suni kai sabh gvaarneeyaa subh gaavat sundar geet sabhai |","meaning_en":"","page":426},{"gurmukhi":"ਸਿੰਧੁ ਸੁਤਾ ਰੁ ਘ੍ਰਿਤਾਚੀ ਤ੍ਰੀਯਾ ਇਨ ਸੀ ਨਹੀ ਨਾਚਤ ਇੰਦ੍ਰ ਸਭੈ।","roman":"Sindhu sutaa ru ghritaachee treeyaa in see nahee naachat indr sabhai |","meaning_en":"","page":426},{"gurmukhi":"ਦਿਵਯਾ ਇਨ ਕੇ ਸੰਗਿ ਖੇਲਤ ਹੈ ਗਜ ਕੋ ਕਬਿ ਸ੍ਯਾਮ ਸੁ ਦਾਨ ਅਭੈ।","roman":"Divyaa in ke sangi khelat hai gaj ko kabi syaam su daan abhai |","meaning_en":"","page":426},{"gurmukhi":"ਚੜ ਕੈ ਸੁ ਬਿਵਾਨਨ ਸੁੰਦਰ ਮੈ ਸੁਰ ਦੇਖਨ ਆਵਤ ਤਿਆਗ ਨਭੈ। ੫੭੮।","roman":"Char kai su bivaanan sundar mai sur dekhan aavat tiaag nabhai | 578 |","meaning_en":"","page":426}]},{"type":"verse","number":[579],"number_text":"੫੭੯।","page":426,"lines":[{"gurmukhi":"ਤ੍ਰੇਤਹਿ ਹੋ ਜਿਨਿ ਰਾਮ ਬਲੀ ਜਗ ਜੀਤਿ ਮਰਿਯੋ ਸੁ ਧਰਿਯੋ ਅਤਿ ਸੀਲਾ।","roman":"Trethi ho jini raam balee jag jeeti mariyo su dhariyo ati seelaa |","meaning_en":"","page":426},{"gurmukhi":"ਗਾਇ ਕੈ ਗੀਤ ਭਲੀ ਬਿਧਿ ਸੋ ਫੁਨਿ ਗ੍ਵਾਰਿਨ ਬੀਚ ਕਰੈ ਰਸ ਲੀਲਾ।","roman":"Gaai kai geet bhalee bidhi so phuni gvaarin beech karai ras leelaa |","meaning_en":"","page":426},{"gurmukhi":"ਰਾਜਤ ਹੈ ਜਿਹ ਕੋ ਤਨ ਸ੍ਯਾਮ ਬਿਰਾਜਤ ਊਪਰ ਕੋ ਪਟ ਪੀਲਾ।","roman":"Raajat hai jih ko tan syaam biraajat oopar ko pat peelaa |","meaning_en":"","page":426},{"gurmukhi":"ਖੇਲਤ ਸੋ ਸੰਗਿ ਗੋਪਿਨ ਕੈ ਕਬਿ ਸ੍ਯਾਮ ਕਹੈ ਜਦੁਰਾਇ ਹਠੀਲਾ। ੫੭੯।","roman":"Khelat so sangi gopin kai kabi syaam kahai jaduraai hatheelaa | 579 |","meaning_en":"","page":426}]},{"type":"verse","number":[580],"number_text":"੫੮੦।","page":426,"lines":[{"gurmukhi":"ਬੋਲਤ ਹੈ ਜਹ ਕੋਕਿਲਕਾ ਅਰੁ ਸੋਰ ਕਰੈ ਚਹੂੰ ਓਰ ਰਟਾਸੀ।","roman":"Bolat hai jah kokilkaa aru sor karai chahoon or rataasee |","meaning_en":"","page":426},{"gurmukhi":"ਸ੍ਯਾਮ ਕਹੈ ਤਿਹ ਸ੍ਯਾਮ ਕੀ ਦੇਹ ਰਜੈ ਅਤਿ ਸੁੰਦਰ ਮੈਨ ਘਟਾ ਸੀ।","roman":"Syaam kahai tih syaam kee deh rajai ati sundar main ghataa see |","meaning_en":"","page":426},{"gurmukhi":"ਤਾ ਪਿਖਿ ਕੈ ਮਨ ਗ੍ਵਾਰਿਨ ਤੇ ਉਪਜੀ ਅਤਿ ਹੀ ਮਨੋ ਘੋਰ ਘਟਾ ਸੀ।","roman":"Taa pikhi kai man gvaarin te upjee ati hee mano ghor ghataa see |","meaning_en":"","page":426},{"gurmukhi":"ਤਾ ਮਹਿ ਯੌ ਬ੍ਰਿਖਭਾਨ ਸੁਤਾ ਦਮਕੈ ਮਨੋ ਸੁੰਦਰ ਬਿਜੁ ਛਟਾ ਸੀ। ੫੮੦।","roman":"Taa mahi yau brikhbhaan sutaa damkai mano sundar biju chhataa see | 580 |","meaning_en":"","page":426}]},{"type":"verse","number":[581],"number_text":"੫੮੧।","page":426,"lines":[{"gurmukhi":"ਅੰਜਨ ਹੈ ਜਿਹ ਆਖਨ ਮੈ ਅਰੁ ਬੇਸਰ ਕੋ ਜਿਹ ਭਾਵ ਨਵੀਨੋ।","roman":"Anjan hai jih aakhan mai aru besar ko jih bhaav naveeno |","meaning_en":"","page":426},{"gurmukhi":"ਜਾ ਮੁਖ ਕੀ ਸਮ ਚੰਦ ਪ੍ਰਭਾ ਜਸੁ ਤਾ ਛਬਿ ਕੋ ਕਬਿ ਨੇ ਲਖਿ ਲੀਨੋ।","roman":"Jaa mukh kee sam chand prabhaa jasu taa chhabi ko kabi ne lakhi leeno |","meaning_en":"","page":426},{"gurmukhi":"ਸਾਜ ਸਭੈ ਸਜ ਕੈ ਸੁਭ ਸੁੰਦਰ ਭਾਲ ਬਿਖੈ ਬਿੰਦੂਆ ਇਕ ਦੀਨੋ।","roman":"Saaj sabhai saj kai subh sundar bhaal bikhai bindooaa ik deeno |","meaning_en":"","page":427},{"gurmukhi":"ਦੇਖਤ ਹੀ ਹਰਿ ਰੀਝ ਰਹੇ ਮਨ ਕੋ ਸਬ ਸੋਕ ਬਿਦਾ ਕਰ ਦੀਨੋ। ੫੮੧।","roman":"Dekhat hee hari reejh rahe man ko sab sok bidaa kar deeno | 581 |","meaning_en":"","page":427}]},{"type":"verse","number":[582],"number_text":"੫੮੨।","page":427,"lines":[{"gurmukhi":"ਬ੍ਰਿਖਭਾਨੁ ਸੁਤਾ ਸੰਗ ਖੇਲਨ ਕੀ ਹਸਿ ਕੈ ਹਰਿ ਸੁੰਦਰ ਬਾਤ ਕਹੈ।","roman":"Brikhbhaanu sutaa sang khelan kee hasi kai hari sundar baat kahai |","meaning_en":"","page":427},{"gurmukhi":"ਸੁਨਏ ਜਿਹ ਕੇ ਮਨਿ ਆਨੰਦ ਬਾਢਤ ਜਾ ਸੁਨ ਕੈ ਸਭ ਸ਼ੋਕ ਦਹੈ।","roman":"Sunae jih ke mani aanand baadhat jaa sun kai sabh shok dahai |","meaning_en":"","page":427},{"gurmukhi":"ਤਿਹ ਕਉਤੁਕ ਕੌ ਮਨ ਗੋਪਿਨ ਕੋ ਕਬਿ ਸਯਾਮ ਕਹੈ ਦਿਖਬੋ ਈ ਚਹੈ।","roman":"Tih kautuk kau man gopin ko kabi sayaam kahai dikhbo ee chahai |","meaning_en":"","page":427},{"gurmukhi":"ਨਭਿ ਮੈ ਪਿਖਿ ਕੈ ਸੁਰ ਗੰਧ੍ਰਬ ਜਾਇ ਚਲਿਯੋ ਨਹਿ ਜਾਇ ਸੁ ਰੀਝ ਰਹੈ। ੫੮੨।","roman":"Nabhi mai pikhi kai sur gandhrab jaai chaliyo nahi jaai su reejh rahai | 582 |","meaning_en":"","page":427}]},{"type":"verse","number":[583],"number_text":"੫੮੩।","page":427,"lines":[{"gurmukhi":"ਕਬਿ ਸ੍ਯਾਮ ਕਹੈ ਤਿਹ ਕੀ ਉਪਮਾ ਜਿਹ ਕੇ ਫੁਨਿ ਉਪਰ ਪੀਤ ਪਿਛਉਰੀ।","roman":"Kabi syaam kahai tih kee upmaa jih ke phuni upar peet pichhauree |","meaning_en":"","page":427},{"gurmukhi":"ਤਾਹੀ ਕੇ ਆਵਤ ਹੈ ਚਲਿ ਕੈ ਢਿਗ ਸੁੰਦਰ ਗਾਵਤ ਸਾਰੰਗ ਗਉਰੀ।","roman":"Taahee ke aavat hai chali kai dhig sundar gaavat saarang gauree |","meaning_en":"","page":427},{"gurmukhi":"ਸਾਵਲੀਆ ਹਰਿ ਕੈ ਢਿਗ ਆਇ ਰਹੀ ਅਤਿ ਰੀਝ ਇਕਾਵਤ ਦਉਰੀ।","roman":"Saavleeaa hari kai dhig aai rahee ati reejh ikaavat dauree |","meaning_en":"","page":427},{"gurmukhi":"ਇਉ ਉਪਮਾ ਉਪਜੀ ਲਖਿ ਫੂਲ ਰਹੀ ਲਪਟਾਇ ਮਨੋ ਤ੍ਰੀਯ ਭਉਰੀ। ੫੮੩।","roman":"Iu upmaa upjee lakhi phool rahee laptaai mano treey bhauree | 583 |","meaning_en":"","page":427}]},{"type":"verse","number":[584],"number_text":"੫੮੪।","page":427,"lines":[{"gurmukhi":"ਸ੍ਯਾਮ ਕਹੈ ਤਿਹ ਕੀ ਉਪਮਾ ਜੋਊ ਦੈਤਨ ਕੋ ਰਿਪੁ ਬੀਰ ਜਸੀ ਹੈ।","roman":"Syaam kahai tih kee upmaa jo'oo daitan ko ripu beer jasee hai |","meaning_en":"","page":427},{"gurmukhi":"ਜੇ ਤਪ ਬੀਚ ਬਡੋ ਤਪੀਆ ਰਸ ਬਾਤਨ ਮੈ ਅਤਿ ਹੀ ਜੁ ਰਸੀ ਹੈ।","roman":"Je tap beech bado tapeeaa ras baatan mai ati hee ju rasee hai |","meaning_en":"","page":427},{"gurmukhi":"ਜਾਹੀ ਕੋ ਕੰਠ ਕਪੋਤ ਸੋ ਹੈ ਜਿਹ ਭਾ ਮੁਖ ਕੀ ਸਮ ਜੋਤਿ ਸਸੀ ਹੈ।","roman":"Jaahee ko kanth kapot so hai jih bhaa mukh kee sam joti sasee hai |","meaning_en":"","page":427},{"gurmukhi":"ਤਾ ਮ੍ਰਿਗਨੀ ਤ੍ਰੀਯ ਮਾਰਨ ਕੋ ਹਰਿ ਭਉਹਨਿ ਕੀ ਅਰੁ ਪੰਚ ਕਸੀ ਹੈ। ੫੮੪।","roman":"Taa mrignee treey maaran ko hari bhauhni kee aru panch kasee hai | 584 |","meaning_en":"","page":427}]},{"type":"verse","number":[585],"number_text":"੫੮੫।","page":427,"lines":[{"gurmukhi":"ਫਿਰਿ ਕੈ ਹਰਿ ਗ੍ਵਾਰਿਨ ਕੇ ਸੰਗ ਹੋ ਫੁਨਿ ਗਾਵਤ ਸਾਰੰਗ ਰਾਮਕਲੀ ਹੈ।","roman":"Phiri kai hari gvaarin ke sang ho phuni gaavat saarang raamaklee hai |","meaning_en":"","page":427},{"gurmukhi":"ਗਾਵਤ ਹੈ ਮਨ ਆਨੰਦ ਕੈ ਬ੍ਰਿਖਭਾਨੁ ਸੁਤਾ ਸੰਗਿ ਜੂਥ ਅਲੀ ਹੈ।","roman":"Gaavat hai man aanand kai brikhbhaanu sutaa sangi jooth alee hai |","meaning_en":"","page":427},{"gurmukhi":"ਤਾ ਸੰਗ ਡੋਲਤ ਹੈ ਭਗਵਾਨ ਜੋਊ ਅਤਿ ਸੁੰਦਰਿ ਰਾਧੇ ਭਲੀ ਹੈ।","roman":"Taa sang dolat hai bhagvaan jo'oo ati sundri raadhe bhalee hai |","meaning_en":"","page":427},{"gurmukhi":"ਰਾਜਤ ਹੈ ਜਿਹ ਕੋ ਸਸਿ ਸੋ ਮੁਖ ਛਾਜਤ ਭਾ ਦ੍ਰਿਗ ਕੰਜ ਕਲੀ ਹੈ। ੫੮੫।","roman":"Raajat hai jih ko sasi so mukh chhaajat bhaa drig kanj kalee hai | 585 |","meaning_en":"","page":427}]},{"type":"verse","number":[586],"number_text":"੫੮੬।","page":427,"lines":[{"gurmukhi":"ਬ੍ਰਿਖਭਾਨੁ ਸੁਤਾ ਸੰਗ ਬਾਤ ਕਹੀ ਕਬਿ ਸ੍ਯਾਮ ਕਹੈ ਹਰਿ ਜੂ ਰਸਵਾਰੇ।","roman":"Brikhbhaanu sutaa sang baat kahee kabi syaam kahai hari joo rasvaare |","meaning_en":"","page":427},{"gurmukhi":"ਜਾ ਮੁਖ ਕੀ ਸਮ ਚੰਦ ਪ੍ਰਭਾ ਜਿਹ ਕੇ ਮ੍ਰਿਗ ਸੇ ਦ੍ਰਿਗ ਸੁੰਦਰ ਕਾਰੇ।","roman":"Jaa mukh kee sam chand prabhaa jih ke mrig se drig sundar kaare |","meaning_en":"","page":427},{"gurmukhi":"ਕੇਹਰਿ ਸੀ ਜਿਹ ਕੀ ਕਟਿ ਹੈ ਤਿਨ ਹੂੰ ਬਚਨਾ ਇਹ ਭਾਤਿ ਉਚਾਰੇ।","roman":"Kehri see jih kee kati hai tin hoon bachnaa ih bhaati uchaare |","meaning_en":"","page":427},{"gurmukhi":"ਸੋ ਸੁਨਿ ਕੈ ਸਭ ਗ੍ਵਾਰਨੀਯਾ ਮਨ ਕੇ ਸਭਿ ਸੋਕ ਬਿਦਾ ਕਰਿ ਡਾਰੇ। ੫੮੬।","roman":"So suni kai sabh gvaarneeyaa man ke sabhi sok bidaa kari daare | 586 |","meaning_en":"","page":427}]},{"type":"verse","number":[587],"number_text":"੫੮੭।","page":427,"lines":[{"gurmukhi":"ਹਸਿ ਕੈ ਤਿਹ ਬਾਤ ਕਹੀ ਰਸ ਕੀ ਸੁ ਪ੍ਰਭਾ ਜਿਨ ਹੂੰ ਬੜਵਾਨਲ ਲੀਲੀ।","roman":"Hasi kai tih baat kahee ras kee su prabhaa jin hoon barvaanal leelee |","meaning_en":"","page":427},{"gurmukhi":"ਜੋ ਜਗ ਬੀਚ ਰਹਿਯੋ ਰਵਿ ਕੈ ਨਰ ਕੈ ਤਰੁ ਕੈ ਗਜ ਅਉਰ ਪਪੀਲੀ।","roman":"Jo jag beech rahiyo ravi kai nar kai taru kai gaj aur papeelee |","meaning_en":"","page":427},{"gurmukhi":"ਮੁਖ ਤੇ ਤਿਨ ਸੁੰਦਰ ਬਾਤ ਕਹੀ ਸੰਗ ਗ੍ਵਾਰਨਿ ਕੇ ਅਤਿ ਸਹੀ ਸੁ ਰਸੀਲੀ।","roman":"Mukh te tin sundar baat kahee sang gvaarni ke ati sahee su raseelee |","meaning_en":"","page":427},{"gurmukhi":"ਤਾ ਸੁਨਿ ਕੈ ਸਭ ਰੀਝ ਰਹੀ ਸੁਨਿ ਰੀਝ ਰਹੀ ਬ੍ਰਿਖਭਾਨੁ ਛਬੀਲੀ। ੫੮੭।","roman":"Taa suni kai sabh reejh rahee suni reejh rahee brikhbhaanu chhabeelee | 587 |","meaning_en":"","page":427}]},{"type":"verse","number":[588],"number_text":"੫੮੮।","page":428,"lines":[{"gurmukhi":"ਗ੍ਵਾਰਨੀਯਾ ਸੁਨਿ ਸ੍ਰਉਨਨ ਮੈ ਬਤੀਆ ਹਰਿ ਕੀ ਅਤਿ ਸਹੀ ਮਨ ਭੀਨੋ।","roman":"Gvaarneeyaa suni sraunan mai bateeaa hari kee ati sahee man bheeno |","meaning_en":"","page":428},{"gurmukhi":"ਕੰਠਸਿਰੀ ਅਰੁ ਬੇਸਰਿ ਮਾਗ ਧਰੈ ਜੋਊ ਸੁੰਦਰ ਸਾਜ ਨਵੀਨੋ।","roman":"Kanthsiree aru besri maag dharai jo'oo sundar saaj naveeno |","meaning_en":"","page":428},{"gurmukhi":"ਜੋ ਅਵਤਾਰਨ ਤੇ ਅਵਤਾਰ ਕਹੈ ਕਬਿ ਸ੍ਯਾਮ ਜੁ ਹੈ ਸੁ ਨਗੀਨੋ।","roman":"Jo avtaaran te avtaar kahai kabi syaam ju hai su nageeno |","meaning_en":"","page":428},{"gurmukhi":"ਤਾਹਿ ਕਿਧੌ ਅਤਿ ਹੀ ਛਲ ਕੈ ਸੁ ਚੁਰਾਇ ਮਨੋ ਮਨ ਗੋਪਿਨ ਲੀਨੋ। ੫੮੮।","roman":"Taahi kidhau ati hee chhal kai su churaai mano man gopin leeno | 588 |","meaning_en":"","page":428}]},{"type":"verse","number":[589],"number_text":"੫੮੯।","page":428,"lines":[{"gurmukhi":"ਕਾਨਰ ਸੋ ਬ੍ਰਿਖਭਾਨੁ ਸੁਤਾ ਹਸਿ ਬਾਤ ਕਹੀ ਸੰਗ ਸੁੰਦਰ ਐਸੇ।","roman":"Kaanar so brikhbhaanu sutaa hasi baat kahee sang sundar aise |","meaning_en":"","page":428},{"gurmukhi":"ਨੈਨ ਨਚਾਇ ਮਹਾ ਮ੍ਰਿਗ ਸੇ ਕਬਿ ਸ੍ਯਾਮ ਕਹੈ ਅਤਿ ਹੀ ਸੁ ਰੁਚੈ ਸੇ।","roman":"Nain nachaai mahaa mrig se kabi syaam kahai ati hee su ruchai se |","meaning_en":"","page":428},{"gurmukhi":"ਤਾ ਛਬਿ ਕੀ ਅਤਿ ਹੀ ਉਪਮਾ ਉਪਜੀ ਕਬਿ ਕੇ ਮਨ ਤੇ ਉਮਗੈ ਸੇ।","roman":"Taa chhabi kee ati hee upmaa upjee kabi ke man te umgai se |","meaning_en":"","page":428},{"gurmukhi":"ਮਾਨਹੁ ਆਨੰਦ ਕੈ ਅਤਿ ਹੀ ਮਨੋ ਕੇਲ ਕਰੈ ਪਤਿ ਸੋ ਰਤਿ ਜੈਸੇ। ੫੮੯।","roman":"Maanhu aanand kai ati hee mano kel karai pati so rati jaise | 589 |","meaning_en":"","page":428}]},{"type":"verse","number":[590],"number_text":"੫੯੦।","page":428,"lines":[{"gurmukhi":"ਗ੍ਵਾਰਿਨ ਕੋ ਹਰਿ ਕੰਚਨ ਸੇ ਤਨ ਮੈ ਮਨਿ ਕੀ ਮਨ ਤੁਲਿ ਖੁਭਾ ਹੈ।","roman":"Gvaarin ko hari kanchan se tan mai mani kee man tuli khubhaa hai |","meaning_en":"","page":428},{"gurmukhi":"ਖੇਲਤ ਹੈ ਹਰਿ ਕੇ ਸੰਗ ਸੋ ਜਿਨ ਕੀ ਬਰਨੀ ਨਹੀ ਜਾਤ ਸੁਭਾ ਹੈ।","roman":"Khelat hai hari ke sang so jin kee barnee nahee jaat subhaa hai |","meaning_en":"","page":428},{"gurmukhi":"ਖੇਲਨ ਕੋ ਭਗਵਾਨ ਰਚੀ ਰਸ ਕੇ ਹਿਤ ਚਿਤ੍ਰ ਬਚਿਤ੍ਰ ਸਭਾ ਹੈ।","roman":"Khelan ko bhagvaan rachee ras ke hit chitr bachitr sabhaa hai |","meaning_en":"","page":428},{"gurmukhi":"ਯੌ ਉਪਜੀ ਉਪਮਾ ਤਿਨ ਮੈ ਬ੍ਰਿਖਭਾਨੁ ਸੁਤਾ ਮਨੋ ਚੰਦ੍ਰ ਪ੍ਰਭਾ ਹੈ। ੫੯੦।","roman":"Yau upjee upmaa tin mai brikhbhaanu sutaa mano chandr prabhaa hai | 590 |","meaning_en":"","page":428}]},{"type":"verse","number":[591],"number_text":"੫੯੧।","page":428,"lines":[{"gurmukhi":"ਬ੍ਰਿਖਭਾਨੁ ਸੁਤਾ ਹਰਿ ਆਇਸ ਮਾਨ ਕੈ ਖੇਲਤ ਭੀ ਅਤਿ ਹੀ ਸ੍ਰਮ ਕੈ।","roman":"Brikhbhaanu sutaa hari aais maan kai khelat bhee ati hee sram kai |","meaning_en":"","page":428},{"gurmukhi":"ਗਹਿ ਹਾਥ ਸੋ ਹਾਥ ਤ੍ਰੀਯਾ ਸਭ ਸੁੰਦਰ ਨਾਚਤ ਰਾਸ ਬਿਖੈ ਭ੍ਰਮ ਕੈ।","roman":"Gahi haath so haath treeyaa sabh sundar naachat raas bikhai bhram kai |","meaning_en":"","page":428},{"gurmukhi":"ਤਿਹ ਕੀ ਸੁ ਕਥਾ ਮਨ ਬੀਚ ਬਿਚਾਰਿ ਕਰੈ ਕਬਿ ਸ੍ਯਾਮ ਕਹੀ ਕ੍ਰਮ ਕੈ।","roman":"Tih kee su kathaa man beech bichaari karai kabi syaam kahee kram kai |","meaning_en":"","page":428},{"gurmukhi":"ਮਨੋ ਗੋਪਿਨ ਕੇ ਘਨ ਸੁੰਦਰ ਮੈ ਬ੍ਰਿਜ ਭਾਮਿਨਿ ਦਾਮਿਨਿ ਜਿਉ ਦਮਕੈ। ੫੯੧।","roman":"Mano gopin ke ghan sundar mai brij bhaamini daamini jiu damkai | 591 |","meaning_en":"","page":428}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":428},{"type":"verse","number":[592],"number_text":"੫੯੨।","page":428,"lines":[{"gurmukhi":"ਪਿਖਿ ਕੈ ਨਾਚਤ ਰਾਧਿਕਾ ਕ੍ਰਿਸਨ ਮਨੈ ਸੁਖ ਪਾਇ।","roman":"Pikhi kai naachat raadhikaa krisan manai sukh paai |","meaning_en":"","page":428},{"gurmukhi":"ਅਤਿ ਹੁਲਾਸ ਜੁਤ ਪ੍ਰੇਮ ਛਕਿ ਮੁਰਲੀ ਉਠਿਯੋ ਬਜਾਇ। ੫੯੨।","roman":"Ati hulaas jut prem chhaki murlee uthiyo bajaai | 592 |","meaning_en":"","page":428}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":428},{"type":"verse","number":[593],"number_text":"੫੯੩।","page":428,"lines":[{"gurmukhi":"ਨਟ ਨਾਇਕ ਸੁੱਧ ਮਲਾਰ ਬਿਲਾਵਲ ਗ੍ਵਾਰਿਨ ਬੀਚ ਧਮਾਰਨ ਗਾਵੈ।","roman":"Nat naaik suddh malaar bilaaval gvaarin beech dhamaaran gaavai |","meaning_en":"","page":428},{"gurmukhi":"ਸੋਰਠਿ ਸਾਰੰਗ ਰਾਮਕਲੀ ਸੁ ਬਿਭਾਸ ਭਲੇ ਹਿਤ ਸਾਥ ਬਸਾਵੈ।","roman":"Sorthi saarang raamaklee su bibhaas bhale hit saath basaavai |","meaning_en":"","page":428},{"gurmukhi":"ਗਾਵਹੁ ਹ੍ਵੈ ਮ੍ਰਿਗਨੀ ਤ੍ਰੀਯ ਕੋ ਸੁ ਬੁਲਾਵਤ ਹੈ ਉਪਮਾ ਜੀਯ ਭਾਵੈ।","roman":"Gaavhu hvai mrignee treey ko su bulaavat hai upmaa jeey bhaavai |","meaning_en":"","page":428},{"gurmukhi":"ਮਾਨਹੁ ਭਉਹਨ ਕੋ ਕਸਿ ਕੈ ਧਨੁ ਨੈਨਨ ਕੇ ਮਨੋ ਤੀਰ ਚਲਾਵੈ। ੫੯੩।","roman":"Maanhu bhauhan ko kasi kai dhanu nainan ke mano teer chalaavai | 593 |","meaning_en":"","page":428}]},{"type":"verse","number":[594],"number_text":"੫੯੪।","page":428,"lines":[{"gurmukhi":"ਮੇਘ ਮਲਾਰ ਅਉ ਦੇਵ ਗੰਧਾਰਿ ਭਲੇ ਗਵਰੀ ਕਰਿ ਕੈ ਹਿਤ ਗਾਵੈ।","roman":"Megh malaar au dev gandhaari bhale gavree kari kai hit gaavai |","meaning_en":"","page":428},{"gurmukhi":"ਜੈਤਸਿਰੀ ਅਰੁ ਮਾਲਸਿਰੀ ਨਟ ਨਾਇਕ ਸੁੰਦਰ ਭਾਤਿ ਬਸਾਵੈ।","roman":"Jaitsiree aru maalsiree nat naaik sundar bhaati basaavai |","meaning_en":"","page":428},{"gurmukhi":"ਰੀਝ ਰਹੀ ਬ੍ਰਿਜ ਕੀ ਸਭ ਗ੍ਵਾਰਿਨ ਰੀਝ ਰਹੈ ਸੁਰ ਜੋ ਸੁਨ ਪਾਵੈ।","roman":"Reejh rahee brij kee sabh gvaarin reejh rahai sur jo sun paavai |","meaning_en":"","page":428},{"gurmukhi":"ਅਉਰ ਕੀ ਬਾਤ ਕਹਾ ਕਹੀਯੈ ਤਜਿ ਇੰਦ੍ਰ ਸਭਾ ਸਭ ਆਸਨ ਆਵੈ। ੫੯੪।","roman":"Aur kee baat kahaa kaheeyai taji indr sabhaa sabh aasan aavai | 594 |","meaning_en":"","page":428}]},{"type":"verse","number":[595],"number_text":"੫੯੫।","page":429,"lines":[{"gurmukhi":"ਖੇਲਤ ਰਾਸ ਮੈ ਸ੍ਯਾਮ ਕਹੈ ਅਤਿ ਹੀ ਰਸ ਸੰਗ ਤ੍ਰੀਯਾ ਮਿਲਿ ਤੀਨੋ।","roman":"Khelat raas mai syaam kahai ati hee ras sang treeyaa mili teeno |","meaning_en":"","page":429},{"gurmukhi":"ਚੰਦ੍ਰਭਗਾ ਅਰੁ ਚੰਦ੍ਰਮੁਖੀ ਬ੍ਰਿਖਭਾਨ ਸੁਤਾ ਸਜਿ ਸਾਜ ਨਵੀਨੋ।","roman":"Chandrabhgaa aru chandramukhee brikhbhaan sutaa saji saaj naveeno |","meaning_en":"","page":429},{"gurmukhi":"ਅੰਜਨ ਆਖਨ ਦੈ ਬਿੰਦੂਆ ਇਕ ਭਾਲ ਮੈ ਸੇਂਧੁਰ ਸੁੰਦਰ ਦੀਨੋ।","roman":"Anjan aakhan dai bindooaa ik bhaal mai sendhur sundar deeno |","meaning_en":"","page":429},{"gurmukhi":"ਯੌ ਉਜਪੀ ਉਪਮਾ ਤ੍ਰੀਯ ਕੈ ਸੁਭ ਭਾਗ ਪ੍ਰਕਾਸ਼ ਅਬੈ ਮਨੋ ਕੀਨੋ। ੫੯੫।","roman":"Yau ujpee upmaa treey kai subh bhaag prakaash abai mano keeno | 595 |","meaning_en":"","page":429}]},{"type":"verse","number":[596],"number_text":"੫੯੬।","page":429,"lines":[{"gurmukhi":"ਖੇਲਤ ਕਾਨ੍ਹ ਸੋ ਚੰਦ੍ਰਭਗਾ ਕਬਿ ਸ੍ਯਾਮ ਕਹੈ ਰਸ ਜੋ ਉਮਹਿਯੋ ਹੈ।","roman":"Khelat kaanh so chandrabhgaa kabi syaam kahai ras jo umhiyo hai |","meaning_en":"","page":429},{"gurmukhi":"ਪ੍ਰੀਤਿ ਕਰੀ ਅਤਿ ਹੀ ਤਿਹ ਸੋ ਬਹੁ ਲੋਗਨ ਕੋ ਉਪਹਾਸ ਸਹਿਯੋ ਹੈ।","roman":"Preeti karee ati hee tih so bahu logan ko uphaas sahiyo hai |","meaning_en":"","page":429},{"gurmukhi":"ਮੋਤਿਨ ਮਾਲ ਢਰੀ ਗਰ ਤੇ ਕਬਿ ਨੇ ਤਿਹ ਕੋ ਜਸੁ ਐਸੇ ਕਹਿਯੋ ਹੈ।","roman":"Motin maal dharee gar te kabi ne tih ko jasu aise kahiyo hai |","meaning_en":"","page":429},{"gurmukhi":"ਆਨਨ ਚੰਦ੍ਰ ਮਨੋ ਪ੍ਰਗਟੇ ਛਪਿ ਕੈ ਅੰਧਿਆਰੁ ਪਤਾਰਿ ਗਯੋ ਹੈ। ੫੯੬।","roman":"Aanan chandr mano pragte chhapi kai andhiaaru pataari gayo hai | 596 |","meaning_en":"","page":429}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":429},{"type":"verse","number":[597],"number_text":"੫੯੭।","page":429,"lines":[{"gurmukhi":"ਗ੍ਵਾਰਿਨ ਰੂਪ ਨਿਹਾਰ ਕੈ ਇਉ ਉਪਜਯੋ ਜੀਯ ਭਾਵ।","roman":"Gvaarin roop nihaar kai iu upajyo jeey bhaav |","meaning_en":"","page":429},{"gurmukhi":"ਰਾਜਤ ਜ੍ਯੋ ਮਹਿ ਚਾਦਨੀ ਕੰਜਨ ਸਹਿਤ ਤਲਾਵ। ੫੯੭।","roman":"Raajat jyo mahi chaadnee kanjan sahit talaav | 597 |","meaning_en":"","page":429}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":429},{"type":"verse","number":[598],"number_text":"੫੯੮।","page":429,"lines":[{"gurmukhi":"ਲੋਚਨ ਹੈ ਜਿਨ ਕੇ ਸੁ ਪ੍ਰਭਾਧਰ ਆਨਨ ਹੈ ਜਿਨ ਕੋ ਸਮ ਮੈਨਾ।","roman":"Lochan hai jin ke su prabhaadhar aanan hai jin ko sam mainaa |","meaning_en":"","page":429},{"gurmukhi":"ਕੈ ਕੈ ਕਟਾਛ ਚੁਰਾਇ ਲਯੋ ਮਨ ਪੈ ਤਿਨ ਕੋ ਜੋਊ ਰਛਕ ਧੈਨਾ।","roman":"Kai kai kataachh churaai layo man pai tin ko jo'oo rachhak dhainaa |","meaning_en":"","page":429},{"gurmukhi":"ਕੇਹਰਿ ਸੀ ਜਿਨ ਕੀ ਕਟਿ ਹੈ ਸੁ ਕਪੋਤ ਸੋ ਕੰਠ ਸੁ ਕੋਕਿਲ ਬੈਨਾ।","roman":"Kehri see jin kee kati hai su kapot so kanth su kokil bainaa |","meaning_en":"","page":429},{"gurmukhi":"ਤਾਹਿ ਲਯੋ ਹਰਿ ਕੈ ਹਰਿ ਕੋ ਮਨ ਭਉਰ ਨਚਾਇ ਨਚਾਇ ਕੈ ਨੈਨਾ। ੫੯੮।","roman":"Taahi layo hari kai hari ko man bhaur nachaai nachaai kai nainaa | 598 |","meaning_en":"","page":429}]},{"type":"verse","number":[599],"number_text":"੫੯੯।","page":429,"lines":[{"gurmukhi":"ਕਾਨ੍ਹ ਬਿਰਾਜਤ ਗ੍ਵਾਰਿਨ ਮੈ ਕਬਿ ਸ੍ਯਾਮ ਕਹੈ ਜਿਨ ਕੋ ਕਛੁ ਭਉ ਨਾ।","roman":"Kaanh biraajat gvaarin mai kabi syaam kahai jin ko kachhu bhau naa |","meaning_en":"","page":429},{"gurmukhi":"ਤਾਤ ਕੀ ਬਾਤ ਕੋ ਨੈਕੁ ਸੁਨੈ ਜਿਨ ਕੇ ਸੰਗ ਭ੍ਰਾਤ ਕਰਿਯੋ ਬਨਿ ਗਉਨਾ।","roman":"Taat kee baat ko naiku sunai jin ke sang bhraat kariyo bani gaunaa |","meaning_en":"","page":429},{"gurmukhi":"ਤਾ ਕੀ ਲਟੈ ਲਟਕੈ ਤਨ ਮੋ ਜੋਊ ਸਾਧਨ ਕੇ ਮਨਿ ਗਿਆਨ ਦਿਵਉਨਾ।","roman":"Taa kee latai latkai tan mo jo'oo saadhan ke mani giaan divaunaa |","meaning_en":"","page":429},{"gurmukhi":"ਸੰਦਲ ਪੈ ਉਪਜੀ ਉਪਮਾ ਮਨੋ ਲਾਗ ਰਹੇ ਅਹਿ ਰਾਜਨ ਛਉਨਾ। ੫੯੯।","roman":"Sandal pai upjee upmaa mano laag rahe ahi raajan chhaunaa | 599 |","meaning_en":"","page":429}]},{"type":"verse","number":[600],"number_text":"੬੦੦।","page":429,"lines":[{"gurmukhi":"ਖੇਲਤ ਹੈ ਸੋਊ ਗ੍ਵਾਰਿਨ ਮੈ ਜੋਊ ਊਪਰ ਪੀਤ ਧਰੇ ਉਪਰਉਨਾ।","roman":"Khelat hai so'oo gvaarin mai jo'oo oopar peet dhare upraunaa |","meaning_en":"","page":429},{"gurmukhi":"ਜੋ ਸਿਰ ਸਤ੍ਰਨ ਕੇ ਹਰਿਤਾ ਜੋਊ ਸਾਧਨ ਕੋ ਵਰੁ ਦਾਨ ਦਿਵਉਨਾ।","roman":"Jo sir satran ke haritaa jo'oo saadhan ko varu daan divaunaa |","meaning_en":"","page":429},{"gurmukhi":"ਬੀਚ ਰਹਿਯੋ ਜਗ ਕੇ ਰਵਿ ਕੈ ਕਬਿ ਸ੍ਯਾਮ ਕਹੈ ਜਿਹ ਕੋ ਪੁਨਿ ਖਉਨਾ।","roman":"Beech rahiyo jag ke ravi kai kabi syaam kahai jih ko puni khaunaa |","meaning_en":"","page":429},{"gurmukhi":"ਰਾਜਤ ਯੌ ਅਲਕੈ ਤਿਨ ਕੀ ਮਨੋ ਚੰਦਨ ਲਾਗ ਰਹੇ ਅਹਿ ਛਉਨਾ। ੬੦੦।","roman":"Raajat yau alkai tin kee mano chandan laag rahe ahi chhaunaa | 600 |","meaning_en":"","page":429}]},{"type":"verse","number":[601],"number_text":"੬੦੧।","page":429,"lines":[{"gurmukhi":"ਕੀਰ ਸੇ ਨਾਕ ਕੁਰੰਗ ਸੇ ਨੈਨਨ ਡੋਲਤ ਹੈ ਸੋਊ ਬੀਚ ਤ੍ਰੀਯਾ ਮੈ।","roman":"Keer se naak kurang se nainan dolat hai so'oo beech treeyaa mai |","meaning_en":"","page":429},{"gurmukhi":"ਜੋ ਮਨ ਸਤ੍ਰਨ ਬੀਚ ਰਵਿਯੋ ਜੋ ਰਹਿਯੋ ਰਵਿ ਸਾਧਨ ਬੀਚ ਹੀਯਾ ਮੈ।","roman":"Jo man satran beech raviyo jo rahiyo ravi saadhan beech heeyaa mai |","meaning_en":"","page":429},{"gurmukhi":"ਤਾ ਛਬਿ ਕੋ ਜਸੁ ਉਚ ਮਹਾ ਇਹ ਭਾਤਿਨ ਸੋ ਫੁਨਿ ਉਚਰੀਯਾ ਮੈ।","roman":"Taa chhabi ko jasu uch mahaa ih bhaatin so phuni uchreeyaa mai |","meaning_en":"","page":430},{"gurmukhi":"ਤਾ ਰਸ ਕੀ ਹਮ ਬਾਤ ਕਹੀ ਜੋਊ ਰਾਵਨ ਸੁ ਬਸਿਯੋ ਹੈ ਜੀਆ ਮੈ। ੬੦੧।","roman":"Taa ras kee ham baat kahee jo'oo raavan su basiyo hai jeeaa mai | 601 |","meaning_en":"","page":430}]},{"type":"verse","number":[602],"number_text":"੬੦੨।","page":430,"lines":[{"gurmukhi":"ਖੇਲਤ ਸੰਗ ਗ੍ਵਾਰਿਨ ਕੇ ਕਬਿ ਸ੍ਯਾਮ ਕਹੈ ਜੋਊ ਕਾਨਰ ਕਾਲਾ।","roman":"Khelat sang gvaarin ke kabi syaam kahai jo'oo kaanar kaalaa |","meaning_en":"","page":430},{"gurmukhi":"ਰਾਜਤ ਹੈ ਸੋਈ ਬੀਚ ਖਰੋ ਸੋ ਬਿਰਾਜਤ ਹੈ ਗਿਰਦੇ ਤਿਹ ਬਾਲਾ।","roman":"Raajat hai soee beech kharo so biraajat hai girde tih baalaa |","meaning_en":"","page":430},{"gurmukhi":"ਫੂਲ ਰਹੇ ਜਹ ਫੂਲ ਭਲੀ ਬਿਧਿ ਹੈ ਅਤਿ ਹੀ ਜਹ ਚੰਦ ਉਜਾਲਾ।","roman":"Phool rahe jah phool bhalee bidhi hai ati hee jah chand ujaalaa |","meaning_en":"","page":430},{"gurmukhi":"ਗੋਪਿਨ ਨੈਨਨ ਕੀ ਸੁ ਮਨੋ ਪਹਰੀ ਭਗਵਾਨ ਸੁ ਕੰਜਨ ਮਾਲਾ। ੬੦੨।","roman":"Gopin nainan kee su mano pahree bhagvaan su kanjan maalaa | 602 |","meaning_en":"","page":430}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":430},{"type":"verse","number":[603],"number_text":"੬੦੩।","page":430,"lines":[{"gurmukhi":"ਬਰਨਨ ਚੰਦ੍ਰਭਗਾ ਕਹਿਯੋ ਅਤਿ ਨਿਰਮਲ ਕੈ ਬੁਧਿ।","roman":"Barnan chandrabhgaa kahiyo ati nirmal kai budhi |","meaning_en":"","page":430},{"gurmukhi":"ਉਪਮਾ ਤਾਹਿ ਤਨਉਰ ਕੀ ਸੂਰਜ ਸੀ ਹੈ ਸੁਧਿ। ੬੦੩।","roman":"Upmaa taahi tanaur kee sooraj see hai sudhi | 603 |","meaning_en":"","page":430}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":430},{"type":"verse","number":[604],"number_text":"੬੦੪।","page":430,"lines":[{"gurmukhi":"ਸ੍ਯਾਮ ਕੇ ਜਾ ਪਿਖਿ ਸ੍ਯਾਮ ਕਹੈ ਅਤਿ ਲਾਜਹਿ ਕੇ ਫੁਨਿ ਜਾਲ ਅਟੇ ਹੈ।","roman":"Syaam ke jaa pikhi syaam kahai ati laajhi ke phuni jaal ate hai |","meaning_en":"","page":430},{"gurmukhi":"ਜਾ ਕੀ ਪ੍ਰਭਾ ਅਤਿ ਸੁੰਦਰ ਪੈ ਸੁਤ ਭਾਵਨ ਭਾਵ ਸੁ ਵਾਰਿ ਸੁਟੇ ਹੈ।","roman":"Jaa kee prabhaa ati sundar pai sut bhaavan bhaav su vaari sute hai |","meaning_en":"","page":430},{"gurmukhi":"ਜਿਹ ਕੋ ਪਿਖਿ ਕੈ ਜਨ ਰੀਝ ਰਹੈ ਸੁ ਮੁਨੀਨ ਕੇ ਪੇਖਿ ਧਿਆਨ ਛੁਟੇ ਹੈ।","roman":"Jih ko pikhi kai jan reejh rahai su muneen ke pekhi dhiaan chhute hai |","meaning_en":"","page":430},{"gurmukhi":"ਰਾਜਤ ਰਾਧੇ ਅਹੀਰਿ ਤਨਉਰ ਕੇ ਮਾਨਹੁ ਸੂਰਜ ਸੇ ਪ੍ਰਗਟੇ ਹੈ। ੬੦੪।","roman":"Raajat raadhe aheeri tanaur ke maanhu sooraj se pragte hai | 604 |","meaning_en":"","page":430}]},{"type":"verse","number":[605],"number_text":"੬੦੫।","page":430,"lines":[{"gurmukhi":"ਖੇਲਤ ਹੈ ਸੋਊ ਗ੍ਵਾਰਿਨ ਮੈ ਜਿਹ ਕੋ ਬ੍ਰਿਜ ਹੈ ਅਤਿ ਸੁੰਦਰ ਡੇਰਾ।","roman":"Khelat hai so'oo gvaarin mai jih ko brij hai ati sundar deraa |","meaning_en":"","page":430},{"gurmukhi":"ਜਾਹੀ ਕੇ ਨੈਨ ਕੁਰੰਗ ਸੇ ਹੈ ਜਸੁਧਾ ਜੂ ਕੋ ਬਾਲਕ ਨੰਦਹਿ ਕੇਰਾ।","roman":"Jaahee ke nain kurang se hai jasudhaa joo ko baalak nandhi keraa |","meaning_en":"","page":430},{"gurmukhi":"ਗ੍ਵਾਰਿਨ ਸੋ ਤਹਿ ਘੇਰ ਲਯੋ ਕਹਿਬੇ ਜਸੁ ਕੋ ਉਮਗਿਯੋ ਮਨ ਮੇਰਾ।","roman":"Gvaarin so tahi gher layo kahibe jasu ko umgiyo man meraa |","meaning_en":"","page":430},{"gurmukhi":"ਮਾਨਹੁ ਮੈਨ ਸੋ ਖੇਲਨ ਕਾਜ ਕਰਿਯੋ ਮਿਲ ਕੈ ਮਨੋ ਚਾਦਨ ਘੇਰਾ। ੬੦੫।","roman":"Maanhu main so khelan kaaj kariyo mil kai mano chaadan gheraa | 605 |","meaning_en":"","page":430}]},{"type":"verse","number":[606],"number_text":"੬੦੬।","page":430,"lines":[{"gurmukhi":"ਗ੍ਵਾਰਿਨ ਰੀਝ ਰਹੀ ਹਰਿ ਪੇਖਿ ਸਭੈ ਤਜਿ ਲਾਜਿ ਸੁ ਅਉ ਡਰ ਸਾਸੋ।","roman":"Gvaarin reejh rahee hari pekhi sabhai taji laaji su au dar saaso |","meaning_en":"","page":430},{"gurmukhi":"ਆਈ ਹੈ ਤਿਆਗਿ ਸੋਊ ਗ੍ਰਿਹ ਪੈ ਭਰਤਾਰ ਕਹੈ ਨ ਕਛੂ ਕਹਿ ਮਾਸੋ।","roman":"Aaee hai tiaagi so'oo grih pai bhartaar kahai na kachhoo kahi maaso |","meaning_en":"","page":430},{"gurmukhi":"ਡੋਲਤ ਹੈ ਸੋਊ ਤਾਲ ਬਜਾਇ ਕੈ ਗਾਵਤ ਹੈ ਕਰਿ ਕੈ ਉਪਹਾਸੋ।","roman":"Dolat hai so'oo taal bajaai kai gaavat hai kari kai uphaaso |","meaning_en":"","page":430},{"gurmukhi":"ਮੋਹਿ ਗਿਰੈ ਧਰ ਪੈ ਸੁ ਤ੍ਰੀਯਾ ਕਬਿ ਸ੍ਯਾਮ ਕਹੈ ਚਿਤਵੈ ਹਰਿ ਜਾ ਸੋ। ੬੦੬।","roman":"Mohi girai dhar pai su treeyaa kabi syaam kahai chitvai hari jaa so | 606 |","meaning_en":"","page":430}]},{"type":"verse","number":[607],"number_text":"੬੦੭।","page":430,"lines":[{"gurmukhi":"ਜੋ ਜੁਗ ਤੀਸਰ ਹੈ ਕਰਤਾ ਜੋਊ ਹੈ ਤਨ ਪੈ ਧਰਿਯਾ ਪਟ ਪੀਲੇ।","roman":"Jo jug teesar hai kartaa jo'oo hai tan pai dhariyaa pat peele |","meaning_en":"","page":430},{"gurmukhi":"ਜਾਹਿ ਛਲਿਯੋ ਬਲਿਰਾਜ ਬਲੀ ਜਿਨਿ ਸਤ੍ਰ ਹਨੇ ਕਰਿ ਕੋਪ ਹਠੀਲੇ।","roman":"Jaahi chhaliyo baliraaj balee jini satr hane kari kop hatheele |","meaning_en":"","page":430},{"gurmukhi":"ਗ੍ਵਾਰਿਨ ਰੀਝ ਰਹੀ ਧਰਨੀ ਜੁ ਧਰੇ ਪਟ ਪੀਤਨ ਪੈ ਸੁ ਰੰਗੀਲੇ।","roman":"Gvaarin reejh rahee dharnee ju dhare pat peetan pai su rangeele |","meaning_en":"","page":430},{"gurmukhi":"ਜਿਉ ਮ੍ਰਿਗਨੀ ਸਰ ਲਾਗਿ ਗਿਰੈ ਇਹ ਤਿਉ ਹਰਿ ਦੇਖਤ ਨੈਨ ਰਸੀਲੇ। ੬੦੭।","roman":"Jiu mrignee sar laagi girai ih tiu hari dekhat nain raseele | 607 |","meaning_en":"","page":430}]},{"type":"verse","number":[608],"number_text":"੬੦੮।","page":431,"lines":[{"gurmukhi":"ਕਾਨਰ ਕੇ ਸੰਗ ਖੇਲਤ ਸੋ ਅਤਿ ਹੀ ਸੁਖ ਕੋ ਕਰ ਕੈ ਤਨ ਮੈ।","roman":"Kaanar ke sang khelat so ati hee sukh ko kar kai tan mai |","meaning_en":"","page":431},{"gurmukhi":"ਸ੍ਯਾਮ ਹੀ ਸੋ ਅਤਿ ਹੀ ਹਿਤ ਕੈ ਚਿਤ ਕੈ ਨਹਿ ਬੰਧਨ ਅਉ ਧਨ ਮੈ।","roman":"Syaam hee so ati hee hit kai chit kai nahi bandhan au dhan mai |","meaning_en":"","page":431},{"gurmukhi":"ਧਰਿ ਰੰਗਨਿ ਬਸਤ੍ਰ ਸਭੈ ਤਹਿ ਡੋਲਤ ਯੌ ਉਪਮਾ ਉਪਜੀ ਮਨ ਮੈ।","roman":"Dhari rangni basatr sabhai tahi dolat yau upmaa upjee man mai |","meaning_en":"","page":431},{"gurmukhi":"ਜੋਊ ਫੂਲ ਮੁਖੀ ਤਹ ਫੂਲ ਕੈ ਖੇਲਤ ਫੂਲ ਸੀ ਹੋਇ ਗਈ ਬਨ ਮੈ। ੬੦੮।","roman":"Jo'oo phool mukhee tah phool kai khelat phool see hoi gaee ban mai | 608 |","meaning_en":"","page":431}]},{"type":"verse","number":[609],"number_text":"੬੦੯।","page":431,"lines":[{"gurmukhi":"ਸਭ ਖੇਲਤ ਹੈ ਮਨਿ ਆਨੰਦ ਕੈ ਭਗਵਾਨ ਕੋ ਧਾਰਿ ਸਬੈ ਮਨ ਮੈ।","roman":"Sabh khelat hai mani aanand kai bhagvaan ko dhaari sabai man mai |","meaning_en":"","page":431},{"gurmukhi":"ਹਰਿ ਕੇ ਚਿਤਬੇ ਕੀ ਰਹੀ ਸੁਧਿ ਏਕਨ ਅਉਰ ਰਹੀ ਨ ਕਛੂ ਤਨ ਮੈ।","roman":"Hari ke chitbe kee rahee sudhi ekan aur rahee na kachhoo tan mai |","meaning_en":"","page":431},{"gurmukhi":"ਨਹੀ ਭੂਤਲ ਮੈ ਅਰੁ ਮਾਤਲੁ ਮੈ ਇਨਿ ਸੋ ਨਹਿ ਦੇਵਨ ਕੇ ਗਨ ਮੈ।","roman":"Nahee bhootal mai aru maatlu mai ini so nahi devan ke gan mai |","meaning_en":"","page":431},{"gurmukhi":"ਸੋਊ ਰੀਝ ਸੋ ਸ੍ਯਾਮ ਕਹੈ ਅਤਿ ਹੀ ਫੁਨਿ ਡੋਲਤ ਗ੍ਵਾਰਿਨ ਕੇ ਗਨ ਮੈ। ੬੦੯।","roman":"So'oo reejh so syaam kahai ati hee phuni dolat gvaarin ke gan mai | 609 |","meaning_en":"","page":431}]},{"type":"verse","number":[610],"number_text":"੬੧੦।","page":431,"lines":[{"gurmukhi":"ਹਸਿ ਕੈ ਭਗਵਾਨ ਕਹੀ ਬਤੀਯਾ ਬ੍ਰਿਖਭਾਨੁ ਸੁਤਾ ਪਿਖਿ ਰੂਪ ਨਵੀਨੋ।","roman":"Hasi kai bhagvaan kahee bateeyaa brikhbhaanu sutaa pikhi roop naveeno |","meaning_en":"","page":431},{"gurmukhi":"ਅੰਜਨ ਆਡ ਧਰੇ ਪੁਨਿ ਬੇਸਰ ਭਾਵ ਸਭੈ ਜਿਨਿ ਭਾਵਨ ਕੀਨੋ।","roman":"Anjan aad dhare puni besar bhaav sabhai jini bhaavan keeno |","meaning_en":"","page":431},{"gurmukhi":"ਸੁੰਦਰ ਸੇਂਧਰ ਕੋ ਜਿਨ ਲੈ ਕਰਿ ਭਾਲ ਬਿਖੈ ਬਿੰਦੂਆ ਇਕ ਦੀਨੋ।","roman":"Sundar sendhar ko jin lai kari bhaal bikhai bindooaa ik deeno |","meaning_en":"","page":431},{"gurmukhi":"ਨੈਨ ਨਚਾਇ ਮਨੈ ਸੁਖ ਪਾਇ ਚਿਤੈ ਜਦੁਰਾਇ ਤਬੈ ਹਸਿ ਦੀਨੋ। ੬੧੦।","roman":"Nain nachaai manai sukh paai chitai jaduraai tabai hasi deeno | 610 |","meaning_en":"","page":431}]},{"type":"verse","number":[611],"number_text":"੬੧੧।","page":431,"lines":[{"gurmukhi":"ਬੀਨ ਸੀ ਗ੍ਵਾਰਿਨ ਗਾਵਤ ਹੈ ਸੁਨਬੇ ਕਹੁ ਸੁੰਦਰ ਕਾਨਰ ਕਾਰੇ।","roman":"Been see gvaarin gaavat hai sunbe kahu sundar kaanar kaare |","meaning_en":"","page":431},{"gurmukhi":"ਆਨਨ ਹੈ ਜਿਨ ਕੋ ਸਸਿ ਸੋ ਸੁ ਬਿਰਾਜਤ ਕੰਜਨ ਸੇ ਦ੍ਰਿਗ ਭਾਰੇ।","roman":"Aanan hai jin ko sasi so su biraajat kanjan se drig bhaare |","meaning_en":"","page":431},{"gurmukhi":"ਝਾਝਨ ਤਾ ਕੀ ਉਠੀ ਧਰ ਪੈ ਧੁਨਿ ਤਾ ਛਬਿ ਕੋ ਕਬਿ ਸ੍ਯਾਮ ਉਚਾਰੇ।","roman":"Jhaajhan taa kee uthee dhar pai dhuni taa chhabi ko kabi syaam uchaare |","meaning_en":"","page":431},{"gurmukhi":"ਢੋਲਕ ਸੰਗਿ ਤੰਬੂਰਨ ਹੋਇ ਉਠੇ ਤਹ ਬਾਜਿ ਮ੍ਰਿਦੰਗ ਨਗਾਰੇ। ੬੧੧।","roman":"Dholak sangi tanbooran hoi uthe tah baaji mridang nagaare | 611 |","meaning_en":"","page":431}]},{"type":"verse","number":[612],"number_text":"੬੧੨।","page":431,"lines":[{"gurmukhi":"ਖੇਲਤ ਗ੍ਵਾਰਿਨ ਪ੍ਰੇਮ ਛਕੀ ਕਬਿ ਸ੍ਯਾਮ ਕਹੈ ਸੰਗ ਕਾਨਰ ਕਾਰੇ।","roman":"Khelat gvaarin prem chhakee kabi syaam kahai sang kaanar kaare |","meaning_en":"","page":431},{"gurmukhi":"ਛਾਜਤ ਜਾ ਮੁਖ ਚੰਦ ਪ੍ਰਭਾ ਸਮ ਰਾਜਤ ਕੰਚਨ ਸੇ ਦ੍ਰਿਗ ਭਾਰੇ।","roman":"Chhaajat jaa mukh chand prabhaa sam raajat kanchan se drig bhaare |","meaning_en":"","page":431},{"gurmukhi":"ਜਾ ਪਿਖਿ ਕੰਦ੍ਰਪ ਰੀਝ ਰਹੈ ਪਿਖਿ ਏ ਜਿਹ ਕੇ ਮ੍ਰਿਗ ਆਦਿਕ ਹਾਰੇ।","roman":"Jaa pikhi kandrap reejh rahai pikhi e jih ke mrig aadik haare |","meaning_en":"","page":431},{"gurmukhi":"ਕੇਹਰਿ ਕੋਕਿਲ ਕੇ ਸਭ ਭਾਵ ਕਿਧੌ ਇਨ ਪੈ ਗਨ ਊਪਰ ਵਾਰੇ। ੬੧੨।","roman":"Kehri kokil ke sabh bhaav kidhau in pai gan oopar vaare | 612 |","meaning_en":"","page":431}]},{"type":"verse","number":[613],"number_text":"੬੧੩।","page":431,"lines":[{"gurmukhi":"ਜਾਹਿ ਬਿਭੀਛਨਿ ਰਾਜ ਦੀਯੋ ਜਿਨ ਹੂੰ ਬਰ ਰਾਵਨ ਸੋ ਰਿਪੁ ਸਾਧੋ।","roman":"Jaahi bibheechhni raaj deeyo jin hoon bar raavan so ripu saadho |","meaning_en":"","page":431},{"gurmukhi":"ਖੇਲਤ ਹੈ ਸੋਊ ਭੂਮਿ ਬਿਖੈ ਬ੍ਰਿਜ ਲਾਜ ਜਹਾਜਨ ਕੋ ਤਜਿ ਬਾਧੋ।","roman":"Khelat hai so'oo bhoomi bikhai brij laaj jahaajan ko taji baadho |","meaning_en":"","page":431},{"gurmukhi":"ਜਾਹਿ ਨਿਕਾਸ ਲਯੋ ਮੁਰਿ ਪ੍ਰਾਨ ਸੁ ਮਾਪ ਲੀਯੋ ਬਲਿ ਕੋ ਤਨ ਆਧੋ।","roman":"Jaahi nikaas layo muri praan su maap leeyo bali ko tan aadho |","meaning_en":"","page":431},{"gurmukhi":"ਸ੍ਯਾਮ ਕਹੈ ਸੰਗ ਗ੍ਵਾਰਿਨ ਕੇ ਅਤਿ ਹੀ ਰਸਿ ਕੈ ਸੋਊ ਖੇਲਤ ਮਾਧੋ। ੬੧੩।","roman":"Syaam kahai sang gvaarin ke ati hee rasi kai so'oo khelat maadho | 613 |","meaning_en":"","page":431}]},{"type":"verse","number":[614],"number_text":"੬੧੪।","page":432,"lines":[{"gurmukhi":"ਜੋ ਮੁਰ ਨਾਮ ਮਹਾ ਰਿਪੁ ਪੈ ਕੁਪ ਕੈ ਅਤਿ ਹੀ ਡਰਈਯਾ ਫੁਨਿ ਭੀਰਨਿ।","roman":"Jo mur naam mahaa ripu pai kup kai ati hee daraeeyaa phuni bheerni |","meaning_en":"","page":432},{"gurmukhi":"ਜੋ ਗਜ ਸੰਕਟ ਕੋ ਕਟੀਯਾ ਹਰਤਾ ਜੋਊ ਸਾਧਨ ਕੇ ਦੁਖ ਪੀਰਨਿ।","roman":"Jo gaj sankat ko kateeyaa hartaa jo'oo saadhan ke dukh peerni |","meaning_en":"","page":432},{"gurmukhi":"ਸੋ ਬ੍ਰਿਜ ਮੈ ਜਮੁਨਾ ਤਟ ਪੈ ਕਬਿ ਸ੍ਯਾਮ ਕਹੈ ਹਰੈਯਾ ਤ੍ਰੀਯ ਚੀਰਨਿ।","roman":"So brij mai jamunaa tat pai kabi syaam kahai haraiyaa treey cheerni |","meaning_en":"","page":432},{"gurmukhi":"ਤਾ ਕਰ ਕੈ ਰਸ ਕੋ ਚਸਕੋ ਇਹ ਭਾਤਿ ਕਹਿਯੋ ਗਨ ਬੀਚ ਅਹੀਰਨਿ। ੬੧੪।","roman":"Taa kar kai ras ko chasko ih bhaati kahiyo gan beech aheerni | 614 |","meaning_en":"","page":432}]},{"type":"heading","kind":"speaker","name":"ਕਾਨ੍ਹ ਜੂ ਬਾਚ ਗ੍ਵਾਰਿਨ ਸੋ","gurmukhi":"ਕਾਨ੍ਹ ਜੂ ਬਾਚ ਗ੍ਵਾਰਿਨ ਸੋ","roman":"Kaanh joo baach gvaarin so","meaning_en":"","page":432},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":432},{"type":"verse","number":[615],"number_text":"੬੧੫।","page":432,"lines":[{"gurmukhi":"ਕੇਲ ਕਰੋ ਹਮ ਸੰਗ ਕਹਿਓ ਅਪਨੇ ਮਨ ਮੈ ਕਛੁ ਸੰਕ ਨ ਆਨੋ।","roman":"Kel karo ham sang kahio apne man mai kachhu sank na aano |","meaning_en":"","page":432},{"gurmukhi":"ਝੂਠ ਕਹਿਯੋ ਨਹਿ ਮਾਨਹੁ ਰੀ ਕਹਿਯੋ ਹਮਰੋ ਤੁਮ ਸਾਚ ਪਛਾਨੋ।","roman":"Jhooth kahiyo nahi maanhu ree kahiyo hamro tum saach pachhaano |","meaning_en":"","page":432},{"gurmukhi":"ਗੁਆਰਨੀਯਾ ਹਰਿ ਕੀ ਸੁਨਿ ਬਾਤ ਗਈ ਤਜਿ ਲਾਜ ਕਬੈ ਜਸੁ ਠਾਨੋ।","roman":"Guaarneeyaa hari kee suni baat gaee taji laaj kabai jasu thaano |","meaning_en":"","page":432},{"gurmukhi":"ਰਾਤਿ ਬਿਖੈ ਤਜਿ ਝੀਲਹਿ ਕੋ ਨਭ ਬੀਚ ਚਲਿਯੋ ਜਿਮ ਜਾਤ ਟਨਾਨੋ। ੬੧੫।","roman":"Raati bikhai taji jheelhi ko nabh beech chaliyo jim jaat tanaano | 615 |","meaning_en":"","page":432}]},{"type":"verse","number":[616],"number_text":"੬੧੬।","page":432,"lines":[{"gurmukhi":"ਬ੍ਰਿਖਭਾਨੁ ਸੁਤਾ ਹਰਿ ਕੇ ਹਿਤ ਗਾਵਤ ਗ੍ਵਾਰਿਨ ਕੇ ਸੁ ਕਿਧੌ ਗਨ ਮੈ।","roman":"Brikhbhaanu sutaa hari ke hit gaavat gvaarin ke su kidhau gan mai |","meaning_en":"","page":432},{"gurmukhi":"ਇਮ ਨਾਚਤ ਹੈ ਅਤਿ ਪ੍ਰੇਮ ਭਰੀ ਬਿਜਲੀ ਜਿਹ ਭਾਤਿ ਘਨੇ ਘਨ ਮੈ।","roman":"Im naachat hai ati prem bharee bijlee jih bhaati ghane ghan mai |","meaning_en":"","page":432},{"gurmukhi":"ਕਬਿ ਨੇ ਉਪਮਾ ਤਿਹ ਗਾਇਬ ਕੀ ਸੁ ਬਿਚਾਰ ਕਹੀ ਅਪਨੇ ਮਨ ਮੈ।","roman":"Kabi ne upmaa tih gaaib kee su bichaar kahee apne man mai |","meaning_en":"","page":432},{"gurmukhi":"ਰੁਤਿ ਚੇਤ ਕੀ ਮੈ ਮਨ ਆਨੰਦ ਕੈ ਕੁਹਕੈ ਮਨੋ ਕੋਕਿਲਕਾ ਬਨ ਮੈ। ੬੧੬।","roman":"Ruti chet kee mai man aanand kai kuhkai mano kokilkaa ban mai | 616 |","meaning_en":"","page":432}]},{"type":"verse","number":[617],"number_text":"੬੧੭।","page":432,"lines":[{"gurmukhi":"ਹਰਿ ਕੇ ਸੰਗ ਖੇਲਤ ਰੰਗ ਭਰੀ ਸੁ ਤ੍ਰੀਯਾ ਸਜਿ ਸਾਜ ਸਭੈ ਤਨ ਮੈ।","roman":"Hari ke sang khelat rang bharee su treeyaa saji saaj sabhai tan mai |","meaning_en":"","page":432},{"gurmukhi":"ਅਤਿ ਹੀ ਕਰ ਕੈ ਹਿਤ ਕਾਨਰ ਸੋ ਕਰ ਕੈ ਨਹੀ ਬੰਧਨ ਔ ਧਨ ਮੈ।","roman":"Ati hee kar kai hit kaanar so kar kai nahee bandhan au dhan mai |","meaning_en":"","page":432},{"gurmukhi":"ਫੁਨਿ ਤਾ ਛਬਿ ਕੀ ਅਤਿ ਹੀ ਉਪਮਾ ਉਪਜੀ ਕਬਿ ਸ੍ਯਾਮ ਕੇ ਯੌ ਮਨ ਮੈ।","roman":"Phuni taa chhabi kee ati hee upmaa upjee kabi syaam ke yau man mai |","meaning_en":"","page":432},{"gurmukhi":"ਮਨੋ ਸਾਵਨ ਮਾਸ ਕੇ ਮਧ ਬਿਖੈ ਚਮਕੈ ਜਿਮ ਬਿਦੁਲਤਾ ਘਨ ਮੈ। ੬੧੭।","roman":"Mano saavan maas ke madh bikhai chamkai jim bidultaa ghan mai | 617 |","meaning_en":"","page":432}]},{"type":"verse","number":[618],"number_text":"੬੧੮।","page":432,"lines":[{"gurmukhi":"ਸ੍ਯਾਮ ਸੋ ਸੁੰਦਰ ਖੇਲਤ ਹੈ ਕਬਿ ਸ੍ਯਾਮ ਕਹੈ ਅਤਿ ਹੀ ਰੰਗ ਰਾਚੀ।","roman":"Syaam so sundar khelat hai kabi syaam kahai ati hee rang raachee |","meaning_en":"","page":432},{"gurmukhi":"ਰੂਪ ਸਚੀ ਅਰੁ ਪੈ ਰਤਿ ਕੀ ਮਨ ਮੈ ਕਰ ਪ੍ਰੀਤਿ ਸੋ ਖੇਲਤ ਸਾਚੀ।","roman":"Roop sachee aru pai rati kee man mai kar preeti so khelat saachee |","meaning_en":"","page":432},{"gurmukhi":"ਰਾਸ ਕੀ ਖੇਲ ਤਟੈ ਜਮੁਨਾ ਰਜਨੀ ਅਰੁ ਦ੍ਯੋਸ ਬਿਧਰਕ ਮਾਚੀ।","roman":"Raas kee khel tatai jamunaa rajnee aru dyos bidhrak maachee |","meaning_en":"","page":432},{"gurmukhi":"ਚੰਦ੍ਰਭਗਾ ਅਰੁ ਚੰਦ੍ਰਮੁਖੀ ਬ੍ਰਿਖਭਾਨੁ ਸੁਤਾ ਤਜ ਲਾਜਹਿ ਨਾਚੀ। ੬੧੮।","roman":"Chandrabhgaa aru chandramukhee brikhbhaanu sutaa taj laajhi naachee | 618 |","meaning_en":"","page":432}]},{"type":"verse","number":[619],"number_text":"੬੧੯।","page":432,"lines":[{"gurmukhi":"ਰਾਸ ਕੀ ਖੇਲ ਸੁ ਗ੍ਵਾਰਨੀਯਾ ਅਤਿ ਹੀ ਤਹ ਸੁੰਦਰ ਭਾਤਿ ਰਚੀ ਹੈ।","roman":"Raas kee khel su gvaarneeyaa ati hee tah sundar bhaati rachee hai |","meaning_en":"","page":432},{"gurmukhi":"ਲੋਚਨ ਹੈ ਜਿਨ ਕੇ ਮ੍ਰਿਗ ਸੇ ਜਿਨ ਕੇ ਸਮਤੁਲ ਨ ਰੂਪ ਸਚੀ ਹੈ।","roman":"Lochan hai jin ke mrig se jin ke samtul na roop sachee hai |","meaning_en":"","page":432},{"gurmukhi":"ਕੰਚਨ ਸੋ ਜਿਨ ਕੋ ਤਨ ਹੈ ਮੁਖ ਹੈ ਸਸਿ ਸੋ ਤਹ ਰਾਧਿ ਗਚੀ ਹੈ।","roman":"Kanchan so jin ko tan hai mukh hai sasi so tah raadhi gachee hai |","meaning_en":"","page":432},{"gurmukhi":"ਮਾਨੋ ਕਰੀ ਕਰਿ ਲੈ ਕਰਤਾ ਸੁਧ ਸੁੰਦਰ ਤੇ ਜੋਊ ਬਾਕੀ ਬਚੀ ਹੈ। ੬੧੯।","roman":"Maano karee kari lai kartaa sudh sundar te jo'oo baakee bachee hai | 619 |","meaning_en":"","page":432}]},{"type":"verse","number":[620],"number_text":"੬੨੦।","page":433,"lines":[{"gurmukhi":"ਆਈ ਹੈ ਖੇਲਨ ਰਾਸ ਬਿਖੈ ਸਜ ਕੈ ਸੁ ਤ੍ਰੀਯਾ ਤਨ ਸੁੰਦਰ ਬਾਨੇ।","roman":"Aaee hai khelan raas bikhai saj kai su treeyaa tan sundar baane |","meaning_en":"","page":433},{"gurmukhi":"ਪੀਤ ਰੰਗੇ ਇਕ ਰੰਗ ਕਸੁੰਭ ਕੇ ਏਕ ਹਰੇ ਇਕ ਕੇਸਰ ਸਾਨੇ।","roman":"Peet range ik rang kasunbh ke ek hare ik kesar saane |","meaning_en":"","page":433},{"gurmukhi":"ਤਾ ਛਬਿ ਕੇ ਜਸੁ ਉਚ ਮਹਾ ਕਬਿ ਨੇ ਅਪਨੇ ਮਨ ਮੈ ਪਹਿਚਾਨੇ।","roman":"Taa chhabi ke jasu uch mahaa kabi ne apne man mai pahichaane |","meaning_en":"","page":433},{"gurmukhi":"ਨਾਚਤ ਭੂਮਿ ਗਿਰੀ ਧਰਨੀ ਹਰਿ ਦੇਖ ਰਹੀ ਨਹੀ ਨੈਨ ਅਘਾਨੇ। ੬੨੦।","roman":"Naachat bhoomi giree dharnee hari dekh rahee nahee nain aghaane | 620 |","meaning_en":"","page":433}]},{"type":"verse","number":[621],"number_text":"੬੨੧।","page":433,"lines":[{"gurmukhi":"ਤਿਨ ਕੋ ਇਤਨੋ ਹਿਤ ਦੇਖਤ ਹੀ ਅਤਿ ਆਨੰਦ ਸੋ ਭਗਵਾਨ ਹਸੇ ਹੈ।","roman":"Tin ko itno hit dekhat hee ati aanand so bhagvaan hase hai |","meaning_en":"","page":433},{"gurmukhi":"ਪ੍ਰੀਤਿ ਬਢੀ ਅਤਿ ਗ੍ਵਾਰਿਨ ਸੋ ਅਤਿ ਹੀ ਰਸ ਕੇ ਫੁਨਿ ਬੀਚ ਫਸੈ ਹੈ।","roman":"Preeti badhee ati gvaarin so ati hee ras ke phuni beech phasai hai |","meaning_en":"","page":433},{"gurmukhi":"ਜਾ ਤਨ ਦੇਖਤ ਪੁੰਨਿ ਬਢੈ ਜਿਹ ਦੇਖਤ ਸਹੀ ਸਭ ਪਾਪ ਨਸੇ ਹੈ।","roman":"Jaa tan dekhat punni badhai jih dekhat sahee sabh paap nase hai |","meaning_en":"","page":433},{"gurmukhi":"ਜਿਉ ਸਸਿ ਅਗ੍ਰ ਲਸੈ ਚਪਲਾ ਹਰਿ ਦਾਰਮ ਸੇ ਤਿਮ ਦਾਤ ਲਸੇ ਹੈ। ੬੨੧।","roman":"Jiu sasi agr lasai chaplaa hari daaram se tim daat lase hai | 621 |","meaning_en":"","page":433}]},{"type":"verse","number":[622],"number_text":"੬੨੨।","page":433,"lines":[{"gurmukhi":"ਸੰਗ ਗੋਪਿਨ ਬਾਤ ਕਹੀ ਰਸ ਕੀ ਜੋਊ ਕਾਨਰ ਹੈ ਸਭ ਦੈਤ ਮਰਈਯਾ।","roman":"Sang gopin baat kahee ras kee jo'oo kaanar hai sabh dait maraeeyaa |","meaning_en":"","page":433},{"gurmukhi":"ਸਾਧਨ ਕੋ ਜੋਊ ਹੈ ਬਰਤਾ ਅਉ ਅਸਾਧਨ ਕੋ ਜੋਊ ਨਾਸ ਕਰਈਯਾ।","roman":"Saadhan ko jo'oo hai bartaa au asaadhan ko jo'oo naas karaeeyaa |","meaning_en":"","page":433},{"gurmukhi":"ਰਾਸ ਬਿਖੈ ਸੋਊ ਖੇਲਤ ਹੈ ਜਸੁਧਾ ਸੁਤ ਜੋ ਮੁਸਲੀਧਰ ਭਈਯਾ।","roman":"Raas bikhai so'oo khelat hai jasudhaa sut jo musleedhar bhaeeyaa |","meaning_en":"","page":433},{"gurmukhi":"ਨੈਨਨ ਕੇ ਕਰ ਕੈ ਸੁ ਕਟਾਛ ਚੁਰਾਇ ਮਨੋ ਮਤਿ ਗੋਪਿਨ ਲਈਯਾ। ੬੨੨।","roman":"Nainan ke kar kai su kataachh churaai mano mati gopin laeeyaa | 622 |","meaning_en":"","page":433}]},{"type":"verse","number":[623],"number_text":"੬੨੩।","page":433,"lines":[{"gurmukhi":"ਦੇਵ ਗੰਧਾਰਿ ਬਿਲਾਵਲ ਸੁਧ ਮਲਾਰ ਕਹੈ ਕਬਿ ਸ੍ਯਾਮ ਸੁਨਾਈ।","roman":"Dev gandhaari bilaaval sudh malaar kahai kabi syaam sunaaee |","meaning_en":"","page":433},{"gurmukhi":"ਜੈਤਸਿਰੀ ਗੁਜਰੀ ਕੀ ਭਲੀ ਧੁਨਿ ਰਾਮਕਲੀ ਹੂੰ ਕੀ ਤਾਨ ਬਸਾਈ।","roman":"Jaitsiree gujree kee bhalee dhuni raamaklee hoon kee taan basaaee |","meaning_en":"","page":433},{"gurmukhi":"ਸਥਾਵਰ ਤੇ ਸੁਨ ਕੈ ਸੁਰ ਜੀ ਜੜ ਜੰਗਮ ਤੇ ਸੁਰ ਜਾ ਸੁਨ ਪਾਈ।","roman":"Sathaavar te sun kai sur jee jar jangam te sur jaa sun paaee |","meaning_en":"","page":433},{"gurmukhi":"ਰਾਸ ਬਿਖੈ ਸੰਗਿ ਗ੍ਵਾਰਿਨ ਕੇ ਇਹ ਭਾਤਿ ਸੋ ਬੰਸੁਰੀ ਕਾਨ੍ਹ ਬਜਾਈ। ੬੨੩।","roman":"Raas bikhai sangi gvaarin ke ih bhaati so bansuree kaanh bajaaee | 623 |","meaning_en":"","page":433}]},{"type":"verse","number":[624],"number_text":"੬੨੪।","page":433,"lines":[{"gurmukhi":"ਦੀਪਕ ਅਉ ਨਟ ਨਾਇਕ ਰਾਗ ਭਲੀ ਬਿਧਿ ਗਉਰੀ ਕੀ ਤਾਨ ਬਸਾਈ।","roman":"Deepak au nat naaik raag bhalee bidhi gauree kee taan basaaee |","meaning_en":"","page":433},{"gurmukhi":"ਸੋਰਠਿ ਸਾਰੰਗ ਰਾਮਕਲੀ ਸੁਰ ਜੈਤਸਿਰੀ ਸੁਭ ਭਾਤਿ ਸੁਨਾਈ।","roman":"Sorthi saarang raamaklee sur jaitsiree subh bhaati sunaaee |","meaning_en":"","page":433},{"gurmukhi":"ਰੀਝ ਰਹੇ ਪ੍ਰਿਥਮੀ ਕੇ ਸਭੈ ਜਨ ਰੀਝ ਰਹਿਯੋ ਸੁਨ ਕੇ ਸੁਰ ਰਾਈ।","roman":"Reejh rahe prithmee ke sabhai jan reejh rahiyo sun ke sur raaee |","meaning_en":"","page":433},{"gurmukhi":"ਤੀਰ ਨਦੀ ਸੰਗਿ ਗ੍ਵਾਰਿਨ ਕੇ ਮੁਰਲੀ ਕਰਿ ਆਨੰਦ ਸ੍ਯਾਮ ਬਜਾਈ। ੬੨੪।","roman":"Teer nadee sangi gvaarin ke murlee kari aanand syaam bajaaee | 624 |","meaning_en":"","page":433}]},{"type":"verse","number":[625],"number_text":"੬੨੫।","page":433,"lines":[{"gurmukhi":"ਜਿਹ ਕੇ ਮੁਖ ਕੀ ਸਮ ਚੰਦ੍ਰਪ੍ਰਭਾ ਤਨ ਕੀ ਇਹ ਭਾ ਮਨੋ ਕੰਚਨ ਸੀ ਹੈ।","roman":"Jih ke mukh kee sam chandraprabhaa tan kee ih bhaa mano kanchan see hai |","meaning_en":"","page":433},{"gurmukhi":"ਮਾਨਹੁ ਲੈ ਕਰ ਮੈ ਕਰਤਾ ਸੁ ਅਨੂਪ ਸੀ ਮੂਰਤਿ ਯਾ ਕੀ ਕਸੀ ਹੈ।","roman":"Maanhu lai kar mai kartaa su anoop see moorti yaa kee kasee hai |","meaning_en":"","page":433},{"gurmukhi":"ਚਾਦਨੀ ਮੈ ਗਨ ਗ੍ਵਾਰਿਨ ਕੇ ਇਹ ਗ੍ਵਾਰਿਨ ਗੋਪਿਨ ਤੇ ਸੁ ਹਛੀ ਹੈ।","roman":"Chaadnee mai gan gvaarin ke ih gvaarin gopin te su hachhee hai |","meaning_en":"","page":433},{"gurmukhi":"ਬਾਤ ਜੁ ਥੀ ਮਨ ਕਾਨਰ ਕੇ ਬ੍ਰਿਖਭਾਨ ਸੁਤਾ ਸੋਊ ਪੈ ਲਖਿ ਲੀ ਹੈ। ੬੨੫।","roman":"Baat ju thee man kaanar ke brikhbhaan sutaa so'oo pai lakhi lee hai | 625 |","meaning_en":"","page":433}]},{"type":"heading","kind":"speaker","name":"ਕਾਨ ਜੂ ਬਾਚ ਰਾਧੇ ਸੋ","gurmukhi":"ਕਾਨ ਜੂ ਬਾਚ ਰਾਧੇ ਸੋ","roman":"Kaan joo baach raadhe so","meaning_en":"","page":434},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":434},{"type":"verse","number":[626],"number_text":"੬੨੬।","page":434,"lines":[{"gurmukhi":"ਕ੍ਰਿਸਨ ਰਾਧਿਕਾ ਤਨ ਨਿਰਖਿ ਕਹੀ ਬਿਹਸਿ ਕੈ ਬਾਤ।","roman":"Krisan raadhikaa tan nirkhi kahee bihsi kai baat |","meaning_en":"","page":434},{"gurmukhi":"ਮ੍ਰਿਗ ਕੇ ਅਰੁ ਫੁਨਿ ਮੈਨ ਕੇ ਤੋ ਮੈ ਸਭ ਹੈ ਗਾਤਿ। ੬੨੬।","roman":"Mrig ke aru phuni main ke to mai sabh hai gaati | 626 |","meaning_en":"","page":434}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":434},{"type":"verse","number":[627],"number_text":"੬੨੭।","page":434,"lines":[{"gurmukhi":"ਭਾਗ ਕੋ ਭਾਲ ਹਰਿਯੋ ਸੁਨਿ ਗ੍ਵਾਰਿਨ ਛੀਨ ਲਈ ਮੁਖ ਜੋਤਿ ਸਸੀ ਹੈ।","roman":"Bhaag ko bhaal hariyo suni gvaarin chheen laee mukh joti sasee hai |","meaning_en":"","page":434},{"gurmukhi":"ਨੈਨ ਮਨੋ ਸਰ ਤੀਛਨ ਹੈ ਭ੍ਰਿਕੁਟੀ ਮਨੋ ਜਾਨੁ ਕਮਾਨ ਕਸੀ ਹੈ।","roman":"Nain mano sar teechhan hai bhrikutee mano jaanu kamaan kasee hai |","meaning_en":"","page":434},{"gurmukhi":"ਕੋਕਿਲ ਬੈਨ ਕਪੋਤਿ ਸੋ ਕੰਠ ਕਹੀ ਹਮਰੇ ਮਨ ਜੋਊ ਬਸੀ ਹੈ।","roman":"Kokil bain kapoti so kanth kahee hamre man jo'oo basee hai |","meaning_en":"","page":434},{"gurmukhi":"ਏਤੇ ਪੈ ਚੋਰ ਲਯੋ ਹਮਰੋ ਚਿਤ ਭਾਮਿਨਿ ਦਾਮਿਨਿ ਭਾਤਿ ਲਸੀ ਹੈ। ੬੨੭।","roman":"Ete pai chor layo hamro chit bhaamini daamini bhaati lasee hai | 627 |","meaning_en":"","page":434}]},{"type":"verse","number":[628],"number_text":"੬੨੮।","page":434,"lines":[{"gurmukhi":"ਕਾਨਰ ਲੈ ਬ੍ਰਿਖਭਾਨ ਸੁਤਾ ਸੰਗਿ ਗੀਤ ਭਲੀ ਬਿਧਿ ਸੁੰਦਰ ਗਾਵੈ।","roman":"Kaanar lai brikhbhaan sutaa sangi geet bhalee bidhi sundar gaavai |","meaning_en":"","page":434},{"gurmukhi":"ਸਾਰੰਗ ਦੇਵ ਗੰਧਾਰ ਬਿਭਾਸ ਬਿਲਾਵਲ ਭੀਤਰ ਤਾਨ ਬਸਾਵੈ।","roman":"Saarang dev gandhaar bibhaas bilaaval bheetar taan basaavai |","meaning_en":"","page":434},{"gurmukhi":"ਜੋ ਜੜ ਸ੍ਰਉਨਨ ਮੈ ਸੁਨ ਕੈ ਧੁਨਿ ਤਿਆਗ ਕੈ ਧਾਮ ਤਹਾ ਕਹੁ ਧਾਵੈ।","roman":"Jo jar sraunan mai sun kai dhuni tiaag kai dhaam tahaa kahu dhaavai |","meaning_en":"","page":434},{"gurmukhi":"ਜੋ ਖਗ ਜਾਤ ਉਡੇ ਨਭਿ ਮੈ ਸੁਨਿ ਠਾਢ ਰਹੈ ਧੁਨਿ ਜੋ ਸੁਨਿ ਪਾਵੈ। ੬੨੮।","roman":"Jo khag jaat ude nabhi mai suni thaadh rahai dhuni jo suni paavai | 628 |","meaning_en":"","page":434}]},{"type":"verse","number":[629],"number_text":"੬੨੯।","page":434,"lines":[{"gurmukhi":"ਗ੍ਵਾਰਿਨ ਸੰਗ ਭਲੇ ਭਗਵਾਨ ਸੋ ਖੇਲਤ ਹੈ ਅਰੁ ਨਾਚਤ ਐਸੇ।","roman":"Gvaarin sang bhale bhagvaan so khelat hai aru naachat aise |","meaning_en":"","page":434},{"gurmukhi":"ਖੇਲਤ ਹੈ ਮਨਿ ਆਨੰਦ ਕੈ ਨ ਕਛੂ ਜਰਰਾ ਮਨਿ ਧਾਰ ਕੈ ਭੈ ਸੇ।","roman":"Khelat hai mani aanand kai na kachhoo jarraa mani dhaar kai bhai se |","meaning_en":"","page":434},{"gurmukhi":"ਗਾਵਤ ਸਾਰੰਗ ਤਾਲ ਬਜਾਵਤ ਸ੍ਯਾਮ ਕਹੈ ਅਤਿ ਹੀ ਸੁ ਰਚੈ ਸੇ।","roman":"Gaavat saarang taal bajaavat syaam kahai ati hee su rachai se |","meaning_en":"","page":434},{"gurmukhi":"ਸਾਵਨ ਕੀ ਰੁਤਿ ਮੈ ਮਨੋ ਨਾਚਤ ਮੋਰਿਨ ਮੈ ਮੁਰਵਾ ਨਰ ਜੈਸੇ। ੬੨੯।","roman":"Saavan kee ruti mai mano naachat morin mai murvaa nar jaise | 629 |","meaning_en":"","page":434}]},{"type":"verse","number":[630],"number_text":"੬੩੦।","page":434,"lines":[{"gurmukhi":"ਨਾਚਤ ਹੈ ਸੋਊ ਗ੍ਵਾਰਿਨ ਮੈ ਜਿਹ ਕੋ ਸਸਿ ਸੋ ਅਤਿ ਸੁੰਦਰ ਆਨਨ।","roman":"Naachat hai so'oo gvaarin mai jih ko sasi so ati sundar aanan |","meaning_en":"","page":434},{"gurmukhi":"ਖੇਲਤ ਹੈ ਰਜਨੀ ਸਿਤ ਮੈ ਜਹ ਰਾਜਤ ਥੋ ਜਮੁਨਾ ਜੁਤ ਕਾਨਨ।","roman":"Khelat hai rajnee sit mai jah raajat tho jamunaa jut kaanan |","meaning_en":"","page":434},{"gurmukhi":"ਭਾਨੁ ਸੁਤਾ ਬ੍ਰਿਖ ਕੀ ਜਹ ਥੀ ਸੁ ਹੁਤੀ ਜਹ ਚੰਦ੍ਰਭਗਾ ਅਭਿਮਾਨਨ।","roman":"Bhaanu sutaa brikh kee jah thee su hutee jah chandrabhgaa abhimaanan |","meaning_en":"","page":434},{"gurmukhi":"ਛਾਜਤ ਤਾ ਮਹਿ ਯੌ ਹਰਿ ਜੂ ਜਿਉ ਬਿਰਾਜਤ ਬੀਚ ਪੰਨਾ ਨਗ ਖਾਨਨ। ੬੩੦।","roman":"Chhaajat taa mahi yau hari joo jiu biraajat beech pannaa nag khaanan | 630 |","meaning_en":"","page":434}]},{"type":"verse","number":[631],"number_text":"੬੩੧।","page":434,"lines":[{"gurmukhi":"ਸੁ ਸੰਗੀਤ ਨਚੈ ਹਰਿ ਜੂ ਤਿਹ ਠਉਰ ਸੋ ਸ੍ਯਾਮ ਕਹੈ ਰਸ ਕੇ ਸੰਗਿ ਭੀਨੋ।","roman":"Su sangeet nachai hari joo tih thaur so syaam kahai ras ke sangi bheeno |","meaning_en":"","page":434},{"gurmukhi":"ਖੋਰ ਦਏ ਫੁਨਿ ਕੇਸਰ ਕੀ ਧੁਤੀਯਾ ਕਸਿ ਕੈ ਪਟ ਓਢਿ ਨਵੀਨੋ।","roman":"Khor dae phuni kesar kee dhuteeyaa kasi kai pat odhi naveeno |","meaning_en":"","page":434},{"gurmukhi":"ਰਾਧਿਕਾ ਚੰਦ੍ਰਭਗਾ ਮੁਖਿ ਚੰਦ ਲਏ ਜਹ ਗ੍ਵਾਰਿਨ ਥੀ ਸੰਗ ਤੀਨੋ।","roman":"Raadhikaa chandrabhgaa mukhi chand lae jah gvaarin thee sang teeno |","meaning_en":"","page":434},{"gurmukhi":"ਕਾਨ੍ਹ ਨਚਾਇ ਕੈ ਨੈਨਨ ਕੋ ਸਭ ਗੋਪਿਨ ਕੋ ਮਨੁਆ ਹਰਿ ਲੀਨੋ। ੬੩੧।","roman":"Kaanh nachaai kai nainan ko sabh gopin ko manuaa hari leeno | 631 |","meaning_en":"","page":434}]},{"type":"verse","number":[632],"number_text":"੬੩੨।","page":435,"lines":[{"gurmukhi":"ਬ੍ਰਿਖਭਾਨੁ ਸੁਤਾ ਕੀ ਬਰਾਬਰ ਮੂਰਤਿ ਸ੍ਯਾਮ ਕਹੈ ਸੁ ਨਹੀ ਘ੍ਰਿਤਚੀ ਹੈ।","roman":"Brikhbhaanu sutaa kee baraabar moorti syaam kahai su nahee ghritchee hai |","meaning_en":"","page":435},{"gurmukhi":"ਜਾ ਸਮ ਹੈ ਨਹੀ ਕਾਮ ਕੀ ਤ੍ਰੀਯਾ ਨਹੀ ਜਿਸ ਕੀ ਸਮ ਤੁਲਿ ਸਚੀ ਹੈ।","roman":"Jaa sam hai nahee kaam kee treeyaa nahee jis kee sam tuli sachee hai |","meaning_en":"","page":435},{"gurmukhi":"ਮਾਨਹੁ ਲੈ ਸਸਿ ਕੋ ਸਭ ਸਾਰ ਪ੍ਰਭਾ ਕਰਤਾਰ ਇਹੀ ਮੈ ਗਚੀ ਹੈ।","roman":"Maanhu lai sasi ko sabh saar prabhaa kartaar ihee mai gachee hai |","meaning_en":"","page":435},{"gurmukhi":"ਨੰਦ ਕੇ ਲਾਲ ਬਿਲਾਸਨ ਕੋ ਇਹ ਮੂਰਤਿ ਚਿਤ੍ਰ ਬਚਿਤ੍ਰ ਰਚੀ ਹੈ। ੬੩੨।","roman":"Nand ke laal bilaasan ko ih moorti chitr bachitr rachee hai | 632 |","meaning_en":"","page":435}]},{"type":"verse","number":[633],"number_text":"੬੩੩।","page":435,"lines":[{"gurmukhi":"ਰਾਧਿਕਾ ਚੰਦ੍ਰਭਗਾ ਮੁਖਿ ਚੰਦ੍ਰ ਸੁ ਖੇਲਤ ਹੈ ਮਿਲ ਖੇਲ ਸਬੈ।","roman":"Raadhikaa chandrabhgaa mukhi chandr su khelat hai mil khel sabai |","meaning_en":"","page":435},{"gurmukhi":"ਮਿਲਿ ਸੁੰਦਰ ਗਾਵਤ ਗੀਤ ਸਬੈ ਸੁ ਬਜਾਵਤ ਹੈ ਕਰ ਤਾਲ ਤਬੈ।","roman":"Mili sundar gaavat geet sabai su bajaavat hai kar taal tabai |","meaning_en":"","page":435},{"gurmukhi":"ਪਿਖਵੈ ਇਹ ਕੋ ਸੋਊ ਮੋਹ ਰਹੈ ਸਭ ਦੇਖਤ ਹੈ ਸੁਰ ਯਾਹਿ ਛਬੈ।","roman":"Pikhvai ih ko so'oo moh rahai sabh dekhat hai sur yaahi chhabai |","meaning_en":"","page":435},{"gurmukhi":"ਕਬਿ ਸ੍ਯਾਮ ਕਹੈ ਮੁਰਲੀ ਧਰ ਮੈਨ ਕੀ ਮੂਰਤਿ ਗੋਪਿਨ ਮਧਿ ਫਬੈ। ੬੩੩।","roman":"Kabi syaam kahai murlee dhar main kee moorti gopin madhi phabai | 633 |","meaning_en":"","page":435}]},{"type":"verse","number":[634],"number_text":"੬੩੪।","page":435,"lines":[{"gurmukhi":"ਜਿਹ ਕੀ ਸਮ ਤੁਲਿ ਨ ਹੈ ਕਮਲਾ ਦੁਤਿ ਜਾ ਪਿਖਿ ਕੈ ਕਟਿ ਕੇਹਰ ਲਾਜੈ।","roman":"Jih kee sam tuli na hai kamlaa duti jaa pikhi kai kati kehar laajai |","meaning_en":"","page":435},{"gurmukhi":"ਕੰਚਨ ਦੇਖਿ ਲਜੈ ਤਨ ਕੋ ਤਿਹ ਦੇਖਤ ਹੀ ਮਨ ਕੋ ਦੁਖੁ ਭਾਜੈ।","roman":"Kanchan dekhi lajai tan ko tih dekhat hee man ko dukhu bhaajai |","meaning_en":"","page":435},{"gurmukhi":"ਜਾ ਸਮ ਰੂਪ ਨ ਕੋਊ ਤ੍ਰੀਯਾ ਕਬਿ ਸ੍ਯਾਮ ਕਹੈ ਰਤਿ ਕੀ ਸਮ ਰਾਜੈ।","roman":"Jaa sam roop na ko'oo treeyaa kabi syaam kahai rati kee sam raajai |","meaning_en":"","page":435},{"gurmukhi":"ਜਿਉ ਘਨ ਬੀਚ ਲਸੈ ਚਪਲਾ ਇਹ ਤਿਉ ਘਨ ਗ੍ਵਾਰਿਨ ਬੀਚ ਬਿਰਾਜੈ। ੬੩੪।","roman":"Jiu ghan beech lasai chaplaa ih tiu ghan gvaarin beech biraajai | 634 |","meaning_en":"","page":435}]},{"type":"verse","number":[635],"number_text":"੬੩੫।","page":435,"lines":[{"gurmukhi":"ਖੇਲਤ ਹੈ ਸੰਗ ਤ੍ਰੀਯਨ ਕੇ ਸਜਿ ਸਾਜ ਸਭੈ ਅਰੁ ਮੋਤਿਨ ਮਾਲਾ।","roman":"Khelat hai sang treeyan ke saji saaj sabhai aru motin maalaa |","meaning_en":"","page":435},{"gurmukhi":"ਪ੍ਰੀਤਿ ਕੈ ਖੇਲਤ ਹੈ ਤਿਹ ਸੋ ਹਰਿ ਜੂ ਜੋਊ ਹੈ ਅਤਿ ਹੀ ਹਿਤ ਵਾਲਾ।","roman":"Preeti kai khelat hai tih so hari joo jo'oo hai ati hee hit vaalaa |","meaning_en":"","page":435},{"gurmukhi":"ਚੰਦ੍ਰਮੁਖੀ ਜਹ ਠਾਢੀ ਹੁਤੀ ਜਹ ਠਾਢੀ ਹੁਤੀ ਬ੍ਰਿਖਭਾਨੁ ਕੀ ਬਾਲਾ।","roman":"Chandramukhee jah thaadhee hutee jah thaadhee hutee brikhbhaanu kee baalaa |","meaning_en":"","page":435},{"gurmukhi":"ਚੰਦ੍ਰਭਗਾ ਕੋ ਮਹਾ ਮੁਖ ਸੁੰਦਰ ਗ੍ਵਾਰਿਨ ਬੀਚ ਕਰਿਯੋ ਉਜਿਯਾਲਾ। ੬੩੫।","roman":"Chandrabhgaa ko mahaa mukh sundar gvaarin beech kariyo ujiyaalaa | 635 |","meaning_en":"","page":435}]},{"type":"verse","number":[636],"number_text":"੬੩੬।","page":435,"lines":[{"gurmukhi":"ਕਾਨ੍ਹ ਕੋ ਰੂਪ ਨਿਹਾਰ ਕੈ ਸੁੰਦਰਿ ਮੋਹਿ ਰਹੀ ਤ੍ਰੀਯਾ ਚੰਦ੍ਰ ਮੁਖੀ।","roman":"Kaanh ko roop nihaar kai sundri mohi rahee treeyaa chandr mukhee |","meaning_en":"","page":435},{"gurmukhi":"ਤਬ ਗਾਇ ਉਠੀ ਕਰ ਤਾਲ ਬਜਾਇ ਹੁਤੀ ਜਿ ਕਿਧੋ ਅਤਿ ਹੀ ਸੁ ਸੁਖੀ।","roman":"Tab gaai uthee kar taal bajaai hutee ji kidho ati hee su sukhee |","meaning_en":"","page":435},{"gurmukhi":"ਕਰ ਕੈ ਅਤਿ ਹੀ ਹਿਤ ਨਾਚਤ ਭੀ ਕਰਿ ਆਨੰਦ ਨ ਮਨ ਬੀਚ ਝੁਖੀ।","roman":"Kar kai ati hee hit naachat bhee kari aanand na man beech jhukhee |","meaning_en":"","page":435},{"gurmukhi":"ਸਭ ਲਾਲਚ ਤਿਆਗ ਦਏ ਗ੍ਰਿਹ ਕੇ ਇਕ ਸ੍ਯਾਮ ਕੇ ਪ੍ਯਾਰ ਕੀ ਹੈ ਸੁ ਭੁਖੀ। ੬੩੬।","roman":"Sabh laalach tiaag dae grih ke ik syaam ke pyaar kee hai su bhukhee | 636 |","meaning_en":"","page":435}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":435},{"type":"verse","number":[637],"number_text":"੬੩੭।","page":435,"lines":[{"gurmukhi":"ਕ੍ਰਿਸਨ ਮਨੈ ਅਤਿ ਰੀਝ ਕੈ ਮੁਰਲੀ ਉਠਿਯੋ ਬਜਾਇ।","roman":"Krisan manai ati reejh kai murlee uthiyo bajaai |","meaning_en":"","page":435},{"gurmukhi":"ਰੀਝ ਰਹੀ ਸਭ ਗੋਪੀਯਾ ਮਹਾ ਪ੍ਰਮੁਦ ਮਨਿ ਪਾਇ। ੬੩੭।","roman":"Reejh rahee sabh gopeeyaa mahaa pramud mani paai | 637 |","meaning_en":"","page":435}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":435},{"type":"verse","number":[638],"number_text":"੬੩੮।","page":435,"lines":[{"gurmukhi":"ਰੀਝ ਰਹੀ ਬ੍ਰਿਜ ਕੀ ਸਭ ਭਾਮਿਨ ਜਉ ਮੁਰਲੀ ਨੰਦ ਲਾਲ ਬਜਾਈ।","roman":"Reejh rahee brij kee sabh bhaamin jau murlee nand laal bajaaee |","meaning_en":"","page":435},{"gurmukhi":"ਰੀਝ ਰਹੇ ਬਨ ਕੇ ਖਗ ਅਉ ਮ੍ਰਿਗ ਰੀਝ ਰਹੇ ਧੁਨਿ ਜਾ ਸੁਨਿ ਪਾਈ।","roman":"Reejh rahe ban ke khag au mrig reejh rahe dhuni jaa suni paaee |","meaning_en":"","page":435},{"gurmukhi":"ਚਿਤ੍ਰ ਕੀ ਹੋਇ ਗਈ ਪ੍ਰਿਤਮਾ ਸਭ ਸ੍ਯਾਮ ਕੀ ਓਰਿ ਰਹੀ ਲਿਵ ਲਾਈ।","roman":"Chitr kee hoi gaee pritmaa sabh syaam kee ori rahee liv laaee |","meaning_en":"","page":436},{"gurmukhi":"ਨੀਰ ਬਹੈ ਨਹੀ ਕਾਨ੍ਹ ਤ੍ਰੀਯਾ ਸੁਨ ਕੇ ਤਿਹ ਪਉਨ ਰਹਿਯੋ ਉਰਝਾਈ। ੬੩੮।","roman":"Neer bahai nahee kaanh treeyaa sun ke tih paun rahiyo urjhaaee | 638 |","meaning_en":"","page":436}]},{"type":"verse","number":[639],"number_text":"੬੩੯।","page":436,"lines":[{"gurmukhi":"ਪਉਨ ਰਹਿਯੋ ਉਰਝਾਇ ਘਰੀ ਇਕ ਨੀਰ ਨਦੀ ਕੋ ਚਲੈ ਸੁ ਕਛੂ ਨਾ।","roman":"Paun rahiyo urjhaai gharee ik neer nadee ko chalai su kachhoo naa |","meaning_en":"","page":436},{"gurmukhi":"ਜੇ ਬ੍ਰਿਜ ਭਾਮਨਿ ਆਈ ਹੁਤੀ ਧਰਿ ਖਾਸਨ ਅੰਗ ਬਿਖੈ ਅਰੁ ਝੂਨਾ।","roman":"Je brij bhaamni aaee hutee dhari khaasan ang bikhai aru jhoonaa |","meaning_en":"","page":436},{"gurmukhi":"ਸੋ ਸੁਨ ਕੈ ਧੁਨਿ ਬਾਸੁਰੀ ਕੀ ਤਨ ਬੀਚ ਰਹੀ ਤਿਨ ਕੇ ਸੁਧਿ ਹੂੰ ਨਾ।","roman":"So sun kai dhuni baasuree kee tan beech rahee tin ke sudhi hoon naa |","meaning_en":"","page":436},{"gurmukhi":"ਤਾ ਸੁਧਿ ਗੀ ਸੁਰ ਕੇ ਸੁਨਿ ਹੀ ਰਹਿ ਗੀ ਇਹ ਮਾਨਹੁ ਚਿਤ੍ਰ ਨਮੂਨਾ। ੬੩੯।","roman":"Taa sudhi gee sur ke suni hee rahi gee ih maanhu chitr namoonaa | 639 |","meaning_en":"","page":436}]},{"type":"verse","number":[640],"number_text":"੬੪੦।","page":436,"lines":[{"gurmukhi":"ਰੀਝਿ ਬਜਾਵਤ ਹੈ ਮੁਰਲੀ ਹਰਿ ਪੈ ਮਨ ਮੈ ਕਰਿ ਸੰਕ ਕਛੂ ਨਾ।","roman":"Reejhi bajaavat hai murlee hari pai man mai kari sank kachhoo naa |","meaning_en":"","page":436},{"gurmukhi":"ਜਾ ਕੀ ਸੁਨੇ ਧੁਨਿ ਸ੍ਰਉਨਨ ਮੈ ਕਰ ਕੈ ਖਗ ਆਵਤ ਹੈ ਬਨ ਸੂਨਾ।","roman":"Jaa kee sune dhuni sraunan mai kar kai khag aavat hai ban soonaa |","meaning_en":"","page":436},{"gurmukhi":"ਸੋ ਸੁਨਿ ਗ੍ਵਾਰਿਨ ਰੀਝ ਰਹੀ ਮਨ ਭੀਤਰ ਸੰਕ ਕਰੀ ਕਛਹੂੰ ਨਾ।","roman":"So suni gvaarin reejh rahee man bheetar sank karee kachhhoon naa |","meaning_en":"","page":436},{"gurmukhi":"ਨੈਨ ਪਸਾਰ ਰਹੀ ਪਿਖ ਕੈ ਜਿਮ ਘੰਟਕ ਹੇਰ ਬਜੇ ਮ੍ਰਿਗਿ ਮੂਨਾ। ੬੪੦।","roman":"Nain pasaar rahee pikh kai jim ghantak her baje mrigi moonaa | 640 |","meaning_en":"","page":436}]},{"type":"verse","number":[641],"number_text":"੬੪੧।","page":436,"lines":[{"gurmukhi":"ਸੁਰ ਬਾਸੁਰੀ ਕੀ ਕਬਿ ਸ੍ਯਾਮ ਕਹੈ ਮੁਖ ਕਾਨਰ ਕੇ ਅਤਿ ਹੀ ਸੁ ਰਸੀ ਹੈ।","roman":"Sur baasuree kee kabi syaam kahai mukh kaanar ke ati hee su rasee hai |","meaning_en":"","page":436},{"gurmukhi":"ਸੋਰਠਿ ਦੇਵ ਗੰਧਾਰਿ ਬਿਭਾਸ ਬਿਲਾਵਲ ਹੂੰ ਕੀ ਸੁ ਤਾਨ ਬਸੀ ਹੈ।","roman":"Sorthi dev gandhaari bibhaas bilaaval hoon kee su taan basee hai |","meaning_en":"","page":436},{"gurmukhi":"ਕੰਚਨ ਸੋ ਜਿਹ ਕੋ ਤਨ ਹੈ ਜਿਹ ਕੇ ਮੁਖ ਕੀ ਸਮ ਸੋਭ ਸਸੀ ਹੈ।","roman":"Kanchan so jih ko tan hai jih ke mukh kee sam sobh sasee hai |","meaning_en":"","page":436},{"gurmukhi":"ਤਾ ਕੈ ਬਜਾਇਬੇ ਕੌ ਸੁਨ ਕੈ ਮਤਿ ਗ੍ਵਾਰਿਨ ਕੀ ਤਿਹ ਬੀਚ ਫਸੀ ਹੈ। ੬੪੧।","roman":"Taa kai bajaaibe kau sun kai mati gvaarin kee tih beech phasee hai | 641 |","meaning_en":"","page":436}]},{"type":"verse","number":[642],"number_text":"੬੪੨।","page":436,"lines":[{"gurmukhi":"ਦੇਵ ਗੰਧਾਰਿ ਬਿਭਾਸ ਬਿਲਾਵਲ ਸਾਰੰਗ ਕੀ ਧੁਨਿ ਤਾ ਮੈ ਬਸਾਈ।","roman":"Dev gandhaari bibhaas bilaaval saarang kee dhuni taa mai basaaee |","meaning_en":"","page":436},{"gurmukhi":"ਸੋਰਠਿ ਸੁਧ ਮਲਾਰ ਕਿਧੌ ਸੁਰ ਮਾਲਸਿਰੀ ਕੀ ਮਹਾ ਸੁਖਦਾਈ।","roman":"Sorthi sudh malaar kidhau sur maalsiree kee mahaa sukhdaaee |","meaning_en":"","page":436},{"gurmukhi":"ਮੋਹਿ ਰਹੇ ਸਭ ਹੀ ਸੁਰ ਅਉ ਨਰ ਗ੍ਵਾਰਿਨ ਰੀਝ ਰਹੀ ਸੁਨਿ ਧਾਈ।","roman":"Mohi rahe sabh hee sur au nar gvaarin reejh rahee suni dhaaee |","meaning_en":"","page":436},{"gurmukhi":"ਯੌ ਉਪਜੀ ਸੁਰ ਚੇਟਕ ਕੀ ਭਗਵਾਨ ਮਨੋ ਧਰਿ ਫਾਸ ਚਲਾਈ। ੬੪੨।","roman":"Yau upjee sur chetak kee bhagvaan mano dhari phaas chalaaee | 642 |","meaning_en":"","page":436}]},{"type":"verse","number":[643],"number_text":"੬੪੩।","page":436,"lines":[{"gurmukhi":"ਆਨਨ ਹੈ ਜਿਹ ਕੋ ਅਤਿ ਸੁੰਦਰ ਕੰਧਿ ਧਰੇ ਜੋਊ ਹੈ ਪਟ ਪੀਲੋ।","roman":"Aanan hai jih ko ati sundar kandhi dhare jo'oo hai pat peelo |","meaning_en":"","page":436},{"gurmukhi":"ਜਾਹਿ ਮਰਿਯੋ ਅਘ ਨਾਮ ਬਡੋ ਰਿਪੁ ਤਾਤ ਰਖਿਯੋ ਅਹਿ ਤੇ ਜਿਨ ਲੀਲੋ।","roman":"Jaahi mariyo agh naam bado ripu taat rakhiyo ahi te jin leelo |","meaning_en":"","page":436},{"gurmukhi":"ਅਸਾਧਨ ਕੌ ਸਿਰ ਜੋ ਕਟੀਯਾ ਅਰੁ ਸਾਧਨ ਕੋ ਕਰਤਾ ਜੋਊ ਹੀਲੋ।","roman":"Asaadhan kau sir jo kateeyaa aru saadhan ko kartaa jo'oo heelo |","meaning_en":"","page":436},{"gurmukhi":"ਚੋਰ ਲਯੋ ਸੁਰ ਸੋ ਮਨ ਤਾਸ ਬਜਾਇ ਭਲੀ ਬਿਧਿ ਸਾਥ ਰਸੀਲੋ। ੬੪੩।","roman":"Chor layo sur so man taas bajaai bhalee bidhi saath raseelo | 643 |","meaning_en":"","page":436}]},{"type":"verse","number":[644],"number_text":"੬੪੪।","page":436,"lines":[{"gurmukhi":"ਜਾਹਿ ਭਭੀਛਨ ਰਾਜ ਦਯੋ ਅਰੁ ਰਾਵਨ ਜਾਹਿ ਮਰਿਯੋ ਕਰਿ ਕ੍ਰੋਹੈ।","roman":"Jaahi bhabheechhan raaj dayo aru raavan jaahi mariyo kari krohai |","meaning_en":"","page":436},{"gurmukhi":"ਚਕ੍ਰ ਕੇ ਸਾਥ ਕਿਧੋ ਜਿਨਹੂੰ ਸਿਸੁਪਾਲ ਕੋ ਸੀਸ ਕਟਿਯੋ ਕਰਿ ਛੋਹੈ।","roman":"Chakr ke saath kidho jinhoon sisupaal ko sees katiyo kari chhohai |","meaning_en":"","page":436},{"gurmukhi":"ਮੈਨ ਸੁ ਅਉ ਸੀਯ ਕੋ ਭਰਤਾ ਜਿਹ ਮੂਰਤਿ ਕੀ ਸਮਤੁਲਿ ਨ ਕੋ ਹੈ।","roman":"Main su au seey ko bhartaa jih moorti kee samtuli na ko hai |","meaning_en":"","page":437},{"gurmukhi":"ਸੋ ਕਰਿ ਲੈ ਅਪੁਨੇ ਮੁਰਲੀ ਅਬ ਸੁੰਦਰ ਗੋਪਿਨ ਕੇ ਮਨ ਮੋਹੈ। ੬੪੪।","roman":"So kari lai apune murlee ab sundar gopin ke man mohai | 644 |","meaning_en":"","page":437}]},{"type":"verse","number":[645],"number_text":"੬੪੫।","page":437,"lines":[{"gurmukhi":"ਰਾਧਿਕਾ ਚੰਦ੍ਰਭਗਾ ਮੁਖਿ ਚੰਦ ਸੁ ਖੇਲਤ ਹੈ ਮਿਲਿ ਖੇਲ ਸਬੈ।","roman":"Raadhikaa chandrabhgaa mukhi chand su khelat hai mili khel sabai |","meaning_en":"","page":437},{"gurmukhi":"ਮਿਲਿ ਸੁੰਦਰਿ ਗਾਵਤ ਗੀਤ ਭਲੇ ਸੁ ਬਜਾਵਤ ਹੈ ਕਰਤਾਲ ਤਬੈ।","roman":"Mili sundri gaavat geet bhale su bajaavat hai kartaal tabai |","meaning_en":"","page":437},{"gurmukhi":"ਫੁਨਿ ਤਿਆਗਿ ਸਭੈ ਸੁਰ ਮੰਡਲ ਕੋ ਸਭ ਕਉਤੁਕ ਦੇਖਤ ਦੇਵ ਸਬੈ।","roman":"Phuni tiaagi sabhai sur mandal ko sabh kautuk dekhat dev sabai |","meaning_en":"","page":437},{"gurmukhi":"ਅਬ ਰਾਕਸ ਮਾਰਨ ਕੀ ਸੁ ਕਥਾ ਕਛੁ ਥੋਰੀ ਅਹੈ ਸੁਨ ਲੇਹੁ ਅਬੈ। ੬੪੫।","roman":"Ab raakas maaran kee su kathaa kachhu thoree ahai sun lehu abai | 645 |","meaning_en":"","page":437}]},{"type":"verse","number":[646],"number_text":"੬੪੬।","page":437,"lines":[{"gurmukhi":"ਨਾਚਤ ਥੀ ਜਹਿ ਗ੍ਵਰਨੀਆ ਜਹ ਫੂਲ ਖਿਰੇ ਅਰੁ ਭਉਰ ਗੁੰਜਾਰੈ।","roman":"Naachat thee jahi gvarneeaa jah phool khire aru bhaur gunjaarai |","meaning_en":"","page":437},{"gurmukhi":"ਤੀਰ ਬਹੈ ਜਮੁਨਾ ਜਹ ਸੁੰਦਰਿ ਕਾਨ੍ਹ ਹਲੀ ਮਿਲਿ ਗੀਤ ਉਚਾਰੈ।","roman":"Teer bahai jamunaa jah sundri kaanh halee mili geet uchaarai |","meaning_en":"","page":437},{"gurmukhi":"ਖੇਲ ਕਰੈ ਅਤਿ ਹੀ ਹਿਤ ਸੋ ਨ ਕਛੂ ਮਨ ਭੀਤਰ ਸੰਕਹਿ ਧਾਰੈ।","roman":"Khel karai ati hee hit so na kachhoo man bheetar sankhi dhaarai |","meaning_en":"","page":437},{"gurmukhi":"ਰੀਝਿ ਕਬਿਤ ਪੜੈ ਰਸ ਕੇ ਬਹਸੈ ਦੋਊ ਆਪਸ ਮੈ ਨਹੀ ਹਾਰੈ। ੬੪੬।","roman":"Reejhi kabit parai ras ke bahsai do'oo aapas mai nahee haarai | 646 |","meaning_en":"","page":437}]},{"type":"heading","kind":"section_heading","name":"ਅਥ ਜਖਛ ਗੋਪਿਨ ਕੌ ਨਭ ਕੋ ਲੇ ਉਡਾ","gurmukhi":"ਅਥ ਜਖਛ ਗੋਪਿਨ ਕੌ ਨਭ ਕੋ ਲੇ ਉਡਾ","roman":"Ath jakhachh gopin kau nabh ko le udaa","meaning_en":"","page":437},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":437},{"type":"verse","number":[647],"number_text":"੬੪੭।","page":437,"lines":[{"gurmukhi":"ਆਵਤ ਥੋ ਇਕ ਜਖਛ ਬਡੋ ਇਹ ਰਾਸ ਕੋ ਕਉਤੁਕ ਤਾਹਿ ਬਿਲੋਕਿਯੋ।","roman":"Aavat tho ik jakhachh bado ih raas ko kautuk taahi bilokiyo |","meaning_en":"","page":437},{"gurmukhi":"ਗ੍ਵਾਰਿਨ ਦੇਖ ਕੈ ਮੈਨ ਬਢਿਯੋ ਤਿਹ ਤੇ ਤਨ ਮੈ ਨਹੀ ਰੰਚਕ ਰੋਕਿਯੋ।","roman":"Gvaarin dekh kai main badhiyo tih te tan mai nahee ranchak rokiyo |","meaning_en":"","page":437},{"gurmukhi":"ਗ੍ਵਾਰਿਨ ਲੈ ਸੁ ਚਲਿਯੋ ਨਭਿ ਕੋ ਕਿਨਹੂੰ ਤਿਹ ਭੀਤਰ ਤੇ ਨਹੀ ਟੋਕਿਯੋ।","roman":"Gvaarin lai su chaliyo nabhi ko kinhoon tih bheetar te nahee tokiyo |","meaning_en":"","page":437},{"gurmukhi":"ਜਿਉ ਮਧਿ ਭੀਤਰਿ ਲੈ ਮੁਸਲੀ ਹਰਿ ਕੇਹਰ ਹ੍ਵੈ ਮ੍ਰਿਗ ਸੋ ਰਿਪੁ ਰੋਕਿਯੋ। ੬੪੭।","roman":"Jiu madhi bheetri lai muslee hari kehar hvai mrig so ripu rokiyo | 647 |","meaning_en":"","page":437}]},{"type":"verse","number":[648],"number_text":"੬੪੮।","page":437,"lines":[{"gurmukhi":"ਜਖਛ ਕੇ ਸੰਗਿ ਕਿਧੌ ਮੁਸਲੀ ਹਰਿ ਜੁਧ ਕਰਿਯੋ ਅਤਿ ਕੋਪੁ ਸੰਭਾਰਿਯੋ।","roman":"Jakhachh ke sangi kidhau muslee hari judh kariyo ati kopu sanbhaariyo |","meaning_en":"","page":437},{"gurmukhi":"ਲੈ ਤਰੁ ਬੀਰ ਦੋਊ ਕਰ ਭੀਤਰ ਭੀਮ ਭਏ ਅਤਿ ਹੀ ਬਲ ਧਾਰਿਯੋ।","roman":"Lai taru beer do'oo kar bheetar bheem bhae ati hee bal dhaariyo |","meaning_en":"","page":437},{"gurmukhi":"ਦੈਤ ਪਛਾਰਿ ਲਯੋ ਇਹ ਭਾਤਿ ਕਬੈ ਜਸੁ ਤਾ ਛਬਿ ਐਸਿ ਉਚਾਰਿਯੋ।","roman":"Dait pachhaari layo ih bhaati kabai jasu taa chhabi aisi uchaariyo |","meaning_en":"","page":437},{"gurmukhi":"ਢੋਕੇ ਛੁਟੇ ਤੇ ਮਹਾ ਛੁਧਵਾਨ ਕਿਧੋ ਚਕਵਾ ਉਠਿ ਬਾਜਹਿੰ ਮਾਰਿਯੋ। ੬੪੮।","roman":"Dhoke chhute te mahaa chhudhvaan kidho chakvaa uthi baajhin maariyo | 648 |","meaning_en":"","page":437}]}],"ending":{"lines":[{"gurmukhi":"ਇਤਿ ਸ੍ਰੀ ਬਚਿਤ੍ਰ ਨਾਟਕ ਗ੍ਰੰਥੇ ਕ੍ਰਿਸਨਾਵਤਾਰੇ ਗੋਪਿ ਛੁਰਾਇਬੋ","roman":"Iti sree bachitr naatak granthe krisnaavtaare gopi chhuraaibo","meaning_en":"","page":437},{"gurmukhi":"ਜਖਛ ਬਧਹ ਧਿਆਇ ਸਮਾਪਤੰ।","roman":"Jakhachh badhah dhiaai samaaptan |","meaning_en":"","page":437}],"page":437}});
